INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C1','soc',5,1,'u1',1,'지형의 뜻과 종류 — 다양하게 나타나는 땅의 생김새를 지형이라고 하며, 산봉우리가 길게 이어진 산지, 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기인 하천, 하천 주변에 주로 발달한 넓고 평평한 평야, 바다와 맞닿아 모래사장·갯벌이 나타나는 해안, 둘레가 바다로 둘러싸인 섬이 있음 · 우리나라는 국토의 약 70%가 산지이고 한 나라 안에 여러 지형이 어우러져 있음 · 이름을 외우기보다 특징을 견주어 이해함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C2','soc',5,1,'u1',2,'산지의 분포와 땅의 높낮이 — 지형도는 땅의 높낮이를 색으로 나타낸 지도이고 범례를 보면 색이 뜻하는 높이를 알 수 있음(색이 진할수록 높음) · 높고 험한 산지는 북쪽과 동쪽에, 낮고 완만한 산지는 남쪽과 서쪽에 많아 우리나라 땅은 북동쪽이 높고 남서쪽이 낮음 · 서쪽에서 동쪽으로 자른 단면도에서도 동쪽으로 갈수록 높아짐',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C3','soc',5,1,'u1',3,'하천의 흐름과 평야 — 물은 언제나 높은 곳에서 낮은 곳으로 흐르므로 큰 하천은 대부분 북쪽·동쪽의 높은 곳에서 시작해 남쪽·서쪽으로 흘러 바다로 감(북동쪽이 높고 남서쪽이 낮기 때문) · 하천 주변, 특히 큰 하천 하류 주변은 대부분 200 m 미만의 낮은 땅으로 넓고 평평한 평야가 발달해 논밭이 많음 · 하천은 오랜 시간 땅을 깎아 골짜기 같은 새 지형을 만들기도 함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C4','soc',5,1,'u1',4,'세 바다의 해안 — 우리나라는 동·서·남 삼면이 바다와 맞닿아 있고 바다와 육지가 만나는 선을 해안선이라고 함 · 동해안은 해안선이 단순하고 섬이 적으며 모래사장이 넓어 해수욕장이 발달 · 서해안과 남해안은 해안선이 복잡하고 섬이 많으며(남해안 다도해) 갯벌이 발달해 해산물을 얻고 간척하기도 함 · 파도가 암석을 깎아 해안 절벽과 동굴을 만들기도 함 — 해안 모습이 다르면 사람들의 생활도 다름',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C5','soc',5,1,'u1',5,'지형이 만든 경관과 보전 — 독특하고 아름다운 지형은 관광지가 됨(산지 — 바위 봉우리와 폭포의 산·고원 목장, 하천 — 두 물줄기가 합쳐지는 강가·지평선이 보이는 평야·깊은 계곡·하천이 깎은 한반도 모양 지형, 해안 — 갯벌·해수욕장·습지·해안 절벽) · 세계 지질 공원은 지질적 가치가 뛰어난 경관을 보전하고 교육·연구에 쓰려고 국제기구가 인증하는 곳(우리나라 처음은 제주) · 지질 공원 해설사는 지질·지형·자연·역사를 엮어 알기 쉽게 설명하고 훼손되지 않게 관리함 — 보고 배우되 그대로 둠',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C6','soc',5,1,'u1',5,'국토 여행 계획 세우기 — 주제 정하기(무엇을 보고 싶은지와 까닭) → 여행 정보 누리집 등으로 여행지 조사하기(디지털 영상 지도로 모습 확인) → 지도에 여행지를 표시하고 일정 순서대로 화살표로 이어 경로 나타내기(한 지역만 갈 때는 그 지역 백지도, 동선이 너무 길지 않게) → 공유 애플리케이션으로 나누고 예절 있게 댓글 쓰기',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C7','soc',5,1,'u1',7,'독도의 위치와 중요성 — 독도는 우리나라 영토의 동쪽 끝, 동해에 있는 섬으로 행정구역은 경상북도 울릉군이고 울릉도에서 87.4 km 떨어져 맑은 날 울릉도에서 보임(예로부터 우리 영토로 인식) · 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통·군사 면에서 중요하며, 연구 가치가 크고 주변 바다에 자원이 풍부함 · 공항이 없어 동해안 항구에서 배를 타고 울릉도를 거쳐 감',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C8','soc',5,1,'u1',8,'독도의 자연환경 — 동도와 서도 두 큰 섬과 여러 바위섬으로 이루어졌고 오래전 바닷속 화산 활동으로 만들어져 독특한 지형이 많음(바위 이름은 닮은 모습에서) · 대체로 온화하나 안개가 자주 끼고 흐린 날이 많으며 겨울에 눈이 많음 · 차가운 바닷물과 따뜻한 바닷물이 만나 좋은 어장을 이루고 해양 심층수(수심 200 m 아래, 영양분 많음)와 가스 하이드레이트(불타는 얼음)가 있어 경제적 가치가 큼 · 자연환경과 생태계를 보호하려고 독도 전체를 천연기념물로 지정',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C9','soc',5,1,'u1',9,'독도에 관한 옛 지도와 기록 — 우리나라 자료: 신라 장군 이사부가 우산국을 정벌한 일, 맑은 날 두 섬이 서로 보인다는 기록, 독도가 그려진 가장 오래된 지도 「팔도총도」, 독도를 울릉군이 다스린다고 정한 대한 제국 칙령(10월 25일 독도의 날) · 다른 나라 자료: 일본 국가 문서 「돗토리번 답변서」·「태정관 지령」(일본 땅이 아님), 일본이 만든 「삼국접양지도」(조선과 같은 색), 프랑스의 「조선왕국전도」, 연합국 최고 사령관 각서 부속 지도 · 옛 지도에는 그때 사람들의 영토 인식이 담겨 영토의 역사를 보여 주는 증거 — 누가 만들었고 무엇을 말하는지 읽기',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C10','soc',5,1,'u1',10,'독도를 지키기 위한 노력 — 안용복은 일본에 건너가 울릉도와 독도가 조선 땅임을 설명했고, 홍순칠과 울릉도 청년들은 독도 의용 수비대를 만들어 지키며 바위에 「한국령」을 새겼고, 최종덕은 주민 등록을 옮겨 최초의 독도 주민이 됨 · 정부는 선착장·주민 숙소·등대를 만들고 경찰인 독도 경비대를 파견(평소처럼 다스리는 우리 땅)하며 법과 정책으로 지키고 세계에 알림, 해양 경찰은 바다를 지킴 · 개인·학교·여러 단체도 방문·잘못된 정보 바로잡기·알리기 활동을 함 — 모두 함께',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C11','soc',5,1,'u1',10,'우리 국토를 알리는 그림 만들기 — 그림으로 알리고 싶은 우리나라의 자연 경관(산지·해안·하천·독도 등)을 골라 생김새·동식물·사람·배경을 떠올려 조건을 구체적이고 자세하게 생각함(뜻이 흐린 조건은 무엇을 그릴지 정해 주지 못함) · 인공지능으로 만들고 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만듦 · 그림에 이름을 붙이고 어떤 조건으로 무엇을 표현했는지 스스로 소개함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X01','soc',5,'u1',ARRAY['SO5-1-u1-C1']::text[],'지형을 기후·인구·교통처럼 땅의 생김새가 아닌 것과 헷갈린다','지형 = 땅의 생김새') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X02','soc',5,'u1',ARRAY['SO5-1-u1-C1']::text[],'산지·하천·평야·해안·섬의 뜻을 서로 바꾸어 짝짓는다','솟은 땅·흐르는 물·평평한 땅·바다와 만나는 곳·바다에 둘러싸인 땅') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X03','soc',5,'u1',ARRAY['SO5-1-u1-C2','SO5-1-u1-C3']::text[],'우리나라 땅의 높낮이를 거꾸로(남서쪽이 높고 북동쪽이 낮다고, 또는 어디나 같다고) 안다','높은 산은 북쪽·동쪽에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X04','soc',5,'u1',ARRAY['SO5-1-u1-C2']::text[],'지형도·범례·단면도를 잘못 읽는다(색이 진하면 낮다고, 범례 대신 방위·축척을 본다 등)','범례의 색 = 높이 · 진할수록 높아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X05','soc',5,'u1',ARRAY['SO5-1-u1-C3']::text[],'하천이 낮은 곳에서 높은 곳으로, 또는 아무 방향으로나 흐른다고 여겨 큰 하천이 남서쪽으로 흐르는 까닭을 놓친다','물은 높은 곳 → 낮은 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X06','soc',5,'u1',ARRAY['SO5-1-u1-C3']::text[],'평야가 높은 산지에 있다고 여기거나 하천과 상관없이 생긴다고 여긴다','하천 주변 · 200 m 미만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X07','soc',5,'u1',ARRAY['SO5-1-u1-C4']::text[],'동해안과 서해안·남해안의 특징(해안선·섬·모래사장·갯벌)을 바꾸어 안다','동해안 — 단순·모래사장 · 서·남해안 — 복잡·섬·갯벌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X08','soc',5,'u1',ARRAY['SO5-1-u1-C4']::text[],'갯벌·모래사장·해안 절벽 같은 해안 지형과 그곳의 생활(조개 캐기·해수욕·간척 등)을 맞지 않게 짝짓는다','진흙 땅·모래·파도가 깎은 바위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X09','soc',5,'u1',ARRAY['SO5-1-u1-C5']::text[],'경관이나 관광지를 그것을 만든 지형과 맞지 않게 짝짓는다','무엇이 이 경관을 만들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X10','soc',5,'u1',ARRAY['SO5-1-u1-C5']::text[],'지질 공원·세계 지질 공원·해설사의 뜻을 오해하거나, 멋진 자연물을 기념으로 가져가도 된다고 여긴다','보전하고 알리는 곳 · 보고 배우되 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X11','soc',5,'u1',ARRAY['SO5-1-u1-C6']::text[],'국토 여행 계획의 차례(주제 → 조사 → 경로 → 공유)나 알맞은 도구(누리집·디지털 영상 지도·백지도)를 헷갈린다','주제가 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X12','soc',5,'u1',ARRAY['SO5-1-u1-C6']::text[],'온라인에서 계획서를 나눌 때 놀리거나 장난스러운 댓글도 괜찮다고 여긴다','화면 너머에도 친구가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X13','soc',5,'u1',ARRAY['SO5-1-u1-C1','SO5-1-u1-C2','SO5-1-u1-C3','SO5-1-u1-C9']::text[],'지형이나 옛 자료 공부를 이름·숫자·연도를 외우는 것으로 여겨 특징과 뜻을 읽어 내는 것을 놓친다','외우기보다 견주고 읽어 내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X14','soc',5,'u1',ARRAY['SO5-1-u1-C7']::text[],'독도의 위치(동쪽 끝·동해)·행정구역·가는 길(공항 없음, 배로 울릉도를 거쳐)을 헷갈린다','동쪽 끝 · 경상북도 울릉군 · 배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X15','soc',5,'u1',ARRAY['SO5-1-u1-C7']::text[],'독도가 중요한 까닭(영토 경계·교통과 군사·연구 가치·자원)을 놓치거나 엉뚱한 까닭(등산·농사·관광객 수)을 댄다','경계 · 교통·군사 · 연구 · 자원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X16','soc',5,'u1',ARRAY['SO5-1-u1-C8']::text[],'독도의 자연환경(화산섬·동도와 서도·기후·어장·해양 심층수와 가스 하이드레이트·천연기념물 지정 까닭)을 잘못 안다','바닷속 화산 · 두 바닷물이 만나는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X17','soc',5,'u1',ARRAY['SO5-1-u1-C9']::text[],'옛 지도와 기록이 무엇을 말하는지 놓친다(다른 나라가 만든 자료의 뜻, 누가 만든 자료인지, 영토 인식의 증거라는 점)','누가 만들었고 무엇을 말하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X18','soc',5,'u1',ARRAY['SO5-1-u1-C10']::text[],'독도를 지킨 사람과 한 일을 바꾸어 짝짓거나, 독도를 지키는 일을 정부·경비대만의 일로 여긴다','안용복·홍순칠·최종덕 · 그리고 우리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X19','soc',5,'u1',ARRAY['SO5-1-u1-C11']::text[],'그림을 만드는 조건을 흐리게 쓰거나, 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 된다고 여긴다','조건은 자세히 · 소개는 내가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#1','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'mc','auto','다양하게 나타나는 땅의 생김새를 무엇이라고 하나요?',ARRAY['SO5-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"다양하게 나타나는 땅의 생김새를 무엇이라고 하나요?","options":[{"t":"지형","correct":true},{"t":"기후","mis":"SO5-1-u1-X01"},{"t":"인구","mis":"SO5-1-u1-X01"},{"t":"교통","mis":"SO5-1-u1-X01"}],"explanation":["땅의 모습을 가리키는 말이에요.","산지·하천·평야·해안·섬이 모두 지형이에요.","기후는 날씨, 인구는 사람 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#2','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'mc','auto','산봉우리가 길게 이어져 솟아 있는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"산봉우리가 길게 이어져 솟아 있는 지형은 어느 것인가요?","options":[{"t":"산지","correct":true},{"t":"평야","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"}],"explanation":["산이 여럿 이어진 땅이에요.","이런 땅을 산지라고 해요.","우리 국토의 약 70%가 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#3','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'sa','auto','둘레가 바다로 둘러싸인 땅을 무엇이라고 하나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"sa","stem":"둘레가 바다로 둘러싸인 땅을 무엇이라고 하나요? 한 글자로 쓰세요.","answer":["섬"],"explanation":["사방이 바다예요.","배를 타야 갈 수 있어요.","이런 땅이 섬이에요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#4','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'ox','auto','하천은 낮은 곳에서 높은 곳으로 흐르는 물줄기예요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"하천은 낮은 곳에서 높은 곳으로 흐르는 물줄기예요.","answer":"X","reason_options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"물줄기는 흐르는 방향이 정해져 있지 않기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["하천은 크고 작은 물줄기예요.","물은 높은 곳에서 낮은 곳으로 흘러요.","그래서 하천도 그렇게 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#5','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'match','auto','다섯 장의 땅 카드를 보고 카드와 지형 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"다섯 장의 땅 카드를 보고 카드와 지형 이름을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"섬"},{"l":"㉯","r":"산지"},{"l":"㉰","r":"하천"},{"l":"㉱","r":"평야"}],"mis":"SO5-1-u1-X02","explanation":["㉮는 바다에 둘러싸여 있어요.","㉯는 솟아 있고, ㉰는 흘러요.","㉱는 넓고 평평해요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#6','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','다섯 장의 땅 카드에서 ㉲에 알맞은 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"다섯 장의 땅 카드에서 ㉲에 알맞은 지형은 어느 것인가요?","options":[{"t":"해안","correct":true},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"평야","mis":"SO5-1-u1-X02"},{"t":"하천","mis":"SO5-1-u1-X02"}],"explanation":["㉲는 바다와 맞닿아 있어요.","모래사장이나 갯벌이 보여요.","이곳이 해안이에요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#7','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','넓고 평평하게 펼쳐져 있으며 하천 주변에 주로 발달하는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"넓고 평평하게 펼쳐져 있으며 하천 주변에 주로 발달하는 지형은 어느 것인가요?","options":[{"t":"평야","correct":true},{"t":"산지","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"}],"explanation":["넓고 평평한 땅이에요.","물줄기 곁에 잘 생겨요.","이런 땅이 평야예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#8','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','지난여름 가족과 해수욕장에서 모래 놀이를 했다면 그곳은 어떤 지형일까요?',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"지난여름 가족과 해수욕장에서 모래 놀이를 했다면 그곳은 어떤 지형일까요?","options":[{"t":"해안","correct":true},{"t":"산지","mis":"SO5-1-u1-X08"},{"t":"평야","mis":"SO5-1-u1-X08"},{"t":"하천","mis":"SO5-1-u1-X08"}],"explanation":["해수욕장 곁에는 바다가 있어요.","모래사장은 바다와 맞닿은 곳에 생겨요.","그래서 해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#9','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'ox','auto','우리나라에는 산지·하천·평야·해안·섬이 모두 나타나요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"ox","stem":"우리나라에는 산지·하천·평야·해안·섬이 모두 나타나요.","answer":"O","reason_options":[{"t":"한 나라 안에 여러 땅의 생김새가 어우러져 있기 때문에","correct":true},{"t":"우리나라에는 산지만 있기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["우리 국토에는 여러 지형이 있어요.","높은 산부터 바닷가까지 있어요.","그래서 지형이 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#10','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',3,'mc','auto','지형을 공부하는 바른 태도가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"지형을 공부하는 바른 태도가 아닌 것은 어느 것인가요?","options":[{"t":"산맥과 하천 이름을 빠짐없이 외우는 데에만 힘쓴다","correct":true},{"t":"여러 지형의 특징을 견주어 살펴본다","mis":"SO5-1-u1-X13"},{"t":"지도나 영상 자료로 지형의 모습을 확인한다","mis":"SO5-1-u1-X13"},{"t":"우리 국토의 아름다움을 느끼며 살펴본다","mis":"SO5-1-u1-X13"}],"explanation":["외우는 것이 목표가 아니에요.","특징을 견주고 자료로 확인해요.","국토의 아름다움도 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#1','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',2,'sa','auto','산지·하천·평야·해안·섬처럼 다양하게 나타나는 땅의 생김새를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"sa","stem":"산지·하천·평야·해안·섬처럼 다양하게 나타나는 땅의 생김새를 두 글자로 무엇이라고 하나요?","answer":["지형"],"explanation":["땅 지(地) 자가 들어가요.","땅의 모양을 뜻해요.","지형이에요."],"mis":"SO5-1-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#2','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',2,'match','auto','지형과 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"지형과 그 특징을 알맞게 이으세요.","pairs":[{"l":"산지","r":"산봉우리가 길게 이어진 땅"},{"l":"하천","r":"높은 곳에서 낮은 곳으로 흐르는 물줄기"},{"l":"해안","r":"바다와 맞닿은 곳"},{"l":"섬","r":"둘레가 바다로 둘러싸인 땅"}],"mis":"SO5-1-u1-X02","explanation":["솟은 땅은 산지예요.","흐르는 물줄기는 하천이에요.","바다와 만나면 해안, 둘러싸이면 섬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#3','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'mc','auto','다섯 장의 땅 카드 가운데 ㉰와 ㉱가 서로 가까이 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X02']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"다섯 장의 땅 카드 가운데 ㉰와 ㉱가 서로 가까이 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물줄기 주변에 넓고 평평한 땅이 잘 발달하기 때문에","correct":true},{"t":"물줄기는 산봉우리 위에서만 흐르기 때문에","mis":"SO5-1-u1-X06"},{"t":"평평한 땅은 바다 한가운데에 생기기 때문에","mis":"SO5-1-u1-X06"},{"t":"두 카드는 같은 지형을 다르게 부른 것이기 때문에","mis":"SO5-1-u1-X02"}],"explanation":["㉰는 하천, ㉱는 평야예요.","평야는 하천 주변에 주로 발달해요.","그래서 둘은 가까이 있어요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#4','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'mc','auto','「배를 타고 가야 하고, 바닷가에서 갯벌도 볼 수 있다」는 여행지에서 만날 수 있는 지형을 모두 고른 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"「배를 타고 가야 하고, 바닷가에서 갯벌도 볼 수 있다」는 여행지에서 만날 수 있는 지형을 모두 고른 것은 어느 것인가요?","options":[{"t":"섬과 해안","correct":true},{"t":"산지와 평야","mis":"SO5-1-u1-X02"},{"t":"하천과 평야","mis":"SO5-1-u1-X02"},{"t":"산지와 하천","mis":"SO5-1-u1-X02"}],"explanation":["배를 타고 가는 땅은 섬이에요.","갯벌은 바다와 맞닿은 해안에 있어요.","그래서 섬과 해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#5','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'ox','auto','「높은 산에서 시작한 시원한 계곡물」을 소개하는 글은 하천과 산지를 함께 보여 주는 글이에요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"ox","stem":"「높은 산에서 시작한 시원한 계곡물」을 소개하는 글은 하천과 산지를 함께 보여 주는 글이에요.","answer":"O","reason_options":[{"t":"계곡물은 흐르는 물줄기이고 그 물이 시작하는 곳이 높은 산이기 때문에","correct":true},{"t":"계곡물은 바다와 맞닿은 해안이기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["계곡물은 하천이에요.","높은 산은 산지예요.","한 장면에 두 지형이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#6','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'error','auto','지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X01','SO5-1-u1-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"error","stem":"지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「날씨가 더운 곳과 추운 곳도 지형이 달라서 생기는 거야.」","correct":true,"mis_target":"SO5-1-u1-X01"},{"t":"하윤 — 「평야는 넓고 평평해서 논밭이 많아.」","mis":"SO5-1-u1-X02"},{"t":"도현 — 「섬은 둘레가 모두 바다야.」","mis":"SO5-1-u1-X02"}],"explanation":["더위와 추위는 기후예요.","지형은 땅의 생김새예요.","둘은 서로 다른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#7','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'mc','auto','우리나라 국토의 약 70%를 차지하는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"우리나라 국토의 약 70%를 차지하는 지형은 어느 것인가요?","options":[{"t":"산지","correct":true},{"t":"평야","mis":"SO5-1-u1-X03"},{"t":"해안","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"}],"explanation":["우리나라는 산이 많아요.","어디를 가도 산이 보여요.","국토의 약 70%가 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#8','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',4,'mc','auto','친구가 「우리 가족은 지형이 하나만 있는 곳으로 여행 갔어」라고 했어요. 친구의 말을 가장 알맞게 고쳐 준 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X01','SO5-1-u1-X13']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"mc","stem":"친구가 「우리 가족은 지형이 하나만 있는 곳으로 여행 갔어」라고 했어요. 친구의 말을 가장 알맞게 고쳐 준 것은 어느 것인가요?","options":[{"t":"한 곳에도 산·물줄기·평평한 땅·바닷가가 함께 있기 쉬우니 어떤 지형들이 보였는지 다시 떠올려 볼래?","correct":true},{"t":"지형은 한 나라에 하나씩만 있으니 맞는 말이야.","mis":"SO5-1-u1-X02"},{"t":"지형은 날씨에 따라 달라지니 날씨를 먼저 말해 줘.","mis":"SO5-1-u1-X01"},{"t":"지형은 이름만 외우면 되니 이름만 말해 줘.","mis":"SO5-1-u1-X13"}],"explanation":["여러 지형은 서로 이어져 있어요.","한 장면에 여럿이 함께 보여요.","다시 떠올려 보게 돕는 말이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#9','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',4,'mc','auto','「산지·하천·평야·해안·섬」 다섯 지형을 두 무리로 나눌 때 가장 알맞은 기준과 나눔은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"mc","stem":"「산지·하천·평야·해안·섬」 다섯 지형을 두 무리로 나눌 때 가장 알맞은 기준과 나눔은 어느 것인가요?","options":[{"t":"바다와 닿아 있는가 — (해안·섬) / (산지·하천·평야)","correct":true},{"t":"물이 흐르는가 — (하천·해안) / (산지·평야·섬)","mis":"SO5-1-u1-X02"},{"t":"사람이 사는가 — (평야) / (산지·하천·해안·섬)","mis":"SO5-1-u1-X01"},{"t":"날씨가 따뜻한가 — (해안·평야) / (산지·하천·섬)","mis":"SO5-1-u1-X01"}],"explanation":["해안은 바다와 맞닿은 곳이에요.","섬은 바다로 둘러싸여 있어요.","나머지 셋은 바다와 떨어져 있어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#10','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',4,'essay','teacher','지형이 무엇인지 쓰고, 여러분이 가 본 곳(또는 가 보고 싶은 곳) 한 곳을 골라 그곳의 지형과 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"essay","stem":"지형이 무엇인지 쓰고, 여러분이 가 본 곳(또는 가 보고 싶은 곳) 한 곳을 골라 그곳의 지형과 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 지형은 다양하게 나타나는 땅의 생김새이다. 나는 할머니 댁 근처의 넓은 들판에 가 보았다. 넓고 평평한 땅에 논이 많고 그 옆으로 강이 흘렀으므로 하천 주변에 발달한 평야라고 생각한다.","scoring_points":["지형의 뜻을 바르게 썼는가","고른 곳의 지형을 썼는가","모습(특징)을 근거로 까닭을 썼는가"]},"explanation":["지형은 땅의 생김새예요.","모습을 떠올려 지형을 골라요.","특징이 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#1','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'mc','auto','지형도에서 색이 얼마만큼의 높이를 뜻하는지 알려 주는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"지형도에서 색이 얼마만큼의 높이를 뜻하는지 알려 주는 것은 어느 것인가요?","options":[{"t":"범례","correct":true},{"t":"방위표","mis":"SO5-1-u1-X04"},{"t":"제목","mis":"SO5-1-u1-X04"},{"t":"축척","mis":"SO5-1-u1-X04"}],"explanation":["색과 뜻을 나란히 적어 둔 부분이에요.","이것을 범례라고 해요.","범례로 땅의 높이를 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#2','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'mc','auto','우리나라에서 높고 험한 산지는 주로 어느 쪽에 많나요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"우리나라에서 높고 험한 산지는 주로 어느 쪽에 많나요?","options":[{"t":"북쪽과 동쪽","correct":true},{"t":"남쪽과 서쪽","mis":"SO5-1-u1-X03"},{"t":"남쪽과 동쪽","mis":"SO5-1-u1-X03"},{"t":"북쪽과 서쪽","mis":"SO5-1-u1-X03"}],"explanation":["지형도에서 색이 진한 곳을 떠올려요.","대부분 북쪽과 동쪽이에요.","그래서 그쪽 땅이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#3','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'sa','auto','땅의 높낮이를 서로 다른 색으로 칠해 땅의 생김새를 나타낸 지도를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"sa","stem":"땅의 높낮이를 서로 다른 색으로 칠해 땅의 생김새를 나타낸 지도를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["지형도"],"explanation":["지형을 나타낸 지도예요.","높은 곳과 낮은 곳의 색이 달라요.","지형도라고 해요."],"mis":"SO5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#4','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'ox','auto','지형도에서는 색이 진할수록 땅이 높아요.',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"ox","stem":"지형도에서는 색이 진할수록 땅이 높아요.","answer":"O","reason_options":[{"t":"범례에서 진한 색이 높은 땅을 나타내도록 정해 두었기 때문에","correct":true},{"t":"진한 색은 바다를 나타내기 때문에","mis":"SO5-1-u1-X04"}],"mis":"SO5-1-u1-X04","explanation":["범례를 보면 알 수 있어요.","진한 갈색이 가장 높아요.","초록색은 낮은 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#5','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','우리나라 땅의 높낮이 특징을 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"우리나라 땅의 높낮이 특징을 바르게 말한 것은 어느 것인가요?","options":[{"t":"북동쪽이 높고 남서쪽이 낮다","correct":true},{"t":"남서쪽이 높고 북동쪽이 낮다","mis":"SO5-1-u1-X03"},{"t":"가운데가 가장 높고 가장자리는 모두 낮다","mis":"SO5-1-u1-X03"},{"t":"어디나 높이가 비슷하다","mis":"SO5-1-u1-X03"}],"explanation":["높은 산이 북쪽과 동쪽에 몰려 있어요.","낮은 산은 남쪽과 서쪽에 있어요.","그래서 북동쪽이 높고 남서쪽이 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#6','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','지형도 읽기 메모에서 가장 높은 땅은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지형도 읽기 메모에서 가장 높은 땅은 어느 것인가요?","options":[{"t":"㉠ 북쪽 땅","correct":true},{"t":"㉡ 동쪽 땅","mis":"SO5-1-u1-X04"},{"t":"㉢ 서쪽 땅","mis":"SO5-1-u1-X04"},{"t":"㉣ 남서쪽 땅","mis":"SO5-1-u1-X04"}],"explanation":["범례에서 진한 갈색이 가장 높아요.","㉠이 진한 갈색이에요.","그래서 ㉠이 가장 높아요."],"asset":{"type":"passage","lines":["범례 — 진한 갈색 2,000 m 이상 · 갈색 1,000 m 안팎","범례 — 노란색 500 m 안팎 · 초록색 200 m 미만","㉠ 북쪽 땅 — 진한 갈색","㉡ 동쪽 땅 — 갈색","㉢ 서쪽 땅 — 초록색","㉣ 남서쪽 땅 — 노란색과 초록색"],"title":"지형도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#7','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','지형도 읽기 메모에서 ㉢ 서쪽 땅의 높이로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지형도 읽기 메모에서 ㉢ 서쪽 땅의 높이로 알맞은 것은 어느 것인가요?","options":[{"t":"200 m 미만","correct":true},{"t":"2,000 m 이상","mis":"SO5-1-u1-X04"},{"t":"1,000 m 안팎","mis":"SO5-1-u1-X04"},{"t":"500 m 안팎","mis":"SO5-1-u1-X04"}],"explanation":["㉢은 초록색이에요.","범례에서 초록색을 찾아요.","초록색은 200 m 미만이에요."],"asset":{"type":"passage","lines":["범례 — 진한 갈색 2,000 m 이상 · 갈색 1,000 m 안팎","범례 — 노란색 500 m 안팎 · 초록색 200 m 미만","㉠ 북쪽 땅 — 진한 갈색","㉡ 동쪽 땅 — 갈색","㉢ 서쪽 땅 — 초록색","㉣ 남서쪽 땅 — 노란색과 초록색"],"title":"지형도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#8','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','지형도에서 산지가 어디인지 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지형도에서 산지가 어디인지 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"범례를 보고 육지 높이가 높게 칠해진 곳을 찾는다","correct":true},{"t":"바다 색이 진한 곳을 찾는다","mis":"SO5-1-u1-X04"},{"t":"글자가 많이 적힌 곳을 찾는다","mis":"SO5-1-u1-X04"},{"t":"도시 이름이 적힌 곳을 찾는다","mis":"SO5-1-u1-X04"}],"explanation":["산지는 땅이 높은 곳이에요.","범례로 높은 색을 확인해요.","그 색이 칠해진 곳이 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#9','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'ox','auto','서쪽에서 동쪽으로 자른 땅의 단면을 보면 동쪽으로 갈수록 땅이 높아져요.',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"ox","stem":"서쪽에서 동쪽으로 자른 땅의 단면을 보면 동쪽으로 갈수록 땅이 높아져요.","answer":"O","reason_options":[{"t":"높은 산이 동쪽에 몰려 있기 때문에","correct":true},{"t":"서쪽에 높은 산이 몰려 있기 때문에","mis":"SO5-1-u1-X03"}],"mis":"SO5-1-u1-X03","explanation":["단면도는 땅을 옆에서 본 모습이에요.","서쪽은 낮고 동쪽은 높아요.","높은 산이 동쪽에 많아서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#10','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',3,'error','auto','지형도 읽기 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X04','SO5-1-u1-X03']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"error","stem":"지형도 읽기 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「㉢이 가장 높아. 초록색이 제일 눈에 잘 띄거든.」","correct":true,"mis_target":"SO5-1-u1-X04"},{"t":"민호 — 「㉠과 ㉡은 높은 산이 있는 곳이야.」","mis":"SO5-1-u1-X03"},{"t":"수아 — 「㉣은 ㉠보다 낮은 땅이야.」","mis":"SO5-1-u1-X03"}],"explanation":["높이는 눈에 띄는 색이 아니라 범례로 읽어요.","초록색은 200 m 미만이에요.","㉢은 낮은 땅이에요."],"asset":{"type":"passage","lines":["범례 — 진한 갈색 2,000 m 이상 · 갈색 1,000 m 안팎","범례 — 노란색 500 m 안팎 · 초록색 200 m 미만","㉠ 북쪽 땅 — 진한 갈색","㉡ 동쪽 땅 — 갈색","㉢ 서쪽 땅 — 초록색","㉣ 남서쪽 땅 — 노란색과 초록색"],"title":"지형도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#1','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',2,'mc','auto','땅의 단면 자료에서 A(서쪽)와 B(동쪽) 가까이의 땅 높이를 견주면 어떠한가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X04']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"땅의 단면 자료에서 A(서쪽)와 B(동쪽) 가까이의 땅 높이를 견주면 어떠한가요?","options":[{"t":"B 가까이가 더 높다","correct":true},{"t":"A가 더 높다","mis":"SO5-1-u1-X03"},{"t":"높이가 같다","mis":"SO5-1-u1-X03"},{"t":"견주어 볼 수 없다","mis":"SO5-1-u1-X04"}],"explanation":["A는 0 m 가까이예요.","B 가까이는 1,000 m가 넘어요.","동쪽이 더 높아요."],"asset":{"type":"passage","lines":["A(서쪽 바닷가) — 0 m 가까이","가운데 — 낮은 언덕과 들(200 m 안팎)","B 가까이(동쪽) — 높은 산줄기(1,000 m 넘음)","B를 지나면 — 곧바로 바다"],"title":"서쪽 A에서 동쪽 B까지 자른 땅의 단면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#2','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',2,'sa','auto','지형도에서 색이나 기호가 무엇을 뜻하는지 적어 둔 부분을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"sa","stem":"지형도에서 색이나 기호가 무엇을 뜻하는지 적어 둔 부분을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["범례"],"explanation":["지도 한쪽에 있어요.","색과 높이를 짝지어 두었어요.","범례라고 해요."],"mis":"SO5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#3','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'mc','auto','땅의 단면 자료를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X04']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"땅의 단면 자료를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서쪽에는 낮은 땅이 넓고, 동쪽에는 높은 산줄기가 바다 가까이까지 솟아 있다","correct":true},{"t":"서쪽에 높은 산줄기가 있고 동쪽은 넓은 들이다","mis":"SO5-1-u1-X03"},{"t":"서쪽과 동쪽 모두 높은 산줄기만 있다","mis":"SO5-1-u1-X03"},{"t":"단면 자료로는 땅의 높낮이를 알 수 없다","mis":"SO5-1-u1-X04"}],"explanation":["A 쪽은 낮아요.","가운데는 언덕과 들이에요.","B 가까이는 높은 산줄기예요."],"asset":{"type":"passage","lines":["A(서쪽 바닷가) — 0 m 가까이","가운데 — 낮은 언덕과 들(200 m 안팎)","B 가까이(동쪽) — 높은 산줄기(1,000 m 넘음)","B를 지나면 — 곧바로 바다"],"title":"서쪽 A에서 동쪽 B까지 자른 땅의 단면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#4','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'mc','auto','지형도에서 색이 가장 진하게 칠해진 곳에 가면 볼 수 있을 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04','SO5-1-u1-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"지형도에서 색이 가장 진하게 칠해진 곳에 가면 볼 수 있을 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"험한 산봉우리가 줄지어 이어진 모습","correct":true},{"t":"넓게 펼쳐진 논밭","mis":"SO5-1-u1-X04"},{"t":"잔잔한 갯벌","mis":"SO5-1-u1-X08"},{"t":"길게 뻗은 모래사장","mis":"SO5-1-u1-X08"}],"explanation":["진한 색은 높은 땅이에요.","높은 땅에는 산지가 있어요.","험한 봉우리가 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#5','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'mc','auto','산지 지형과 관련 있는 관광지로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"산지 지형과 관련 있는 관광지로 알맞은 것은 어느 것인가요?","options":[{"t":"높은 산지에 펼쳐진 초원과 풍력 발전기가 있는 목장","correct":true},{"t":"물이 빠지면 조개를 캐는 갯벌 체험장","mis":"SO5-1-u1-X09"},{"t":"지평선이 보이는 넓은 평야","mis":"SO5-1-u1-X09"},{"t":"두 물줄기가 합쳐지는 강가 마을","mis":"SO5-1-u1-X09"}],"explanation":["목장은 높은 산지에 있어요.","바람이 세서 풍력 발전기도 있어요.","산지가 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#6','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'ox','auto','「1,000 m가 넘는 높은 산은 주로 남쪽과 서쪽에 있다」는 말은 바르게 지형도를 읽은 것이에요.',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"ox","stem":"「1,000 m가 넘는 높은 산은 주로 남쪽과 서쪽에 있다」는 말은 바르게 지형도를 읽은 것이에요.","answer":"X","reason_options":[{"t":"1,000 m가 넘는 높은 산은 주로 북쪽과 동쪽에 있기 때문에","correct":true},{"t":"높은 산은 우리나라 어디에나 똑같이 퍼져 있기 때문에","mis":"SO5-1-u1-X03"}],"mis":"SO5-1-u1-X03","explanation":["높은 산은 북쪽과 동쪽에 몰려 있어요.","남쪽과 서쪽에는 낮은 산이 많아요.","그래서 바르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#7','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'error','auto','산지를 공부하는 태도를 두고 친구들이 말했어요. 바르지 않은 친구는 누구인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X03','SO5-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"error","stem":"산지를 공부하는 태도를 두고 친구들이 말했어요. 바르지 않은 친구는 누구인가요?","options":[{"t":"은우 — 「산 이름과 높이 숫자를 모두 외우는 게 제일 중요해.」","correct":true,"mis_target":"SO5-1-u1-X13"},{"t":"예린 — 「높은 산이 어느 쪽에 몰려 있는지 견주어 봐야지.」","mis":"SO5-1-u1-X03"},{"t":"준서 — 「산지 경관을 보며 국토의 아름다움을 느껴.」","mis":"SO5-1-u1-X09"}],"explanation":["외우는 것이 목표가 아니에요.","분포를 견주어 이해해요.","아름다움도 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#8','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',4,'mc','auto','어느 학생이 「동쪽 바닷가에서 출발해 서쪽 바닷가까지 걸어간다」고 해요. 길의 높낮이 변화로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"mc","stem":"어느 학생이 「동쪽 바닷가에서 출발해 서쪽 바닷가까지 걸어간다」고 해요. 길의 높낮이 변화로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"처음에 곧 높은 산을 넘고, 서쪽으로 갈수록 점점 낮아진다","correct":true},{"t":"처음부터 끝까지 평평하다","mis":"SO5-1-u1-X03"},{"t":"처음에는 낮다가 서쪽 바닷가에서 가장 높아진다","mis":"SO5-1-u1-X03"},{"t":"처음에 넓은 들을 지나고 서쪽 끝에서 높은 산을 넘는다","mis":"SO5-1-u1-X03"}],"explanation":["동쪽은 높은 산이 바다 가까이 있어요.","서쪽으로 갈수록 낮아져요.","단면도를 거꾸로 걸어간 셈이에요."],"asset":{"type":"passage","lines":["A(서쪽 바닷가) — 0 m 가까이","가운데 — 낮은 언덕과 들(200 m 안팎)","B 가까이(동쪽) — 높은 산줄기(1,000 m 넘음)","B를 지나면 — 곧바로 바다"],"title":"서쪽 A에서 동쪽 B까지 자른 땅의 단면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#9','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',4,'mc','auto','높은 산에서 바람이 세게 부는 곳에 풍력 발전기가 많은 까닭을 지형과 관련지어 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X07','SO5-1-u1-X06']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"mc","stem":"높은 산에서 바람이 세게 부는 곳에 풍력 발전기가 많은 까닭을 지형과 관련지어 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"높은 산지는 바람을 막는 것이 적어 바람이 세게 불기 때문에","correct":true},{"t":"높은 산지는 갯벌이 넓기 때문에","mis":"SO5-1-u1-X08"},{"t":"높은 산지는 바다와 맞닿아 있기 때문에","mis":"SO5-1-u1-X07"},{"t":"높은 산지는 평평한 논밭이 넓기 때문에","mis":"SO5-1-u1-X06"}],"explanation":["높은 곳은 바람이 세요.","바람이 세면 전기를 만들기 좋아요.","지형이 경관을 만든 예예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#10','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',4,'essay','teacher','지형도와 단면도로 알 수 있는 우리나라 땅의 높낮이 특징을 쓰고, 그렇게 말할 수 있는 근거를 두 자료에서 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"essay","stem":"지형도와 단면도로 알 수 있는 우리나라 땅의 높낮이 특징을 쓰고, 그렇게 말할 수 있는 근거를 두 자료에서 하나씩 쓰세요.","answer_guide":{"answer":"예: 우리나라 땅은 북쪽과 동쪽이 높고 남쪽과 서쪽이 낮다. 지형도에서는 진한 갈색으로 칠해진 높은 산이 북쪽과 동쪽에 몰려 있다. 서쪽에서 동쪽으로 자른 단면도에서는 서쪽은 낮고 동쪽으로 갈수록 땅이 높아진다.","scoring_points":["북동쪽이 높고 남서쪽이 낮다고 썼는가","지형도에서 근거를 찾았는가","단면도에서 근거를 찾았는가"]},"explanation":["높은 산이 몰린 쪽이 높아요.","지형도는 색으로 보여요.","단면도는 옆모습으로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#1','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'mc','auto','물은 어떤 방향으로 흐르나요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"물은 어떤 방향으로 흐르나요?","options":[{"t":"높은 곳에서 낮은 곳으로","correct":true},{"t":"낮은 곳에서 높은 곳으로","mis":"SO5-1-u1-X05"},{"t":"언제나 동쪽으로","mis":"SO5-1-u1-X05"},{"t":"방향이 정해져 있지 않다","mis":"SO5-1-u1-X05"}],"explanation":["물은 아래로 흘러요.","높은 곳에서 낮은 곳으로 가요.","하천의 방향도 땅의 높낮이가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#2','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'mc','auto','우리나라의 큰 하천은 대부분 어느 쪽으로 흐르나요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"우리나라의 큰 하천은 대부분 어느 쪽으로 흐르나요?","options":[{"t":"남쪽과 서쪽","correct":true},{"t":"북쪽과 동쪽","mis":"SO5-1-u1-X05"},{"t":"북쪽과 서쪽","mis":"SO5-1-u1-X05"},{"t":"남쪽과 동쪽","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","우리나라는 남쪽과 서쪽이 낮아요.","그래서 큰 하천도 그쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#3','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'sa','auto','하천 주변에 낮고 평평하게 넓게 펼쳐진 땅을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"sa","stem":"하천 주변에 낮고 평평하게 넓게 펼쳐진 땅을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["평야"],"explanation":["넓고 평평한 땅이에요.","하천 곁에 잘 생겨요.","논밭이 많아요."],"mis":"SO5-1-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#4','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'ox','auto','하천 주변의 땅은 대부분 200 m 미만의 낮은 땅이에요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"ox","stem":"하천 주변의 땅은 대부분 200 m 미만의 낮은 땅이에요.","answer":"O","reason_options":[{"t":"물이 낮은 곳으로 모여 흐르고 그 주변에 낮고 평평한 땅이 펼쳐지기 때문에","correct":true},{"t":"하천은 높은 산꼭대기를 따라서만 흐르기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["하천은 낮은 곳으로 흘러요.","그 주변도 낮은 땅이에요.","그래서 평야가 발달해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#5','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','물길 따라가기 놀이판의 갈림길 ①에서 물이 갈 수 있는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"물길 따라가기 놀이판의 갈림길 ①에서 물이 갈 수 있는 곳은 어느 것인가요?","options":[{"t":"㉯ 800 m","correct":true},{"t":"㉮ 1,400 m","mis":"SO5-1-u1-X05"},{"t":"㉰ 1,300 m","mis":"SO5-1-u1-X05"},{"t":"세 곳 모두","mis":"SO5-1-u1-X05"}],"explanation":["출발은 1,200 m예요.","물은 더 낮은 곳으로만 가요.","1,200 m보다 낮은 곳은 ㉯뿐이에요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#6','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','물길 따라가기 놀이판의 갈림길 ③에서 물이 가장 먼저 갈 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"물길 따라가기 놀이판의 갈림길 ③에서 물이 가장 먼저 갈 곳은 어느 것인가요?","options":[{"t":"㉯ 150 m","correct":true},{"t":"㉮ 600 m","mis":"SO5-1-u1-X05"},{"t":"㉰ 350 m","mis":"SO5-1-u1-X05"},{"t":"물이 멈춘다","mis":"SO5-1-u1-X05"}],"explanation":["세 곳의 높이를 견줘요.","가장 낮은 곳이 150 m예요.","물은 가장 낮은 곳으로 흘러가요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#7','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','큰 하천이 남쪽과 서쪽으로 흐르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X05']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"큰 하천이 남쪽과 서쪽으로 흐르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 땅이 북동쪽은 높고 남서쪽은 낮기 때문에","correct":true},{"t":"남서쪽이 높고 북동쪽이 낮기 때문에","mis":"SO5-1-u1-X03"},{"t":"바닷물이 하천을 끌어당기기 때문에","mis":"SO5-1-u1-X05"},{"t":"비가 남서쪽에만 내리기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","우리나라는 남서쪽이 낮아요.","그래서 큰 하천도 남서쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#8','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','큰 하천의 아래쪽 주변에 가면 흔히 볼 수 있는 모습은 어느 것인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"큰 하천의 아래쪽 주변에 가면 흔히 볼 수 있는 모습은 어느 것인가요?","options":[{"t":"넓게 펼쳐진 논밭","correct":true},{"t":"눈 덮인 험한 봉우리","mis":"SO5-1-u1-X06"},{"t":"깎아지른 바닷가 절벽","mis":"SO5-1-u1-X08"},{"t":"바닷물이 빠진 진흙 땅","mis":"SO5-1-u1-X08"}],"explanation":["하천 아래쪽 주변은 낮고 평평해요.","그곳에 평야가 발달해요.","넓은 논밭이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#9','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'ox','auto','평야는 높은 산꼭대기에 주로 발달해요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"ox","stem":"평야는 높은 산꼭대기에 주로 발달해요.","answer":"X","reason_options":[{"t":"평야는 낮고 평평한 하천 주변에 주로 발달하기 때문에","correct":true},{"t":"높은 곳일수록 땅이 평평해지기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["산꼭대기는 높고 험해요.","평야는 낮고 평평한 땅이에요.","하천 주변에 주로 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#10','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',3,'mc','auto','물길 따라가기 놀이판에서 출발부터 갈림길 ③까지 물이 지나간 높이를 차례대로 바르게 쓴 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"물길 따라가기 놀이판에서 출발부터 갈림길 ③까지 물이 지나간 높이를 차례대로 바르게 쓴 것은 어느 것인가요?","options":[{"t":"1,200 m → 800 m → 400 m → 150 m","correct":true},{"t":"1,200 m → 1,400 m → 900 m → 600 m","mis":"SO5-1-u1-X05"},{"t":"1,200 m → 800 m → 900 m → 150 m","mis":"SO5-1-u1-X05"},{"t":"1,200 m → 1,300 m → 700 m → 350 m","mis":"SO5-1-u1-X05"}],"explanation":["갈림길마다 가장 낮은 곳을 골라요.","800 m → 400 m → 150 m예요.","물은 점점 낮아지며 바다로 가요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#1','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',2,'mc','auto','두 물줄기가 합쳐져 큰 하천을 이루는 강가 마을의 경관을 만든 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"두 물줄기가 합쳐져 큰 하천을 이루는 강가 마을의 경관을 만든 지형은 어느 것인가요?","options":[{"t":"하천","correct":true},{"t":"해안","mis":"SO5-1-u1-X09"},{"t":"섬","mis":"SO5-1-u1-X09"},{"t":"갯벌","mis":"SO5-1-u1-X09"}],"explanation":["두 물줄기가 만나는 곳이에요.","물줄기는 하천이에요.","하천이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#2','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',2,'sa','auto','크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"sa","stem":"크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["하천"],"explanation":["물이 흐르는 지형이에요.","강과 시내를 함께 이르는 말이에요.","하천이에요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#3','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'mc','auto','물길 따라가기 놀이판에서 갈림길 ②에 물이 도착했을 때, 물이 이미 지나온 곳보다 높은 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"물길 따라가기 놀이판에서 갈림길 ②에 물이 도착했을 때, 물이 이미 지나온 곳보다 높은 곳은 어느 것인가요?","options":[{"t":"㉮ 900 m","correct":true},{"t":"㉯ 700 m","mis":"SO5-1-u1-X05"},{"t":"㉰ 400 m","mis":"SO5-1-u1-X05"},{"t":"세 곳 모두 지나온 곳보다 낮다","mis":"SO5-1-u1-X05"}],"explanation":["물은 갈림길 ①에서 800 m로 왔어요.","900 m는 800 m보다 높아요.","그래서 ㉮로는 갈 수 없어요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#4','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'mc','auto','한반도를 줄여 놓은 듯한 모양의 마을 지형은 어떻게 만들어졌을까요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"한반도를 줄여 놓은 듯한 모양의 마을 지형은 어떻게 만들어졌을까요?","options":[{"t":"깊은 골짜기를 흐르는 하천이 오랜 시간 땅을 깎아 만들었다","correct":true},{"t":"바닷물이 오랫동안 드나들며 만들었다","mis":"SO5-1-u1-X09"},{"t":"사람들이 흙을 쌓아 만들었다","mis":"SO5-1-u1-X09"},{"t":"화산이 터지면서 만들어졌다","mis":"SO5-1-u1-X09"}],"explanation":["하천은 흐르면서 땅을 깎아요.","오랜 시간이 지나면 모양이 생겨요.","하천이 만든 지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#5','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'ox','auto','지평선이 보일 만큼 넓은 들판에서 농사 문화를 체험할 수 있는 곳은 하천과 관계가 있어요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"ox","stem":"지평선이 보일 만큼 넓은 들판에서 농사 문화를 체험할 수 있는 곳은 하천과 관계가 있어요.","answer":"O","reason_options":[{"t":"넓은 들판은 하천 주변에 발달한 평야이기 때문에","correct":true},{"t":"넓은 들판은 높은 산지에만 있기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["지평선이 보이는 들판은 평야예요.","평야는 하천 주변에 발달해요.","그래서 하천과 관계가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#6','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'error','auto','하천과 평야를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"error","stem":"하천과 평야를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「물은 바다를 향해 가니까 언제나 동쪽으로 흘러.」","correct":true,"mis_target":"SO5-1-u1-X05"},{"t":"나린 — 「하천 아래쪽 주변에는 논밭이 넓게 펼쳐져.」","mis":"SO5-1-u1-X06"},{"t":"시우 — 「하천이 흐르는 방향을 보면 땅의 높낮이를 알 수 있어.」","mis":"SO5-1-u1-X05"}],"explanation":["물은 동쪽이 아니라 낮은 곳으로 흘러요.","우리나라는 서쪽과 남쪽이 낮아요.","그래서 큰 하천은 서·남쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#7','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'mc','auto','깊은 골짜기를 흐르는 물과 폭포가 어우러진 계곡의 경관을 만든 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"깊은 골짜기를 흐르는 물과 폭포가 어우러진 계곡의 경관을 만든 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"골짜기를 따라 흐르는 하천","correct":true},{"t":"바다와 맞닿은 해안","mis":"SO5-1-u1-X09"},{"t":"넓고 평평한 평야","mis":"SO5-1-u1-X09"},{"t":"파도가 깎은 해안 절벽","mis":"SO5-1-u1-X09"}],"explanation":["계곡에는 물이 흘러요.","흐르는 물이 골짜기를 만들어요.","하천이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#8','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',4,'mc','auto','「하천이 흐르는 방향을 보면 땅의 높낮이를 알 수 있다」는 말의 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X13']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"mc","stem":"「하천이 흐르는 방향을 보면 땅의 높낮이를 알 수 있다」는 말의 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물은 언제나 높은 곳에서 낮은 곳으로 흐르므로, 하천이 흘러가는 쪽이 더 낮은 땅이기 때문에","correct":true},{"t":"하천은 언제나 북쪽에서 시작하기 때문에","mis":"SO5-1-u1-X05"},{"t":"하천 이름에 땅의 높이가 적혀 있기 때문에","mis":"SO5-1-u1-X13"},{"t":"하천이 흐르는 쪽이 언제나 더 높은 땅이기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","흘러가는 쪽이 더 낮아요.","그래서 방향으로 높낮이를 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#9','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',4,'mc','auto','어느 지역에서 하천이 동쪽으로 흐르고 있었어요. 이 지역의 높낮이로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"mc","stem":"어느 지역에서 하천이 동쪽으로 흐르고 있었어요. 이 지역의 높낮이로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서쪽이 동쪽보다 높다","correct":true},{"t":"동쪽이 서쪽보다 높다","mis":"SO5-1-u1-X05"},{"t":"어디나 높이가 같다","mis":"SO5-1-u1-X03"},{"t":"높낮이와 하천은 상관없다","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 쪽으로 흘러요.","동쪽으로 흐르면 동쪽이 낮아요.","그 지역은 서쪽이 더 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#10','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',4,'essay','teacher','우리나라의 큰 하천이 대부분 남쪽과 서쪽으로 흐르는 까닭을 쓰고, 하천 주변에 평야가 발달하는 까닭과 그곳에서 볼 수 있는 모습을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"essay","stem":"우리나라의 큰 하천이 대부분 남쪽과 서쪽으로 흐르는 까닭을 쓰고, 하천 주변에 평야가 발달하는 까닭과 그곳에서 볼 수 있는 모습을 쓰세요.","answer_guide":{"answer":"예: 우리나라는 북쪽과 동쪽이 높고 남쪽과 서쪽이 낮은데, 물은 높은 곳에서 낮은 곳으로 흐르므로 큰 하천도 남쪽과 서쪽으로 흐른다. 하천 주변은 대부분 200 m 미만의 낮고 평평한 땅이어서 평야가 발달하고, 그곳에서는 넓은 논밭을 볼 수 있다.","scoring_points":["땅의 높낮이로 흐르는 방향의 까닭을 썼는가","하천 주변이 낮고 평평하다고 썼는가","평야에서 볼 수 있는 모습을 썼는가"]},"explanation":["높낮이가 방향을 정해요.","하천 주변은 낮고 평평해요.","넓은 논밭이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#1','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'mc','auto','우리나라는 몇 면이 바다와 맞닿아 있나요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"우리나라는 몇 면이 바다와 맞닿아 있나요?","options":[{"t":"세 면","correct":true},{"t":"한 면","mis":"SO5-1-u1-X07"},{"t":"두 면","mis":"SO5-1-u1-X07"},{"t":"네 면","mis":"SO5-1-u1-X07"}],"explanation":["동쪽·서쪽·남쪽이 바다예요.","그래서 삼면이 바다라고 해요.","해안 지형이 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#2','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'mc','auto','해안선이 단순하고 모래사장이 넓게 펼쳐진 해안은 어느 것인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"해안선이 단순하고 모래사장이 넓게 펼쳐진 해안은 어느 것인가요?","options":[{"t":"동해안","correct":true},{"t":"서해안","mis":"SO5-1-u1-X07"},{"t":"남해안","mis":"SO5-1-u1-X07"},{"t":"서해안과 남해안","mis":"SO5-1-u1-X07"}],"explanation":["동해안은 굴곡이 적어요.","넓은 모래사장이 있어요.","해수욕장이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#3','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'sa','auto','바다와 육지가 만나는 선을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"sa","stem":"바다와 육지가 만나는 선을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["해안선"],"explanation":["바다와 땅의 경계예요.","지도에서 따라 그릴 수 있어요.","해안선이라고 해요."],"mis":"SO5-1-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#4','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'ox','auto','서해안과 남해안은 해안선이 복잡하고 섬이 많아요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"ox","stem":"서해안과 남해안은 해안선이 복잡하고 섬이 많아요.","answer":"O","reason_options":[{"t":"해안선이 들쭉날쭉하고 크고 작은 섬이 많이 흩어져 있기 때문에","correct":true},{"t":"서해안과 남해안은 해안선이 곧게 뻗어 있기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["서해안과 남해안은 굴곡이 많아요.","섬도 아주 많아요.","남해안은 다도해라고도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#5','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'match','auto','해안 특징 카드를 보고 카드와 알맞은 바다를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"match","stem":"해안 특징 카드를 보고 카드와 알맞은 바다를 이으세요.","pairs":[{"l":"㉠","r":"동해안"},{"l":"㉡","r":"서해안"},{"l":"㉢","r":"남해안"}],"mis":"SO5-1-u1-X07","explanation":["곧게 뻗은 해안선은 동해안이에요.","넓은 진흙 땅은 서해안의 갯벌이에요.","섬이 아주 많은 바다는 남해안이에요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#6','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'mc','auto','바닷물이 빠진 뒤 조개를 잡는 체험을 할 수 있는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X09']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"바닷물이 빠진 뒤 조개를 잡는 체험을 할 수 있는 곳은 어느 것인가요?","options":[{"t":"넓은 갯벌","correct":true},{"t":"넓은 모래사장","mis":"SO5-1-u1-X08"},{"t":"깎아지른 해안 절벽","mis":"SO5-1-u1-X08"},{"t":"높은 산지","mis":"SO5-1-u1-X09"}],"explanation":["갯벌은 바닷물이 드나드는 진흙 땅이에요.","물이 빠지면 드러나요.","그때 조개를 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#7','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'mc','auto','여름에 동해안의 해수욕장을 찾는 사람이 많은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"여름에 동해안의 해수욕장을 찾는 사람이 많은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓은 모래사장이 펼쳐져 있어서","correct":true},{"t":"갯벌이 넓게 발달해서","mis":"SO5-1-u1-X07"},{"t":"섬이 아주 많아서","mis":"SO5-1-u1-X07"},{"t":"해안선이 복잡해서","mis":"SO5-1-u1-X07"}],"explanation":["해수욕장은 모래사장이 있어야 해요.","동해안은 모래사장이 넓어요.","그래서 해수욕장이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#8','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'mc','auto','파도가 오랜 시간 바위를 깎아 만든 절벽과 동굴을 볼 수 있는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X09','SO5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"파도가 오랜 시간 바위를 깎아 만든 절벽과 동굴을 볼 수 있는 곳은 어느 것인가요?","options":[{"t":"해안 절벽이 있는 바닷가","correct":true},{"t":"넓은 평야","mis":"SO5-1-u1-X09"},{"t":"높은 산지","mis":"SO5-1-u1-X09"},{"t":"넓은 모래사장","mis":"SO5-1-u1-X08"}],"explanation":["파도는 바위를 깎아요.","오랜 시간이 지나면 절벽과 동굴이 생겨요.","해안이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#9','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'ox','auto','해안의 모습이 다르면 그곳 사람들의 생활도 달라져요.',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"ox","stem":"해안의 모습이 다르면 그곳 사람들의 생활도 달라져요.","answer":"O","reason_options":[{"t":"갯벌에서는 해산물을 얻고 모래사장에서는 해수욕을 하는 것처럼 지형에 맞게 생활하기 때문에","correct":true},{"t":"해안 사람들은 모두 똑같이 생활하기 때문에","mis":"SO5-1-u1-X08"}],"mis":"SO5-1-u1-X08","explanation":["갯벌이 있으면 조개를 캐요.","모래사장이 있으면 해수욕장이 생겨요.","지형에 따라 생활이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#10','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',3,'mc','auto','해안 특징 카드 가운데 서해안이나 남해안의 모습에 해당하지 않는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"해안 특징 카드 가운데 서해안이나 남해안의 모습에 해당하지 않는 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉡","mis":"SO5-1-u1-X07"},{"t":"㉤","mis":"SO5-1-u1-X08"},{"t":"㉥","mis":"SO5-1-u1-X07"}],"explanation":["㉣은 넓은 모래사장과 해수욕장이에요.","이는 동해안의 모습이에요.","나머지는 서해안·남해안의 모습이에요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#1','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',2,'sa','auto','바닷물이 드나드는 곳에 쌓인 진흙 땅으로, 물이 빠지면 조개 등을 잡을 수 있는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"sa","stem":"바닷물이 드나드는 곳에 쌓인 진흙 땅으로, 물이 빠지면 조개 등을 잡을 수 있는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["갯벌"],"explanation":["서해안에 넓게 발달했어요.","진흙 땅이에요.","갯벌이에요."],"mis":"SO5-1-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#2','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',2,'mc','auto','지질적 가치가 뛰어난 경관을 보전하고 교육·연구에 활용하려고 국제기구가 인증하는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X09']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"지질적 가치가 뛰어난 경관을 보전하고 교육·연구에 활용하려고 국제기구가 인증하는 곳은 어느 것인가요?","options":[{"t":"세계 지질 공원","correct":true},{"t":"놀이공원","mis":"SO5-1-u1-X10"},{"t":"광물을 캐는 광산","mis":"SO5-1-u1-X10"},{"t":"해수욕장","mis":"SO5-1-u1-X09"}],"explanation":["지질적 가치가 뛰어난 곳이에요.","국제기구가 인증해요.","우리나라는 제주가 처음 받았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#3','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'mc','auto','해안 특징 카드 ㉤처럼 진흙 땅을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X09']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"해안 특징 카드 ㉤처럼 진흙 땅을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?","options":[{"t":"갯벌이 넓은 서해안","correct":true},{"t":"모래사장이 넓은 동해안","mis":"SO5-1-u1-X07"},{"t":"해안선이 단순한 동해안","mis":"SO5-1-u1-X07"},{"t":"높은 산지","mis":"SO5-1-u1-X09"}],"explanation":["㉤은 갯벌을 막는 일이에요.","갯벌은 서해안에 넓어요.","이 일을 간척이라고 해요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#4','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'mc','auto','지도에서 해안선을 따라 그릴 때 동해안이 서해안보다 그리기 쉬운 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"지도에서 해안선을 따라 그릴 때 동해안이 서해안보다 그리기 쉬운 까닭은 무엇인가요?","options":[{"t":"동해안은 해안선의 굴곡이 적고 섬도 적기 때문에","correct":true},{"t":"동해안은 섬이 아주 많기 때문에","mis":"SO5-1-u1-X07"},{"t":"동해안은 해안선이 들쭉날쭉하기 때문에","mis":"SO5-1-u1-X07"},{"t":"동해안은 바다와 맞닿아 있지 않기 때문에","mis":"SO5-1-u1-X07"}],"explanation":["동해안은 곧게 뻗었어요.","섬도 적어요.","그래서 따라 그리기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#5','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'ox','auto','같은 바닷가라도 동해안과 서해안은 바닥이 모래인지 진흙인지가 다를 수 있어요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"ox","stem":"같은 바닷가라도 동해안과 서해안은 바닥이 모래인지 진흙인지가 다를 수 있어요.","answer":"O","reason_options":[{"t":"동해안은 모래사장이, 서해안은 갯벌이 넓게 발달했기 때문에","correct":true},{"t":"우리나라 바닷가는 모두 같은 모래로 되어 있기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["동해안 — 모래사장이에요.","서해안 — 갯벌이에요.","바닥이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#6','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'error','auto','해안을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"error","stem":"해안을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「동해안은 섬이 아주 많아서 다도해라고 불러.」","correct":true,"mis_target":"SO5-1-u1-X07"},{"t":"소율 — 「남해안은 섬이 많고 해안선이 복잡해.」","mis":"SO5-1-u1-X07"},{"t":"지후 — 「서해안 갯벌에서는 해산물을 얻어.」","mis":"SO5-1-u1-X08"}],"explanation":["다도해는 남해안을 부르는 말이에요.","동해안은 섬이 적어요.","그래서 하람이의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#7','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'mc','auto','넓은 갯벌과 갈대밭이 펼쳐진 습지에 사람들이 찾아가는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X09','SO5-1-u1-X08']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"넓은 갯벌과 갈대밭이 펼쳐진 습지에 사람들이 찾아가는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해안이 만든 독특하고 아름다운 경관을 보려고","correct":true},{"t":"높은 산봉우리를 오르려고","mis":"SO5-1-u1-X09"},{"t":"지평선이 보이는 논에서 농사를 지으려고","mis":"SO5-1-u1-X09"},{"t":"파도가 깎은 동굴에 들어가려고","mis":"SO5-1-u1-X08"}],"explanation":["갯벌과 갈대밭은 해안에 있어요.","독특하고 아름다워요.","그래서 관광지가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#8','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',4,'mc','auto','서핑을 하러 오는 사람이 많은 바닷가가 어느 바다에 있을지 가장 알맞게 짐작한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X07','SO5-1-u1-X09']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"mc","stem":"서핑을 하러 오는 사람이 많은 바닷가가 어느 바다에 있을지 가장 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"모래사장이 넓고 파도를 타기 좋은 바다가 탁 트인 동해안","correct":true},{"t":"물이 빠지면 진흙 땅이 넓게 드러나는 서해안","mis":"SO5-1-u1-X08"},{"t":"섬이 아주 많아 바다가 섬에 가려진 남해안","mis":"SO5-1-u1-X07"},{"t":"바다와 맞닿지 않은 산지","mis":"SO5-1-u1-X09"}],"explanation":["서핑은 모래사장과 파도가 필요해요.","동해안은 모래사장이 넓어요.","서해안은 물이 빠지면 갯벌이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#9','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',4,'mc','auto','해안 특징 카드 여섯 장을 동해안과 「서해안·남해안」 두 바구니에 나눌 때 바르게 나눈 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"mc","stem":"해안 특징 카드 여섯 장을 동해안과 「서해안·남해안」 두 바구니에 나눌 때 바르게 나눈 것은 어느 것인가요?","options":[{"t":"동해안 — ㉠·㉣ / 서해안·남해안 — ㉡·㉢·㉤·㉥","correct":true},{"t":"동해안 — ㉠·㉡ / 서해안·남해안 — ㉢·㉣·㉤·㉥","mis":"SO5-1-u1-X07"},{"t":"동해안 — ㉢·㉥ / 서해안·남해안 — ㉠·㉡·㉣·㉤","mis":"SO5-1-u1-X07"},{"t":"동해안 — ㉣·㉤ / 서해안·남해안 — ㉠·㉡·㉢·㉥","mis":"SO5-1-u1-X08"}],"explanation":["단순한 해안선과 모래사장은 동해안이에요.","갯벌·섬·간척·들쭉날쭉한 해안선은 서·남해안이에요.","두 바구니로 나눠요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#10','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',4,'essay','teacher','동해안과 서해안의 모습을 해안선과 바닷가 땅(모래사장·갯벌)으로 견주어 쓰고, 그 차이가 사람들의 생활에 어떻게 나타나는지 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"essay","stem":"동해안과 서해안의 모습을 해안선과 바닷가 땅(모래사장·갯벌)으로 견주어 쓰고, 그 차이가 사람들의 생활에 어떻게 나타나는지 하나씩 쓰세요.","answer_guide":{"answer":"예: 동해안은 해안선이 단순하고 넓은 모래사장이 펼쳐져 있다. 서해안은 해안선이 복잡하고 섬이 많으며 넓은 갯벌이 발달했다. 그래서 동해안에는 해수욕장이 많아 여름에 사람들이 해수욕을 즐기고, 서해안에서는 갯벌에서 조개 같은 해산물을 얻거나 갯벌을 막아 땅으로 쓰기도 한다.","scoring_points":["해안선을 견주었는가","모래사장과 갯벌을 바르게 짝지었는가","두 해안의 생활 모습을 썼는가"]},"explanation":["동해안 — 단순·모래사장이에요.","서해안 — 복잡·갯벌이에요.","생활도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#1','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',1,'mc','auto','국토 여행 계획을 세울 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"국토 여행 계획을 세울 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"어떤 주제로 여행할지 정한다","correct":true},{"t":"친구 계획서에 댓글을 단다","mis":"SO5-1-u1-X11"},{"t":"여행지를 화살표로 잇는다","mis":"SO5-1-u1-X11"},{"t":"계획서를 사진으로 찍어 올린다","mis":"SO5-1-u1-X11"}],"explanation":["무엇을 보러 갈지 먼저 정해요.","그래야 어디를 조사할지 알아요.","주제 → 조사 → 경로 → 공유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#2','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',1,'mc','auto','가고 싶은 여행지를 조사할 때 이용하기에 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"가고 싶은 여행지를 조사할 때 이용하기에 알맞은 것은 어느 것인가요?","options":[{"t":"여행 정보 누리집","correct":true},{"t":"학교 시간표","mis":"SO5-1-u1-X11"},{"t":"가족 앨범","mis":"SO5-1-u1-X11"},{"t":"오늘의 일기 예보","mis":"SO5-1-u1-X11"}],"explanation":["누리집에서 여행지를 찾아요.","자연과 관련 있는 곳을 살펴봐요.","지역 누리집도 찾아볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#3','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C5',1,'sa','auto','지질 공원을 안내하고 그곳의 지질·지형·자연·역사를 알기 쉽게 설명해 주는 사람을 무엇이라고 하나요? (□□ □□ □□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"sa","stem":"지질 공원을 안내하고 그곳의 지질·지형·자연·역사를 알기 쉽게 설명해 주는 사람을 무엇이라고 하나요? (□□ □□ □□□)","answer":["지질 공원 해설사","지질공원 해설사","지질공원해설사"],"explanation":["지질 공원에서 일해요.","지형과 역사를 엮어 설명해요.","지질 공원 해설사예요."],"mis":"SO5-1-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#4','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C1',1,'ox','auto','산지·하천·평야·해안처럼 다양한 땅의 생김새를 지형이라고 해요.',ARRAY['SO5-1-u1-X01']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"산지·하천·평야·해안처럼 다양한 땅의 생김새를 지형이라고 해요.","answer":"O","reason_options":[{"t":"지형은 땅의 생김새를 가리키는 말이기 때문에","correct":true},{"t":"지형은 그 지역의 날씨를 가리키는 말이기 때문에","mis":"SO5-1-u1-X01"}],"mis":"SO5-1-u1-X01","explanation":["땅의 생김새가 지형이에요.","우리 국토에는 여러 지형이 있어요.","네 갈래가 서로 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#5','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',2,'mc','auto','조사한 여행지의 실제 모습을 확대해서 자세히 살펴볼 때 쓰기 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"조사한 여행지의 실제 모습을 확대해서 자세히 살펴볼 때 쓰기 알맞은 것은 어느 것인가요?","options":[{"t":"디지털 영상 지도","correct":true},{"t":"온도계","mis":"SO5-1-u1-X11"},{"t":"줄자","mis":"SO5-1-u1-X11"},{"t":"달력","mis":"SO5-1-u1-X11"}],"explanation":["영상 지도는 실제 모습을 보여 줘요.","확대해서 볼 수 있어요.","지형의 특징을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#6','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',2,'mc','auto','하율이의 여행 계획 메모를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"하율이의 여행 계획 메모를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉯ → ㉱ → ㉰ → ㉮","correct":true},{"t":"㉱ → ㉯ → ㉰ → ㉮","mis":"SO5-1-u1-X11"},{"t":"㉮ → ㉯ → ㉱ → ㉰","mis":"SO5-1-u1-X11"},{"t":"㉯ → ㉰ → ㉮ → ㉱","mis":"SO5-1-u1-X11"}],"explanation":["주제를 먼저 정해요(㉯).","조사하고(㉱), 경로를 이어요(㉰).","마지막에 나누고 댓글을 달아요(㉮)."],"asset":{"type":"passage","lines":["㉮ 친구 계획서에 느낀 점을 댓글로 남겼다.","㉯ 「세 바다의 해안을 견주어 보고 싶다」고 주제를 정했다.","㉰ 지도에 여행지를 표시하고 일정 순서대로 화살표로 이었다.","㉱ 여행 정보 누리집과 디지털 영상 지도로 여행지를 조사했다."],"title":"하율이의 여행 계획 메모(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#7','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',2,'mc','auto','제주도 안에서만 여행할 계획이라 우리나라 전체 지도에는 경로를 그리기 어려워요. 어떻게 하면 좋을까요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"제주도 안에서만 여행할 계획이라 우리나라 전체 지도에는 경로를 그리기 어려워요. 어떻게 하면 좋을까요?","options":[{"t":"그 지역만 크게 나타낸 백지도를 이용한다","correct":true},{"t":"여행 계획을 그만둔다","mis":"SO5-1-u1-X11"},{"t":"일부러 먼 곳을 끼워 넣는다","mis":"SO5-1-u1-X11"},{"t":"지도 없이 글로만 쓴다","mis":"SO5-1-u1-X11"}],"explanation":["한 지역 안의 경로는 작아요.","그 지역만 크게 나타낸 지도가 좋아요.","백지도를 내려받아 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#8','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C3',2,'ox','auto','우리나라는 동쪽이 높고 서쪽이 낮아서 큰 하천이 대부분 남쪽과 서쪽으로 흘러가요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"ox","stem":"우리나라는 동쪽이 높고 서쪽이 낮아서 큰 하천이 대부분 남쪽과 서쪽으로 흘러가요.","answer":"O","reason_options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"하천은 땅의 높낮이와 상관없이 흐르기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["땅의 높낮이가 하천을 정해요.","물은 낮은 곳으로 흘러요.","그래서 남쪽과 서쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#9','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C5',2,'mc','auto','지질 공원 해설사가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"지질 공원 해설사가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지질 공원을 안내하고 훼손되지 않도록 관리한다","correct":true},{"t":"공원에 들어오는 사람을 모두 막는다","mis":"SO5-1-u1-X10"},{"t":"공원의 멋진 바위를 캐서 판다","mis":"SO5-1-u1-X10"},{"t":"날마다 날씨를 예보한다","mis":"SO5-1-u1-X01"}],"explanation":["해설사는 공원을 알려요.","알기 쉽게 설명해요.","공원이 망가지지 않게 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#10','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',3,'mc','auto','친구의 여행 계획서에 댓글을 쓸 때의 태도로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"친구의 여행 계획서에 댓글을 쓸 때의 태도로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"재미있으라고 친구를 놀리는 말을 남긴다","correct":true},{"t":"보고 느낀 점을 예의 있게 쓴다","mis":"SO5-1-u1-X12"},{"t":"좋아 보이는 점을 찾아 칭찬한다","mis":"SO5-1-u1-X12"},{"t":"궁금한 점을 정중하게 묻는다","mis":"SO5-1-u1-X12"}],"explanation":["온라인에서도 예절을 지켜요.","놀리는 댓글은 상처를 줘요.","느낀 점과 칭찬을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#1','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',2,'mc','auto','「동해안·서해안·남해안의 모습을 견주어 보고 싶어」라는 생각에서 나올 여행 주제로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"「동해안·서해안·남해안의 모습을 견주어 보고 싶어」라는 생각에서 나올 여행 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"세 바다의 해안 지형을 찾아가는 여행","correct":true},{"t":"높은 산지만 골라 오르는 여행","mis":"SO5-1-u1-X11"},{"t":"하천을 따라 상류에서 하류까지 내려가는 여행","mis":"SO5-1-u1-X11"},{"t":"넓은 평야에서 농사 체험을 하는 여행","mis":"SO5-1-u1-X11"}],"explanation":["주제는 보고 싶은 것에서 나와요.","세 바다를 견주고 싶어 해요.","해안 지형 여행이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#2','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',2,'sa','auto','여행 계획서에서 여행지를 지도에 표시한 뒤 일정 순서대로 무엇으로 이어 여행 경로를 나타내나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"sa","stem":"여행 계획서에서 여행지를 지도에 표시한 뒤 일정 순서대로 무엇으로 이어 여행 경로를 나타내나요? 세 글자로 쓰세요.","answer":["화살표"],"explanation":["순서를 보여 줘요.","한쪽 끝이 뾰족해요.","화살표로 이어요."],"mis":"SO5-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#3','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',3,'mc','auto','여행 경로의 순서를 정할 때 가장 알맞게 생각한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X11']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"여행 경로의 순서를 정할 때 가장 알맞게 생각한 것은 어느 것인가요?","options":[{"t":"이동 거리가 너무 길어지지 않게, 여행의 목적에 맞추어 순서를 정한다","correct":true},{"t":"이름이 가장 긴 곳부터 간다","mis":"SO5-1-u1-X13"},{"t":"가장 먼 곳끼리 번갈아 간다","mis":"SO5-1-u1-X11"},{"t":"조사하지 않은 곳을 먼저 넣는다","mis":"SO5-1-u1-X11"}],"explanation":["동선이 길면 힘들어요.","목적에 맞게 순서를 정해요.","화살표로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#4','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',3,'mc','auto','완성한 여행 계획서를 공유 애플리케이션으로 나누면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11','SO5-1-u1-X12']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"완성한 여행 계획서를 공유 애플리케이션으로 나누면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"자리에 앉아서도 친구들의 계획서를 언제든 볼 수 있다","correct":true},{"t":"여행에 드는 돈이 줄어든다","mis":"SO5-1-u1-X11"},{"t":"계획서를 고칠 수 없게 잠긴다","mis":"SO5-1-u1-X11"},{"t":"댓글은 아무렇게나 써도 된다","mis":"SO5-1-u1-X12"}],"explanation":["사진으로 찍어 올려요.","앞에 나오지 않아도 돼요.","언제든 서로의 계획을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#5','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'ox','auto','지질 공원의 멋진 바위 조각은 기념으로 조금 떼어 와 간직해도 괜찮아요.',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"ox","stem":"지질 공원의 멋진 바위 조각은 기념으로 조금 떼어 와 간직해도 괜찮아요.","answer":"X","reason_options":[{"t":"오랜 시간이 만든 단 하나뿐인 자연이라 떼어 오면 되돌릴 수 없기 때문에","correct":true},{"t":"바위는 다시 금방 자라나기 때문에","mis":"SO5-1-u1-X10"}],"mis":"SO5-1-u1-X10","explanation":["바위와 지형은 오랜 시간이 만들었어요.","떼어 오면 되돌릴 수 없어요.","눈으로 보고 마음에 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#6','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'error','auto','지질 공원 해설사의 말을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"error","stem":"지질 공원 해설사의 말을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「해설사는 지형만 설명하고 마을의 옛이야기는 다루지 않아.」","correct":true,"mis_target":"SO5-1-u1-X10"},{"t":"예준 — 「바위 줄무늬가 생긴 까닭을 알기 쉽게 설명했어.」","mis":"SO5-1-u1-X10"},{"t":"다인 — 「공원이 훼손되지 않게 지키는 일도 해.」","mis":"SO5-1-u1-X10"}],"explanation":["해설사는 지질·지형·자연·역사를 엮어요.","소금 이야기는 역사예요.","그래서 라온이의 말이 틀렸어요."],"asset":{"type":"speech","turns":[{"who":"해설사","text":"이 바위 줄무늬는 아주 오랜 시간 동안 흙과 모래가 쌓여서 생겼어요."},{"who":"해설사","text":"옛날 이 마을 사람들은 이 바위 아래에서 소금을 말렸다고 해요."},{"who":"해설사","text":"바위를 만지거나 떼어 가면 다시 되돌릴 수 없으니 눈으로만 보아 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#7','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'mc','auto','지질 공원 해설사가 되려는 사람에게 필요한 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X13']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"mc","stem":"지질 공원 해설사가 되려는 사람에게 필요한 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"공원 바위를 마음대로 가져갈 수 있는 힘","correct":true},{"t":"자연환경에 대한 꾸준한 관심","mis":"SO5-1-u1-X10"},{"t":"지질과 지형에 관한 정확한 지식","mis":"SO5-1-u1-X13"},{"t":"자연을 아끼고 사랑하는 마음","mis":"SO5-1-u1-X10"}],"explanation":["관심과 사랑하는 마음이 필요해요.","정확한 지식도 필요해요.","자연물을 가져가면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#8','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C2',4,'mc','auto','주제 ①에서 배운 내용을 하나로 잇는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"mc","stem":"주제 ①에서 배운 내용을 하나로 잇는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"땅의 높낮이 하나가 산지의 분포, 하천의 방향, 평야의 자리까지 정해 준다","correct":true},{"t":"산지·하천·평야는 서로 아무 관계가 없다","mis":"SO5-1-u1-X02"},{"t":"하천은 높낮이와 상관없이 동쪽으로 흐른다","mis":"SO5-1-u1-X05"},{"t":"평야는 높은 산지 위에 주로 펼쳐진다","mis":"SO5-1-u1-X06"}],"explanation":["높은 산은 북·동쪽이에요.","하천은 남·서쪽으로 흘러요.","하천 주변에 평야가 펼쳐져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#9','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',4,'mc','auto','「갯벌과 습지의 생물을 만나는 여행」을 주제로 정했어요. 이 주제에 가장 잘 어울리는 여행지 묶음은 어느 것인가요?',ARRAY['SO5-1-u1-X09','SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"mc","stem":"「갯벌과 습지의 생물을 만나는 여행」을 주제로 정했어요. 이 주제에 가장 잘 어울리는 여행지 묶음은 어느 것인가요?","options":[{"t":"서해안의 갯벌 체험장과 남해안의 갯벌·갈대밭 습지","correct":true},{"t":"높은 산지의 목장과 바위 봉우리 산","mis":"SO5-1-u1-X09"},{"t":"동해안의 모래 해수욕장과 서핑 바닷가","mis":"SO5-1-u1-X08"},{"t":"지평선이 보이는 평야와 두 물줄기가 합쳐지는 강가","mis":"SO5-1-u1-X09"}],"explanation":["주제에 맞는 곳을 골라요.","갯벌은 서·남해안에 발달했어요.","습지에 갈대밭도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#10','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',4,'essay','teacher','자신만의 국토 여행 주제를 하나 정해 그 까닭을 쓰고, 여행지 두 곳을 어떤 지형인지와 함께 쓴 뒤, 계획을 친구들과 나눌 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"essay","stem":"자신만의 국토 여행 주제를 하나 정해 그 까닭을 쓰고, 여행지 두 곳을 어떤 지형인지와 함께 쓴 뒤, 계획을 친구들과 나눌 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 나의 여행 주제는 「하천을 따라 내려가는 여행」이다. 물이 어디서 시작해 어디로 흘러가는지 직접 보고 싶기 때문이다. 먼저 깊은 골짜기에 물과 폭포가 어우러진 계곡(하천)에 가고, 그다음 하천 주변에 펼쳐진 넓은 평야에 가겠다. 친구들과 나눌 때는 장난스러운 댓글 대신 느낀 점과 좋은 점을 예의 있게 쓰겠다.","scoring_points":["주제와 까닭을 썼는가","여행지 두 곳과 그 지형을 맞게 썼는가","온라인 예절을 썼는가"]},"explanation":["주제가 먼저예요.","여행지의 지형을 함께 써요.","나눌 때는 예절을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#1','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'mc','auto','독도는 우리나라 영토의 어느 쪽 끝에 있는 섬인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"독도는 우리나라 영토의 어느 쪽 끝에 있는 섬인가요?","options":[{"t":"동쪽 끝","correct":true},{"t":"서쪽 끝","mis":"SO5-1-u1-X14"},{"t":"남쪽 끝","mis":"SO5-1-u1-X14"},{"t":"북쪽 끝","mis":"SO5-1-u1-X14"}],"explanation":["독도는 동해에 있어요.","우리 영토의 동쪽 끝이에요.","동쪽 경계를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#2','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'mc','auto','독도가 있는 바다는 어느 것인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"독도가 있는 바다는 어느 것인가요?","options":[{"t":"동해","correct":true},{"t":"서해","mis":"SO5-1-u1-X14"},{"t":"남해","mis":"SO5-1-u1-X14"},{"t":"호수","mis":"SO5-1-u1-X14"}],"explanation":["독도는 동쪽 끝에 있어요.","그 바다는 동해예요.","동해는 세 나라에 둘러싸여 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#3','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'sa','auto','독도의 행정구역은 경상북도 어느 군인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"sa","stem":"독도의 행정구역은 경상북도 어느 군인가요? 세 글자로 쓰세요.","answer":["울릉군"],"explanation":["가까운 큰 섬의 이름을 따요.","경상북도에 속해요.","울릉군이에요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#4','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'ox','auto','독도에는 공항이 있어서 비행기로 바로 갈 수 있어요.',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"ox","stem":"독도에는 공항이 있어서 비행기로 바로 갈 수 있어요.","answer":"X","reason_options":[{"t":"독도에는 공항이 없어 배를 타고 울릉도를 거쳐 가야 하기 때문에","correct":true},{"t":"독도는 너무 가까워 걸어서 갈 수 있기 때문에","mis":"SO5-1-u1-X14"}],"mis":"SO5-1-u1-X14","explanation":["독도에는 공항이 없어요.","동해안 항구에서 배를 타요.","울릉도를 거쳐 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#5','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','독도 가는 길 찾기에서 ①과 ③ 사이에 들르는 섬은 어디인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도 가는 길 찾기에서 ①과 ③ 사이에 들르는 섬은 어디인가요?","options":[{"t":"울릉도","correct":true},{"t":"제주도","mis":"SO5-1-u1-X14"},{"t":"강화도","mis":"SO5-1-u1-X14"},{"t":"거제도","mis":"SO5-1-u1-X14"}],"explanation":["항구에서 배를 타요.","먼저 울릉도로 가요.","울릉도에서 다시 독도로 가요."],"asset":{"type":"passage","lines":["① 우리 학교에서 버스를 타고 동해안의 항구로 간다.","② 항구에서 배를 타고 울릉도로 간다.","③ 울릉도에서 다시 배를 타고 독도에 내린다."],"title":"독도 가는 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#6','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','인터넷 지도로 독도 가는 길을 찾을 때 도착지에 넣을 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11','SO5-1-u1-X14']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"인터넷 지도로 독도 가는 길을 찾을 때 도착지에 넣을 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"독도항","correct":true},{"t":"우리 학교","mis":"SO5-1-u1-X11"},{"t":"가까운 지하철역","mis":"SO5-1-u1-X11"},{"t":"동해안의 항구","mis":"SO5-1-u1-X14"}],"explanation":["출발지는 학교나 집이에요.","도착지는 마지막 목적지예요.","독도항을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#7','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','맑은 날 울릉도에서 독도를 눈으로 볼 수 있다는 사실이 알려 주는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15','SO5-1-u1-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"맑은 날 울릉도에서 독도를 눈으로 볼 수 있다는 사실이 알려 주는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"울릉도 사람들이 오래전부터 독도를 알고 우리 영토로 여겨 왔다","correct":true},{"t":"독도와 울릉도가 땅으로 이어져 있다","mis":"SO5-1-u1-X14"},{"t":"독도에는 사람이 살 수 없다","mis":"SO5-1-u1-X15"},{"t":"독도가 울릉도보다 크다","mis":"SO5-1-u1-X16"}],"explanation":["눈에 보일 만큼 가까웠어요.","그래서 옛날부터 알고 있었어요.","예로부터 우리 영토로 여겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#8','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'ox','auto','독도는 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요해요.',ARRAY['SO5-1-u1-X15']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"ox","stem":"독도는 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요해요.","answer":"O","reason_options":[{"t":"동해를 지나는 배와 비행기를 살필 수 있는 자리에 있기 때문에","correct":true},{"t":"독도에서는 농사를 많이 지을 수 있기 때문에","mis":"SO5-1-u1-X15"}],"mis":"SO5-1-u1-X15","explanation":["독도는 동해 한가운데에 있어요.","배와 비행기를 살필 수 있어요.","교통·군사 면에서 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#9','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','독도가 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도가 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"높은 산이 많아 등산하기 좋다","correct":true},{"t":"주변 바다에 수산 자원과 천연자원이 풍부하다","mis":"SO5-1-u1-X15"},{"t":"동식물이 다양하고 지형이 독특해 연구 가치가 크다","mis":"SO5-1-u1-X15"},{"t":"우리나라 영토의 동쪽 경계를 알려 준다","mis":"SO5-1-u1-X15"}],"explanation":["독도는 영토의 경계를 알려요.","교통·군사·연구·자원 면에서 중요해요.","등산 때문에 중요한 곳이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#10','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',3,'mc','auto','다른 나라 사람이 독도에 가려면 어떻게 해야 하나요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"다른 나라 사람이 독도에 가려면 어떻게 해야 하나요?","options":[{"t":"우리나라에 들어와 우리와 같은 방법으로 배를 타고 울릉도를 거쳐 간다","correct":true},{"t":"자기 나라에서 비행기로 독도에 바로 내린다","mis":"SO5-1-u1-X14"},{"t":"어느 나라에서든 마음대로 배를 타고 바로 간다","mis":"SO5-1-u1-X14"},{"t":"다른 나라 사람은 독도에 갈 수 없다","mis":"SO5-1-u1-X15"}],"explanation":["독도는 우리 영토예요.","그래서 우리나라를 거쳐 가요.","가는 길에도 영토의 뜻이 담겨 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#1','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',2,'mc','auto','독도 안내 카드에서 독도가 교통과 군사 면에서 중요하다는 것을 알려 주는 줄은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도 안내 카드에서 독도가 교통과 군사 면에서 중요하다는 것을 알려 주는 줄은 어느 것인가요?","options":[{"t":"동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아","correct":true},{"t":"행정구역 — 경상북도 울릉군","mis":"SO5-1-u1-X15"},{"t":"공항 — 없다","mis":"SO5-1-u1-X14"},{"t":"울릉도와의 거리 — 87.4 km","mis":"SO5-1-u1-X14"}],"explanation":["세 나라가 동해를 둘러싸요.","많은 배와 비행기가 지나가요.","그래서 교통·군사 면에서 중요해요."],"asset":{"type":"passage","lines":["위치 — 우리나라 영토의 동쪽 끝, 동해","행정구역 — 경상북도 울릉군","울릉도와의 거리 — 87.4 km","맑은 날 — 울릉도 전망대에서 눈으로 보인다","공항 — 없다","동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아"],"title":"독도 안내 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#2','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',2,'sa','auto','배가 바다에서 다니는 길로, 지도에 점선으로 나타내는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"sa","stem":"배가 바다에서 다니는 길로, 지도에 점선으로 나타내는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["항로"],"explanation":["배가 다니는 길이에요.","지도에 점선으로 그려요.","항로라고 해요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#3','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'mc','auto','독도 안내 카드에서 「예로부터 독도를 우리 영토로 여겨 왔다」는 근거가 되는 줄은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"독도 안내 카드에서 「예로부터 독도를 우리 영토로 여겨 왔다」는 근거가 되는 줄은 어느 것인가요?","options":[{"t":"맑은 날 — 울릉도 전망대에서 눈으로 보인다","correct":true},{"t":"공항 — 없다","mis":"SO5-1-u1-X14"},{"t":"동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아","mis":"SO5-1-u1-X15"},{"t":"위치 — 우리나라 영토의 동쪽 끝, 동해","mis":"SO5-1-u1-X14"}],"explanation":["눈으로 보이면 존재를 알 수 있어요.","울릉도 사람들이 오래전부터 알았어요.","그래서 우리 영토로 여겼어요."],"asset":{"type":"passage","lines":["위치 — 우리나라 영토의 동쪽 끝, 동해","행정구역 — 경상북도 울릉군","울릉도와의 거리 — 87.4 km","맑은 날 — 울릉도 전망대에서 눈으로 보인다","공항 — 없다","동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아"],"title":"독도 안내 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#4','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'mc','auto','독도 주변 바다가 어업을 하는 우리 국민에게 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X16','SO5-1-u1-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"독도 주변 바다가 어업을 하는 우리 국민에게 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고기를 잡는 국민을 보호하고 배가 급할 때 대피할 수도 있기 때문에","correct":true},{"t":"독도에서는 바다에 나갈 수 없기 때문에","mis":"SO5-1-u1-X15"},{"t":"독도 주변에는 물고기가 살지 않기 때문에","mis":"SO5-1-u1-X16"},{"t":"독도에 큰 공항이 있기 때문에","mis":"SO5-1-u1-X14"}],"explanation":["독도는 바다 한가운데의 섬이에요.","어업하는 국민을 지켜 줘요.","급할 때 배가 피할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#5','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'ox','auto','독도에 가는 길을 찾을 때 항구 이름을 모두 외워야 독도까지 갈 수 있어요.',ARRAY['SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"ox","stem":"독도에 가는 길을 찾을 때 항구 이름을 모두 외워야 독도까지 갈 수 있어요.","answer":"X","reason_options":[{"t":"항구 이름보다 동해안 항구에서 배를 타고 울릉도를 거쳐 가는 방법을 이해하는 것이 중요하기 때문에","correct":true},{"t":"독도에 가는 길은 하나도 정해져 있지 않기 때문에","mis":"SO5-1-u1-X13"}],"mis":"SO5-1-u1-X13","explanation":["외우기보다 방법을 이해해요.","항구 → 울릉도 → 독도예요.","배를 타고 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#6','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'error','auto','독도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"error","stem":"독도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「독도는 우리나라 영토의 서쪽 끝에 있는 섬이야.」","correct":true,"mis_target":"SO5-1-u1-X14"},{"t":"채원 — 「독도는 경상북도 울릉군에 속해.」","mis":"SO5-1-u1-X14"},{"t":"로하 — 「독도는 우리 영토의 경계를 알려 줘.」","mis":"SO5-1-u1-X15"}],"explanation":["독도는 동쪽 끝에 있어요.","동해에 있는 섬이에요.","서쪽이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#7','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'match','auto','독도가 중요한 까닭과 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"match","stem":"독도가 중요한 까닭과 그 내용을 알맞게 이으세요.","pairs":[{"l":"영토","r":"우리 영토의 동쪽 경계를 알려 준다"},{"l":"교통·군사","r":"동해를 지나는 배와 비행기를 살필 수 있다"},{"l":"연구","r":"다양한 동식물과 독특한 지형이 있다"},{"l":"자원","r":"주변 바다에 수산 자원과 천연자원이 풍부하다"}],"mis":"SO5-1-u1-X15","explanation":["동쪽 끝이라 경계예요.","바다 한가운데라 교통·군사예요.","동식물·지형은 연구, 바다는 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#8','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',4,'mc','auto','독도 안내 카드의 「공항 — 없다」와 「독도 가는 길 찾기」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"mc","stem":"독도 안내 카드의 「공항 — 없다」와 「독도 가는 길 찾기」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"누구든 동해안 항구에서 배를 타고 울릉도를 거쳐야 하므로 독도로 가는 길이 우리나라를 지난다","correct":true},{"t":"독도에는 아무도 갈 수 없다","mis":"SO5-1-u1-X14"},{"t":"독도는 일본 쪽에서만 갈 수 있다","mis":"SO5-1-u1-X14"},{"t":"독도는 비행기로 가는 것이 가장 빠르다","mis":"SO5-1-u1-X14"}],"explanation":["공항이 없어 배를 타요.","항구 → 울릉도 → 독도예요.","가는 길이 우리나라를 지나요."],"asset":{"type":"passage","lines":["① 우리 학교에서 버스를 타고 동해안의 항구로 간다.","② 항구에서 배를 타고 울릉도로 간다.","③ 울릉도에서 다시 배를 타고 독도에 내린다."],"title":"독도 가는 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#9','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',4,'mc','auto','독도가 「동해를 지나는 배와 비행기를 살필 수 있는 최전방」이라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"mc","stem":"독도가 「동해를 지나는 배와 비행기를 살필 수 있는 최전방」이라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 가장 동쪽 바다 위에서 먼저 살피고 지키는 자리라는 뜻","correct":true},{"t":"사람이 가장 많이 사는 곳이라는 뜻","mis":"SO5-1-u1-X15"},{"t":"비행기가 내리는 큰 공항이라는 뜻","mis":"SO5-1-u1-X14"},{"t":"관광객이 가장 많이 찾는 곳이라는 뜻","mis":"SO5-1-u1-X15"}],"explanation":["최전방은 맨 앞이에요.","독도는 동쪽 맨 끝이에요.","먼저 살피고 지키는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#10','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',4,'essay','teacher','독도의 위치를 쓰고, 독도가 중요한 까닭을 두 가지 쓴 뒤, 우리 학교에서 독도까지 가는 길을 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"essay","stem":"독도의 위치를 쓰고, 독도가 중요한 까닭을 두 가지 쓴 뒤, 우리 학교에서 독도까지 가는 길을 차례대로 쓰세요.","answer_guide":{"answer":"예: 독도는 우리나라 영토의 동쪽 끝, 동해에 있는 섬이고 행정구역은 경상북도 울릉군이다. 독도는 우리 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요하다. 학교에서 동해안의 항구로 간 다음, 배를 타고 울릉도로 가서 다시 배를 타고 독도에 간다.","scoring_points":["위치를 바르게 썼는가","중요한 까닭을 두 가지 썼는가","항구 → 울릉도 → 독도의 차례를 썼는가"]},"explanation":["동쪽 끝·동해예요.","경계·교통·군사·연구·자원이에요.","배로 울릉도를 거쳐 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#1','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'mc','auto','독도를 이루는 두 개의 큰 섬은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"mc","stem":"독도를 이루는 두 개의 큰 섬은 어느 것인가요?","options":[{"t":"동도와 서도","correct":true},{"t":"남도와 북도","mis":"SO5-1-u1-X16"},{"t":"큰섬과 작은섬","mis":"SO5-1-u1-X16"},{"t":"본섬과 끝섬","mis":"SO5-1-u1-X16"}],"explanation":["동쪽 섬과 서쪽 섬이에요.","동도와 서도라고 해요.","주변에 바위섬도 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#2','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'mc','auto','독도는 오래전 바닷속에서 일어난 무슨 활동으로 만들어졌나요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"mc","stem":"독도는 오래전 바닷속에서 일어난 무슨 활동으로 만들어졌나요?","options":[{"t":"화산 활동","correct":true},{"t":"빙하 활동","mis":"SO5-1-u1-X16"},{"t":"바람의 활동","mis":"SO5-1-u1-X16"},{"t":"사람의 공사","mis":"SO5-1-u1-X16"}],"explanation":["바닷속에서 화산이 터졌어요.","그래서 독도가 생겼어요.","독특한 지형이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#3','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'sa','auto','자연환경과 생태계를 보호하려고 우리나라가 독도 전체를 무엇으로 지정했나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"sa","stem":"자연환경과 생태계를 보호하려고 우리나라가 독도 전체를 무엇으로 지정했나요? 다섯 글자로 쓰세요.","answer":["천연기념물"],"explanation":["자연을 보호하는 이름이에요.","바위 하나가 아니라 섬 전체예요.","천연기념물이에요."],"mis":"SO5-1-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#4','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'ox','auto','독도 주변 바다는 차가운 바닷물과 따뜻한 바닷물이 만나 좋은 어장을 이뤄요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"ox","stem":"독도 주변 바다는 차가운 바닷물과 따뜻한 바닷물이 만나 좋은 어장을 이뤄요.","answer":"O","reason_options":[{"t":"두 바닷물이 만나는 곳에 여러 해양 생물이 살기 좋기 때문에","correct":true},{"t":"독도 주변 바다에는 바닷물이 흐르지 않기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["차가운 물과 따뜻한 물이 만나요.","해양 생물이 살기 좋아요.","그래서 좋은 어장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#5','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','독도의 날씨를 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"독도의 날씨를 바르게 말한 것은 어느 것인가요?","options":[{"t":"대체로 온화하지만 안개가 자주 끼고 흐린 날이 많다","correct":true},{"t":"일 년 내내 눈이 쌓여 있다","mis":"SO5-1-u1-X16"},{"t":"비가 한 방울도 오지 않는다","mis":"SO5-1-u1-X16"},{"t":"여름에만 바람이 분다","mis":"SO5-1-u1-X16"}],"explanation":["독도는 대체로 온화해요.","바다 한가운데라 안개가 잦아요.","겨울에는 눈이 많이 내려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#6','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','「불타는 얼음」이라고도 불리며 미래 에너지 자원으로 주목받는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"「불타는 얼음」이라고도 불리며 미래 에너지 자원으로 주목받는 것은 어느 것인가요?","options":[{"t":"가스 하이드레이트","correct":true},{"t":"해양 심층수","mis":"SO5-1-u1-X16"},{"t":"해조류","mis":"SO5-1-u1-X16"},{"t":"바닷모래","mis":"SO5-1-u1-X16"}],"explanation":["고체로 된 천연가스예요.","바다 밑바닥에 묻혀 있어요.","가스 하이드레이트예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#7','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','해양 심층수를 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"해양 심층수를 바르게 말한 것은 어느 것인가요?","options":[{"t":"수심 200 m 아래의 바닷물로 영양분이 많아 음료·식품 등에 쓰인다","correct":true},{"t":"바다 위에 떠 있는 얼음이다","mis":"SO5-1-u1-X16"},{"t":"바닷가의 모래를 뜻한다","mis":"SO5-1-u1-X16"},{"t":"바닷물이 얼어붙은 것이다","mis":"SO5-1-u1-X16"}],"explanation":["깊은 바다의 물이에요.","수심 200 m 아래예요.","영양분이 많아 여러 곳에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#8','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'ox','auto','독도 바위의 이름은 그 바위가 닮은 모습에서 온 것이 많아요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"ox","stem":"독도 바위의 이름은 그 바위가 닮은 모습에서 온 것이 많아요.","answer":"O","reason_options":[{"t":"물속에 코를 넣은 코끼리를 닮은 바위를 코끼리바위라고 부르는 것처럼 모양을 보고 이름을 지었기 때문에","correct":true},{"t":"바위 이름은 바위를 찾은 사람의 이름을 그대로 붙였기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["바위마다 닮은 모습이 있어요.","코끼리·촛대·한반도 모양이에요.","모양에서 이름이 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#9','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','독도 자연 카드에서 독도의 경제적 가치를 보여 주는 줄을 모두 고른 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"독도 자연 카드에서 독도의 경제적 가치를 보여 주는 줄을 모두 고른 것은 어느 것인가요?","options":[{"t":"바다(좋은 어장)와 깊은 바다(해양 심층수·가스 하이드레이트)","correct":true},{"t":"생김새와 날씨","mis":"SO5-1-u1-X16"},{"t":"만들어진 까닭과 보호","mis":"SO5-1-u1-X16"},{"t":"날씨와 보호","mis":"SO5-1-u1-X16"}],"explanation":["어장에서 물고기를 잡아요.","해양 심층수와 가스 하이드레이트는 자원이에요.","이것이 경제적 가치예요."],"asset":{"type":"passage","lines":["생김새 — 큰 섬 둘(동도·서도)과 크고 작은 바위섬","만들어진 까닭 — 오래전 바닷속 화산 활동","날씨 — 대체로 온화하나 안개가 잦고 흐린 날이 많다","바다 — 차가운 물과 따뜻한 물이 만나는 좋은 어장","깊은 바다 — 해양 심층수 · 바다 밑 — 가스 하이드레이트","보호 — 독도 전체를 천연기념물로 지정"],"title":"독도 자연 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#10','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',3,'mc','auto','우리나라가 독도 전체를 천연기념물로 지정한 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"우리나라가 독도 전체를 천연기념물로 지정한 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"관광객을 더 많이 오게 하려고","correct":true},{"t":"다양한 동식물이 살고 있어서","mis":"SO5-1-u1-X16"},{"t":"화산섬이라 연구 가치가 커서","mis":"SO5-1-u1-X16"},{"t":"독특한 지형과 아름다운 경관을 지녀서","mis":"SO5-1-u1-X16"}],"explanation":["천연기념물은 보호하려고 정해요.","동식물·연구 가치·경관 때문이에요.","사람을 부르려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#1','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',2,'sa','auto','독도 주변 깊은 바다에 있는 수심 200 m 아래의 바닷물로, 영양분이 많은 것을 무엇이라고 하나요? (□□ □□□)','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"sa","stem":"독도 주변 깊은 바다에 있는 수심 200 m 아래의 바닷물로, 영양분이 많은 것을 무엇이라고 하나요? (□□ □□□)","answer":["해양 심층수","해양심층수"],"explanation":["깊은 곳의 물이에요.","영양분이 많아요.","해양 심층수예요."],"mis":"SO5-1-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#2','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',2,'match','auto','독도의 바위와 이름이 온 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"match","stem":"독도의 바위와 이름이 온 모습을 알맞게 이으세요.","pairs":[{"l":"코끼리바위","r":"물속에 코를 넣은 코끼리"},{"l":"촛대바위","r":"바다에 솟은 촛대"},{"l":"탕건봉","r":"옛 선비가 갓 아래 받쳐 쓰던 탕건"},{"l":"한반도바위","r":"우리나라 땅 모양"}],"mis":"SO5-1-u1-X16","explanation":["바위는 닮은 모습으로 불려요.","코끼리·촛대·탕건 모양이 있어요.","한반도 모양 바위도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#3','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'mc','auto','독도에 독특한 지형과 아름다운 경관이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X06','SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도에 독특한 지형과 아름다운 경관이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바닷속 화산 활동으로 만들어진 섬이기 때문에","correct":true},{"t":"사람들이 바위를 깎아 꾸몄기 때문에","mis":"SO5-1-u1-X16"},{"t":"넓은 평야가 펼쳐져 있기 때문에","mis":"SO5-1-u1-X06"},{"t":"큰 하천이 섬 가운데를 흐르기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["독도는 화산섬이에요.","화산이 독특한 지형을 만들었어요.","그래서 경관이 아름다워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#4','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'mc','auto','독도 자연 카드의 「보호」 줄에서 바위 하나나 새 한 종이 아니라 「독도 전체」를 지정한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도 자연 카드의 「보호」 줄에서 바위 하나나 새 한 종이 아니라 「독도 전체」를 지정한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바위·새·식물·바다 생물이 함께 어우러진 생태계 전체를 지키려고","correct":true},{"t":"독도에는 바위 하나밖에 없어서","mis":"SO5-1-u1-X16"},{"t":"사람이 더 많이 찾아오게 하려고","mis":"SO5-1-u1-X16"},{"t":"새는 보호할 필요가 없어서","mis":"SO5-1-u1-X16"}],"explanation":["독도의 생물은 서로 이어져 있어요.","한 가지만 지키면 생태계가 무너져요.","그래서 전체를 지정했어요."],"asset":{"type":"passage","lines":["생김새 — 큰 섬 둘(동도·서도)과 크고 작은 바위섬","만들어진 까닭 — 오래전 바닷속 화산 활동","날씨 — 대체로 온화하나 안개가 잦고 흐린 날이 많다","바다 — 차가운 물과 따뜻한 물이 만나는 좋은 어장","깊은 바다 — 해양 심층수 · 바다 밑 — 가스 하이드레이트","보호 — 독도 전체를 천연기념물로 지정"],"title":"독도 자연 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#5','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'ox','auto','독도는 바다 한가운데에 있어서 안개가 자주 끼고 흐린 날이 많아요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"ox","stem":"독도는 바다 한가운데에 있어서 안개가 자주 끼고 흐린 날이 많아요.","answer":"O","reason_options":[{"t":"사방이 바다라 바다에서 올라온 물기로 안개가 자주 생기기 때문에","correct":true},{"t":"독도는 높은 산 위에 있어서 늘 맑기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["독도는 바다로 둘러싸여 있어요.","안개가 자주 끼어요.","흐린 날이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#6','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'error','auto','독도의 자연환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"error","stem":"독도의 자연환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「독도는 땅이 넓고 평평해서 큰 목장이 있어.」","correct":true,"mis_target":"SO5-1-u1-X16"},{"t":"도윤 — 「괭이갈매기 같은 새가 살아.」","mis":"SO5-1-u1-X16"},{"t":"세아 — 「바위에 사철나무와 해국 같은 식물이 자라.」","mis":"SO5-1-u1-X16"}],"explanation":["독도는 바위섬이에요.","넓은 목장은 없어요.","새와 바위 식물이 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#7','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'mc','auto','독도 주변 바다에 물고기가 많이 모이는 까닭과 가장 관계 깊은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도 주변 바다에 물고기가 많이 모이는 까닭과 가장 관계 깊은 것은 어느 것인가요?","options":[{"t":"차가운 바닷물과 따뜻한 바닷물이 만난다","correct":true},{"t":"바닷물이 아주 얕다","mis":"SO5-1-u1-X16"},{"t":"바다에 공항이 있다","mis":"SO5-1-u1-X14"},{"t":"파도가 전혀 치지 않는다","mis":"SO5-1-u1-X16"}],"explanation":["두 바닷물이 만나요.","먹이가 많아 물고기가 모여요.","좋은 어장이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#8','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',4,'mc','auto','독도 자연 카드의 여섯 줄을 「자연의 모습」과 「쓸모(가치)」로 나눌 때 「쓸모」에 들어갈 줄로만 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"mc","stem":"독도 자연 카드의 여섯 줄을 「자연의 모습」과 「쓸모(가치)」로 나눌 때 「쓸모」에 들어갈 줄로만 묶은 것은 어느 것인가요?","options":[{"t":"바다(어장) · 깊은 바다(해양 심층수·가스 하이드레이트)","correct":true},{"t":"생김새 · 만들어진 까닭","mis":"SO5-1-u1-X16"},{"t":"날씨 · 생김새","mis":"SO5-1-u1-X16"},{"t":"만들어진 까닭 · 날씨","mis":"SO5-1-u1-X16"}],"explanation":["생김새·까닭·날씨는 모습이에요.","어장과 자원은 쓸모예요.","보호는 지키는 일이에요."],"asset":{"type":"passage","lines":["생김새 — 큰 섬 둘(동도·서도)과 크고 작은 바위섬","만들어진 까닭 — 오래전 바닷속 화산 활동","날씨 — 대체로 온화하나 안개가 잦고 흐린 날이 많다","바다 — 차가운 물과 따뜻한 물이 만나는 좋은 어장","깊은 바다 — 해양 심층수 · 바다 밑 — 가스 하이드레이트","보호 — 독도 전체를 천연기념물로 지정"],"title":"독도 자연 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#9','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',4,'mc','auto','「독도는 화산섬이라 연구 가치가 크다」는 말을 가장 알맞게 풀어 쓴 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X14','SO5-1-u1-X10']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"mc","stem":"「독도는 화산섬이라 연구 가치가 크다」는 말을 가장 알맞게 풀어 쓴 것은 어느 것인가요?","options":[{"t":"바닷속 화산이 만든 지형과 그 위에 자리 잡은 생물을 살피면 땅과 생물의 오랜 변화를 알아낼 수 있다","correct":true},{"t":"화산섬이라 사람이 살기에 가장 편하다","mis":"SO5-1-u1-X16"},{"t":"화산섬이라 큰 공항을 짓기 좋다","mis":"SO5-1-u1-X14"},{"t":"화산섬이라 바위를 마음껏 떼어 가도 된다","mis":"SO5-1-u1-X10"}],"explanation":["화산섬은 특별한 지형이에요.","땅과 생물의 변화를 알 수 있어요.","그래서 연구 가치가 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#10','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',4,'essay','teacher','독도의 자연환경 가운데 생김새와 만들어진 까닭을 쓰고, 독도 주변 바다의 경제적 가치를 두 가지 쓴 뒤, 독도 전체를 천연기념물로 지정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"essay","stem":"독도의 자연환경 가운데 생김새와 만들어진 까닭을 쓰고, 독도 주변 바다의 경제적 가치를 두 가지 쓴 뒤, 독도 전체를 천연기념물로 지정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 독도는 동도와 서도 두 큰 섬과 여러 바위섬으로 이루어졌고, 오래전 바닷속 화산 활동으로 만들어졌다. 주변 바다는 차가운 물과 따뜻한 물이 만나 좋은 어장을 이루고, 깊은 바다에는 해양 심층수가, 바다 밑에는 가스 하이드레이트가 있다. 독도는 연구 가치가 크고 다양한 동식물이 사는 생태계를 지녔으므로, 이를 보호하려고 독도 전체를 천연기념물로 지정했다.","scoring_points":["생김새와 화산 활동을 썼는가","경제적 가치를 두 가지 썼는가","천연기념물 지정 까닭(보호)을 썼는가"]},"explanation":["동도·서도·바위섬이에요.","어장과 자원이에요.","생태계를 보호하려고 지정했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#1','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'mc','auto','우산국을 정벌해 우산국이 신라의 영토가 되게 한 신라의 장군은 누구인가요?',ARRAY['SO5-1-u1-X17','SO5-1-u1-X18']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"mc","stem":"우산국을 정벌해 우산국이 신라의 영토가 되게 한 신라의 장군은 누구인가요?","options":[{"t":"이사부","correct":true},{"t":"김유신","mis":"SO5-1-u1-X17"},{"t":"장보고","mis":"SO5-1-u1-X17"},{"t":"안용복","mis":"SO5-1-u1-X18"}],"explanation":["『삼국사기』에 남은 일이에요.","신라의 장군이 우산국을 정벌했어요.","이사부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#2','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'mc','auto','지금 남아 있는 우리나라 옛 지도 가운데 독도가 그려진 가장 오래된 지도는 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"mc","stem":"지금 남아 있는 우리나라 옛 지도 가운데 독도가 그려진 가장 오래된 지도는 어느 것인가요?","options":[{"t":"「팔도총도」","correct":true},{"t":"「삼국접양지도」","mis":"SO5-1-u1-X17"},{"t":"「조선왕국전도」","mis":"SO5-1-u1-X17"},{"t":"「태정관 지령」","mis":"SO5-1-u1-X17"}],"explanation":["우리나라가 만든 지도예요.","우산도(독도)가 그려져 있어요.","「팔도총도」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#3','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'sa','auto','대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 일을 기려 정한 「독도의 날」은 몇 월 며칠인가요? (□□월 □□일)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"sa","stem":"대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 일을 기려 정한 「독도의 날」은 몇 월 며칠인가요? (□□월 □□일)","answer":["10월 25일","10월25일"],"explanation":["가을에 있어요.","대한 제국의 칙령을 기려요.","10월 25일이에요."],"mis":"SO5-1-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#4','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'ox','auto','독도는 옛날에 우산도·삼봉도·석도 같은 여러 이름으로 불렸어요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"ox","stem":"독도는 옛날에 우산도·삼봉도·석도 같은 여러 이름으로 불렸어요.","answer":"O","reason_options":[{"t":"오래전부터 우리와 가까운 섬이어서 모습이나 특징을 보고 여러 이름을 붙였기 때문에","correct":true},{"t":"독도는 최근에 처음 발견되어 이름이 하나뿐이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["세 봉우리를 보고 삼봉도라고 불렀어요.","돌섬이라 석도라고도 했어요.","이름이 많을 만큼 가까운 섬이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#5','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','『세종실록지리지』에 적힌 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17','SO5-1-u1-X14','SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"『세종실록지리지』에 적힌 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 섬이 멀지 않아 맑은 날 서로 바라볼 수 있다","correct":true},{"t":"두 섬이 일본의 영토라고 적혀 있다","mis":"SO5-1-u1-X17"},{"t":"독도에는 아무도 갈 수 없다고 적혀 있다","mis":"SO5-1-u1-X14"},{"t":"독도의 넓이를 정확히 재어 적어 두었다","mis":"SO5-1-u1-X13"}],"explanation":["우산(독도)과 무릉(울릉도)이 나와요.","거리가 멀지 않다고 했어요.","맑으면 서로 보인다고 적었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#6','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','일본에서 만든 「삼국접양지도」에서 독도는 어느 나라와 같은 색으로 칠해져 있나요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"일본에서 만든 「삼국접양지도」에서 독도는 어느 나라와 같은 색으로 칠해져 있나요?","options":[{"t":"조선","correct":true},{"t":"일본","mis":"SO5-1-u1-X17"},{"t":"청나라","mis":"SO5-1-u1-X17"},{"t":"색이 칠해져 있지 않다","mis":"SO5-1-u1-X17"}],"explanation":["나라마다 색이 달라요.","독도는 울릉도와 함께 칠해졌어요.","조선과 같은 색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#7','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','독도에 관한 옛 자료 여섯 가운데 다른 나라가 만든 자료로만 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"독도에 관한 옛 자료 여섯 가운데 다른 나라가 만든 자료로만 묶은 것은 어느 것인가요?","options":[{"t":"㉣·㉤·㉥","correct":true},{"t":"㉠·㉡·㉢","mis":"SO5-1-u1-X17"},{"t":"㉠·㉣·㉥","mis":"SO5-1-u1-X17"},{"t":"㉡·㉢·㉤","mis":"SO5-1-u1-X17"}],"explanation":["괄호 안에 만든 나라가 있어요.","㉣·㉤은 일본, ㉥은 프랑스예요.","나머지는 우리나라 자료예요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#8','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'ox','auto','옛 지도에는 그때 사람들이 어디까지를 자기 나라 땅으로 여겼는지가 담겨 있어요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"ox","stem":"옛 지도에는 그때 사람들이 어디까지를 자기 나라 땅으로 여겼는지가 담겨 있어요.","answer":"O","reason_options":[{"t":"지도를 그린 사람들의 영토 인식이 그대로 나타나기 때문에","correct":true},{"t":"옛 지도는 아무렇게나 그려서 아무 뜻이 없기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["옛 지도는 영토 인식을 보여 줘요.","그래서 영토의 역사를 알 수 있어요.","중요한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#9','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','프랑스의 지리학자가 만든 「조선왕국전도」에 울릉도와 독도가 그려진 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"프랑스의 지리학자가 만든 「조선왕국전도」에 울릉도와 독도가 그려진 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"멀리 떨어진 유럽 사람들도 두 섬을 조선의 땅으로 알고 있었다","correct":true},{"t":"우리나라 사람만 독도를 알고 있었다","mis":"SO5-1-u1-X17"},{"t":"독도는 프랑스의 영토였다","mis":"SO5-1-u1-X17"},{"t":"옛날에는 동해에 섬이 없었다","mis":"SO5-1-u1-X17"}],"explanation":["유럽인이 만든 조선 지도예요.","울릉도와 독도가 그려져 있어요.","멀리서도 조선 땅으로 알았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#10','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',3,'mc','auto','「돗토리번 답변서」와 「태정관 지령」이 특별한 증거가 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"「돗토리번 답변서」와 「태정관 지령」이 특별한 증거가 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일본이 스스로 만든 국가 문서에서 두 섬이 일본 땅이 아니라고 밝혔기 때문에","correct":true},{"t":"우리나라 사람이 일본에 가서 만든 문서이기 때문에","mis":"SO5-1-u1-X17"},{"t":"가장 오래된 옛 지도이기 때문에","mis":"SO5-1-u1-X17"},{"t":"세계 여러 나라가 함께 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"explanation":["두 자료는 일본의 문서예요.","스스로 일본 땅이 아니라고 했어요.","그래서 더 분명한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#1','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',2,'sa','auto','신라 장군 이사부가 정벌해 신라의 영토가 된 울릉도와 독도 지역의 옛 나라 이름은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"sa","stem":"신라 장군 이사부가 정벌해 신라의 영토가 된 울릉도와 독도 지역의 옛 나라 이름은 무엇인가요? 세 글자로 쓰세요.","answer":["우산국"],"explanation":["『삼국사기』에 나와요.","신라 지증왕 때 항복했어요.","우산국이에요."],"mis":"SO5-1-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#2','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',2,'match','auto','옛 자료와 그 자료가 말해 주는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"match","stem":"옛 자료와 그 자료가 말해 주는 내용을 알맞게 이으세요.","pairs":[{"l":"『세종실록지리지』","r":"맑은 날 두 섬이 서로 보인다"},{"l":"「팔도총도」","r":"독도가 그려진 가장 오래된 우리 옛 지도"},{"l":"「삼국접양지도」","r":"독도를 조선과 같은 색으로 칠함"},{"l":"「태정관 지령」","r":"두 섬은 일본 땅이 아니라고 밝힘"}],"mis":"SO5-1-u1-X17","explanation":["『세종실록지리지』는 기록이에요.","「팔도총도」는 가장 오래된 우리 지도예요.","두 일본 자료도 조선 땅이라 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#3','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'mc','auto','독도에 관한 옛 자료 여섯에서 ㉡의 기록이 독도가 우리 땅이라는 증거가 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X17']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"독도에 관한 옛 자료 여섯에서 ㉡의 기록이 독도가 우리 땅이라는 증거가 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 사람들이 두 섬의 위치를 알고 우리 땅으로 기록했기 때문에","correct":true},{"t":"독도의 넓이가 정확히 적혀 있기 때문에","mis":"SO5-1-u1-X13"},{"t":"일본이 만든 기록이기 때문에","mis":"SO5-1-u1-X17"},{"t":"가장 최근에 만든 기록이기 때문에","mis":"SO5-1-u1-X17"}],"explanation":["㉡은 우리나라 기록이에요.","두 섬이 서로 보인다고 적었어요.","알고 있었고 우리 땅으로 여겼어요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#4','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'mc','auto','연합국 최고 사령관 각서의 부속 지도가 독도를 어떻게 나타냈나요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"연합국 최고 사령관 각서의 부속 지도가 독도를 어떻게 나타냈나요?","options":[{"t":"울릉도와 함께 일본에서 제외되는 섬으로 표시했다","correct":true},{"t":"일본의 섬으로 표시했다","mis":"SO5-1-u1-X17"},{"t":"러시아의 섬으로 표시했다","mis":"SO5-1-u1-X17"},{"t":"독도를 그리지 않았다","mis":"SO5-1-u1-X17"}],"explanation":["다른 나라가 만든 지도예요.","두 섬을 일본에서 뺐어요.","독도가 일본 땅이 아니라는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#5','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'ox','auto','옛 지도와 기록을 살펴볼 때는 자료에 적힌 연도를 빠짐없이 외우는 것이 가장 중요해요.',ARRAY['SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"ox","stem":"옛 지도와 기록을 살펴볼 때는 자료에 적힌 연도를 빠짐없이 외우는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"누가 만들었고 무엇을 말하는지 읽어 내는 것이 더 중요하기 때문에","correct":true},{"t":"옛 자료에는 연도가 하나도 적혀 있지 않기 때문에","mis":"SO5-1-u1-X13"}],"mis":"SO5-1-u1-X13","explanation":["연도를 외우는 것이 목표가 아니에요.","만든 나라와 내용을 읽어요.","자료를 견주면 더 분명해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#6','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'error','auto','옛 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"error","stem":"옛 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「일본이 만든 자료는 독도와 아무 관계가 없으니 보지 않아도 돼.」","correct":true,"mis_target":"SO5-1-u1-X17"},{"t":"서아 — 「우리나라 자료와 다른 나라 자료를 함께 봐야 해.」","mis":"SO5-1-u1-X17"},{"t":"유찬 — 「자료가 어느 나라에서 만들어졌는지 살펴봐야 해.」","mis":"SO5-1-u1-X17"}],"explanation":["일본 자료도 독도를 조선 땅으로 나타냈어요.","그래서 더 분명한 증거예요.","여러 나라 자료를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#7','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'mc','auto','「삼국접양지도」를 보고 「당시 일본에서도 독도를 조선의 영토로 여겼다」고 말할 수 있는 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"「삼국접양지도」를 보고 「당시 일본에서도 독도를 조선의 영토로 여겼다」고 말할 수 있는 까닭은 무엇인가요?","options":[{"t":"일본이 만든 지도인데도 독도를 조선과 같은 색으로 칠했기 때문에","correct":true},{"t":"독도를 일본과 같은 색으로 칠했기 때문에","mis":"SO5-1-u1-X17"},{"t":"조선 사람이 만든 지도이기 때문에","mis":"SO5-1-u1-X17"},{"t":"지도에 독도가 그려지지 않았기 때문에","mis":"SO5-1-u1-X17"}],"explanation":["나라마다 색으로 영토를 나눴어요.","독도는 조선 색이에요.","만든 나라가 일본이라 더 뜻깊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#8','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',4,'mc','auto','독도에 관한 옛 자료 여섯을 모두 볼 때 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"mc","stem":"독도에 관한 옛 자료 여섯을 모두 볼 때 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 자료와 다른 나라 자료 모두 옛날부터 독도를 우리 땅으로 나타냈다","correct":true},{"t":"우리나라 자료만 독도를 우리 땅으로 나타냈다","mis":"SO5-1-u1-X17"},{"t":"독도는 옛 자료에 한 번도 나오지 않는다","mis":"SO5-1-u1-X17"},{"t":"옛 자료마다 독도를 다른 나라 땅으로 나타냈다","mis":"SO5-1-u1-X17"}],"explanation":["㉠~㉢은 우리 자료예요.","㉣~㉥은 다른 나라 자료예요.","모두 독도를 우리 땅으로 나타냈어요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#9','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',4,'mc','auto','독도가 우리 땅이라는 증거로 다른 나라가 만든 자료가 특히 힘이 있는 까닭을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X17']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"mc","stem":"독도가 우리 땅이라는 증거로 다른 나라가 만든 자료가 특히 힘이 있는 까닭을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"자기 나라에 이로울 것이 없는데도 독도를 조선 땅으로 나타냈으니 믿을 만하기 때문에","correct":true},{"t":"다른 나라 자료는 언제나 우리 자료보다 오래되었기 때문에","mis":"SO5-1-u1-X13"},{"t":"다른 나라 자료는 그림이 더 예쁘기 때문에","mis":"SO5-1-u1-X17"},{"t":"다른 나라 자료는 연도가 더 정확하기 때문에","mis":"SO5-1-u1-X13"}],"explanation":["자기 땅이라고 할 수도 있었어요.","그런데도 조선 땅이라 했어요.","그래서 믿을 만한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#10','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',4,'essay','teacher','독도에 관한 옛 자료 여섯 가운데 우리나라 자료 하나와 다른 나라 자료 하나를 골라 무엇을 말하는지 쓰고, 두 자료를 함께 볼 때 알 수 있는 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"essay","stem":"독도에 관한 옛 자료 여섯 가운데 우리나라 자료 하나와 다른 나라 자료 하나를 골라 무엇을 말하는지 쓰고, 두 자료를 함께 볼 때 알 수 있는 점을 쓰세요.","answer_guide":{"answer":"예: 우리나라 자료인 「팔도총도」에는 울릉도와 함께 우산도(독도)가 그려져 있어 조선이 동해에 두 섬이 있음을 알고 있었음을 보여 준다. 일본이 만든 「삼국접양지도」는 독도를 조선과 같은 색으로 칠했다. 두 자료를 함께 보면 우리나라뿐 아니라 일본도 옛날부터 독도를 조선의 영토로 여겼음을 알 수 있다.","scoring_points":["우리나라 자료의 내용을 바르게 썼는가","다른 나라 자료의 내용을 바르게 썼는가","두 자료를 견주어 알 수 있는 점을 썼는가"]},"explanation":["우리 자료를 하나 골라요.","다른 나라 자료도 하나 골라요.","함께 보면 더 분명해요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#1','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',1,'mc','auto','조선 시대에 두 차례 일본으로 건너가 울릉도와 독도가 조선의 땅이라고 설명한 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"mc","stem":"조선 시대에 두 차례 일본으로 건너가 울릉도와 독도가 조선의 땅이라고 설명한 사람은 누구인가요?","options":[{"t":"안용복","correct":true},{"t":"최종덕","mis":"SO5-1-u1-X18"},{"t":"홍순칠","mis":"SO5-1-u1-X18"},{"t":"이사부","mis":"SO5-1-u1-X17"}],"explanation":["조선 시대 사람이에요.","일본에 건너가 설명했어요.","안용복이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#2','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',1,'mc','auto','독도로 주민 등록을 옮겨 최초의 독도 주민이 된 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"mc","stem":"독도로 주민 등록을 옮겨 최초의 독도 주민이 된 사람은 누구인가요?","options":[{"t":"최종덕","correct":true},{"t":"안용복","mis":"SO5-1-u1-X18"},{"t":"홍순칠","mis":"SO5-1-u1-X18"},{"t":"이사부","mis":"SO5-1-u1-X17"}],"explanation":["울릉도의 어부였어요.","독도에 사람이 산다는 것을 알렸어요.","최종덕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#3','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',1,'sa','auto','정부가 독도에 파견해 주민과 관광객의 편의와 안전을 지키게 한 경찰을 무엇이라고 하나요? (□□ □□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"sa","stem":"정부가 독도에 파견해 주민과 관광객의 편의와 안전을 지키게 한 경찰을 무엇이라고 하나요? (□□ □□□)","answer":["독도 경비대","독도경비대"],"explanation":["독도에 머무는 경찰이에요.","안전을 지키고 해안을 경계해요.","독도 경비대예요."],"mis":"SO5-1-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#4','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',1,'ox','auto','인공지능으로 그림을 만들 때는 조건을 구체적이고 자세하게 나타낼수록 원하는 그림에 가까워져요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C11","difficulty":1,"kind":"ox","stem":"인공지능으로 그림을 만들 때는 조건을 구체적이고 자세하게 나타낼수록 원하는 그림에 가까워져요.","answer":"O","reason_options":[{"t":"조건이 자세해야 무엇을 어떻게 그릴지 또렷해지기 때문에","correct":true},{"t":"인공지능은 조건이 짧을수록 더 잘 알아듣기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["흐린 조건은 그림을 정해 주지 못해요.","모습과 행동까지 적어요.","자세할수록 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#5','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'mc','auto','홍순칠과 독도 의용 수비대가 독도 바위에 「한국령」을 새긴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"홍순칠과 독도 의용 수비대가 독도 바위에 「한국령」을 새긴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"독도가 우리 영토임을 알리고 지키려는 의지를 나타내려고","correct":true},{"t":"바위의 이름을 붙여 관광객을 모으려고","mis":"SO5-1-u1-X18"},{"t":"배가 길을 잃지 않도록 방향을 알려 주려고","mis":"SO5-1-u1-X18"},{"t":"바위의 높이를 재어 기록해 두려고","mis":"SO5-1-u1-X13"}],"explanation":["「한국령」은 한국의 영토라는 뜻이에요.","우리 땅임을 알렸어요.","지키겠다는 의지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#6','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'match','auto','독도를 지킨 사람들 카드를 보고 카드와 알맞은 이름을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"match","stem":"독도를 지킨 사람들 카드를 보고 카드와 알맞은 이름을 이으세요.","pairs":[{"l":"㉠","r":"안용복"},{"l":"㉡","r":"홍순칠"},{"l":"㉢","r":"최종덕"},{"l":"㉣","r":"독도 경비대"}],"mis":"SO5-1-u1-X18","explanation":["㉠은 조선 시대 일본에 건너갔어요.","㉡은 의용 수비대, ㉢은 첫 주민이에요.","㉣은 지금 독도를 지키는 경찰이에요."],"asset":{"type":"passage","lines":["㉠ 조선 시대에 두 차례 일본으로 건너가 두 섬이 조선 땅이라고 설명했다.","㉡ 울릉도 청년들과 의용 수비대를 만들어 독도를 지켰다.","㉢ 울릉도의 어부로, 독도로 주민 등록을 옮겨 첫 독도 주민이 되었다.","㉣ 독도에 머물며 주민과 관광객의 안전을 지키고 해안을 경계한다."],"title":"독도를 지킨 사람들 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#7','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'mc','auto','오늘날 정부가 독도를 지키려고 하는 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"오늘날 정부가 독도를 지키려고 하는 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"독도에 큰 공항을 지어 관광객만 받는다","correct":true},{"t":"선착장·주민 숙소·등대를 만든다","mis":"SO5-1-u1-X18"},{"t":"독도와 주변 바다를 지키는 법과 정책을 만든다","mis":"SO5-1-u1-X18"},{"t":"세계 여러 나라에 독도가 우리 고유의 영토임을 알린다","mis":"SO5-1-u1-X18"}],"explanation":["정부는 시설을 만들고 경비대를 보내요.","법과 정책으로 지켜요.","세계에 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#8','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',2,'mc','auto','「우리나라의 아름다운 섬, 독도」 그림 조건 메모에서 독도와 어울리지 않는 조건은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X19']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C11","difficulty":2,"kind":"mc","stem":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모에서 독도와 어울리지 않는 조건은 어느 것인가요?","options":[{"t":"조건 ㉱","correct":true},{"t":"조건 ㉯","mis":"SO5-1-u1-X16"},{"t":"조건 ㉰","mis":"SO5-1-u1-X16"},{"t":"조건 ㉮","mis":"SO5-1-u1-X19"}],"explanation":["독도에는 목장이 없어요.","괭이갈매기·해국·사철나무는 독도의 모습이에요.","㉱는 독도와 맞지 않아요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#9','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'ox','auto','독도를 지키는 일은 정부와 경비대가 하니 나는 관심을 갖지 않아도 돼요.',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"ox","stem":"독도를 지키는 일은 정부와 경비대가 하니 나는 관심을 갖지 않아도 돼요.","answer":"X","reason_options":[{"t":"개인·학교·여러 단체가 함께 관심을 기울이고 노력해야 더 잘 지킬 수 있기 때문에","correct":true},{"t":"독도는 아무도 지킬 필요가 없는 섬이기 때문에","mis":"SO5-1-u1-X18"}],"mis":"SO5-1-u1-X18","explanation":["독도 지키기는 모두의 일이에요.","관심을 갖고 바르게 알아요.","알리는 활동에 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#10','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',3,'mc','auto','그림 조건 메모의 조건 ㉮ 「예쁜 풍경」만으로는 원하는 그림을 얻기 어려운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"그림 조건 메모의 조건 ㉮ 「예쁜 풍경」만으로는 원하는 그림을 얻기 어려운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람마다 떠올리는 모습이 달라 무엇을 그릴지 정해 주지 못하기 때문에","correct":true},{"t":"글자 수가 너무 많기 때문에","mis":"SO5-1-u1-X19"},{"t":"인공지능이 우리말을 읽지 못하기 때문에","mis":"SO5-1-u1-X19"},{"t":"예쁜 것은 그릴 수 없기 때문에","mis":"SO5-1-u1-X19"}],"explanation":["「예쁜 풍경」은 뜻이 흐려요.","무엇을 그릴지 정해지지 않아요.","자세한 조건이 필요해요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#1','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',2,'mc','auto','바다에서 국민의 생명과 재산을 지키고 해상 교통 질서와 바다 환경을 지키는 직업은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X18']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"바다에서 국민의 생명과 재산을 지키고 해상 교통 질서와 바다 환경을 지키는 직업은 어느 것인가요?","options":[{"t":"해양 경찰","correct":true},{"t":"지질 공원 해설사","mis":"SO5-1-u1-X10"},{"t":"등대지기","mis":"SO5-1-u1-X18"},{"t":"선장","mis":"SO5-1-u1-X18"}],"explanation":["바다를 지키는 경찰이에요.","사고가 나면 사람을 구해요.","바다 오염도 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#2','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',2,'sa','auto','홍순칠과 독도 의용 수비대가 독도 바위에 새긴 세 글자는 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"sa","stem":"홍순칠과 독도 의용 수비대가 독도 바위에 새긴 세 글자는 무엇인가요?","answer":["한국령"],"explanation":["「한국의 영토」라는 뜻이에요.","바위에 새겼어요.","한국령이에요."],"mis":"SO5-1-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#3','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'mc','auto','독도에 군인이 아니라 경찰인 독도 경비대가 머무는 것이 뜻하는 바로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"독도에 군인이 아니라 경찰인 독도 경비대가 머무는 것이 뜻하는 바로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라가 독도를 우리 영토로서 평소처럼 다스리고 있다는 뜻","correct":true},{"t":"독도가 아직 어느 나라 땅인지 정해지지 않았다는 뜻","mis":"SO5-1-u1-X18"},{"t":"독도에는 사람이 살 수 없다는 뜻","mis":"SO5-1-u1-X15"},{"t":"독도에 관광객이 오지 못한다는 뜻","mis":"SO5-1-u1-X14"}],"explanation":["경찰은 나라 안의 질서를 지켜요.","독도도 우리 땅 안이에요.","평소처럼 다스린다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#4','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'mc','auto','사이버 외교 사절단이 독도에 관한 잘못된 정보를 찾아 고치도록 하는 활동이 필요한 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"사이버 외교 사절단이 독도에 관한 잘못된 정보를 찾아 고치도록 하는 활동이 필요한 까닭은 무엇인가요?","options":[{"t":"세계 사람들이 독도를 우리 땅으로 바르게 알도록 하려고","correct":true},{"t":"독도를 찾는 관광객 수를 늘리려고","mis":"SO5-1-u1-X15"},{"t":"독도에 새로운 시설을 지으려고","mis":"SO5-1-u1-X18"},{"t":"독도의 옛 이름을 새로 정하려고","mis":"SO5-1-u1-X17"}],"explanation":["잘못된 정보는 오해를 낳아요.","틀린 내용을 바로잡아요.","세계가 바르게 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#5','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',3,'ox','auto','인공지능이 만든 그림을 소개할 때는 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 돼요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"ox","stem":"인공지능이 만든 그림을 소개할 때는 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 돼요.","answer":"X","reason_options":[{"t":"조건을 생각하고 고른 사람은 나이므로 어떤 조건으로 무엇을 표현했는지 스스로 설명해야 하기 때문에","correct":true},{"t":"인공지능 그림은 이름을 붙일 수 없기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["조건을 고른 사람은 나예요.","그림 이름을 말해요.","어떤 조건으로 무엇을 표현했는지 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#6','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'error','auto','독도를 지킨 사람들 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"error","stem":"독도를 지킨 사람들 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「㉢은 조선 시대에 일본에 건너간 안용복이야.」","correct":true,"mis_target":"SO5-1-u1-X18"},{"t":"보민 — 「㉣은 지금도 독도에 머무는 경찰이야.」","mis":"SO5-1-u1-X18"},{"t":"지유 — 「㉡은 울릉도 청년들과 함께 독도를 지켰어.」","mis":"SO5-1-u1-X18"}],"explanation":["㉢은 첫 독도 주민이에요.","첫 독도 주민은 최종덕이에요.","안용복은 ㉠이에요."],"asset":{"type":"passage","lines":["㉠ 조선 시대에 두 차례 일본으로 건너가 두 섬이 조선 땅이라고 설명했다.","㉡ 울릉도 청년들과 의용 수비대를 만들어 독도를 지켰다.","㉢ 울릉도의 어부로, 독도로 주민 등록을 옮겨 첫 독도 주민이 되었다.","㉣ 독도에 머물며 주민과 관광객의 안전을 지키고 해안을 경계한다."],"title":"독도를 지킨 사람들 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#7','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',3,'mc','auto','표현하고 싶은 경관이 제대로 그려지지 않았을 때 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"표현하고 싶은 경관이 제대로 그려지지 않았을 때 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조건을 더하거나 다르게 입력해 마음에 들 때까지 다시 만든다","correct":true},{"t":"그리기를 그만둔다","mis":"SO5-1-u1-X19"},{"t":"아무 그림이나 골라서 쓴다","mis":"SO5-1-u1-X19"},{"t":"조건을 모두 지우고 그냥 둔다","mis":"SO5-1-u1-X19"}],"explanation":["한 번에 안 되어도 괜찮아요.","조건을 고쳐 보아요.","여러 번 다시 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#8','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',4,'mc','auto','초등학생들이 독도에 찾아가 경비대를 만나고, 명예시민 등록과 각국 대사관에 편지 쓰기를 하기로 했어요. 이 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"mc","stem":"초등학생들이 독도에 찾아가 경비대를 만나고, 명예시민 등록과 각국 대사관에 편지 쓰기를 하기로 했어요. 이 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"개인과 학교도 독도에 관심을 불러일으키고 세계에 독도가 우리 땅임을 알리는 데 함께한다","correct":true},{"t":"독도를 지키는 일은 학생과 관계없다","mis":"SO5-1-u1-X18"},{"t":"독도에 학교를 새로 지으려는 것이다","mis":"SO5-1-u1-X18"},{"t":"독도에 사는 동물 수를 세려는 것이다","mis":"SO5-1-u1-X16"}],"explanation":["방문하고 알리는 활동이에요.","세계에 바른 역사를 알려요.","학생도 함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#9','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',4,'mc','auto','「우리나라의 아름다운 섬, 독도」 그림을 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19','SO5-1-u1-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C11","difficulty":4,"kind":"mc","stem":"「우리나라의 아름다운 섬, 독도」 그림을 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그림 이름은 「아침의 독도」입니다. 동도와 서도, 하늘을 나는 괭이갈매기, 바위에 핀 해국을 조건으로 독도의 자연을 표현했습니다.」","correct":true},{"t":"「인공지능이 만들었으니 제 생각은 없어요.」","mis":"SO5-1-u1-X19"},{"t":"「이름은 없지만 예쁘니까 봐 주세요.」","mis":"SO5-1-u1-X19"},{"t":"「산 위 목장의 소를 넣어 독도를 표현했습니다.」","mis":"SO5-1-u1-X16"}],"explanation":["그림 이름을 말해요.","어떤 조건을 썼는지 말해요.","무엇을 표현했는지 설명해요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#10','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',4,'essay','teacher','독도를 지키려고 노력한 사람이나 집단 두 곳을 골라 한 일을 쓰고, 내가 독도를 알리려고 할 수 있는 일을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"essay","stem":"독도를 지키려고 노력한 사람이나 집단 두 곳을 골라 한 일을 쓰고, 내가 독도를 알리려고 할 수 있는 일을 하나 쓰세요.","answer_guide":{"answer":"예: 안용복은 조선 시대에 두 차례 일본으로 건너가 울릉도와 독도가 조선의 땅이라고 설명했다. 정부는 독도 경비대를 파견하고 선착장과 등대를 만들어 독도를 지킨다. 나는 독도의 위치와 자연환경, 옛 지도에 나타난 독도를 소개하는 그림을 만들어 친구들과 가족에게 알리겠다.","scoring_points":["노력한 사람이나 집단을 둘 골랐는가","각각 한 일을 바르게 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["옛날과 오늘의 노력을 골라요.","한 일을 바르게 짝지어요.","나도 함께할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#1','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C1',1,'mc','auto','새봄이네가 여행하며 만난 산지·하천·평야·해안·섬을 함께 이르는 말은 어느 것인가요?',ARRAY['SO5-1-u1-X01','SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"새봄이네가 여행하며 만난 산지·하천·평야·해안·섬을 함께 이르는 말은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"기후","mis":"SO5-1-u1-X01"},{"t":"인구","mis":"SO5-1-u1-X01"},{"t":"항로","mis":"SO5-1-u1-X14"}],"explanation":["모두 땅의 생김새예요.","땅의 생김새를 지형이라고 해요.","기후는 날씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#2','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C2',1,'mc','auto','새봄이네 수첩 ①의 산지가 지형도에서 진한 갈색인 것은 무엇을 뜻하나요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ①의 산지가 지형도에서 진한 갈색인 것은 무엇을 뜻하나요?","options":[{"t":"땅이 아주 높다","correct":true},{"t":"땅이 아주 낮다","mis":"SO5-1-u1-X04"},{"t":"바다가 깊다","mis":"SO5-1-u1-X04"},{"t":"사람이 많이 산다","mis":"SO5-1-u1-X04"}],"explanation":["범례를 보면 알 수 있어요.","진한 갈색은 높은 땅이에요.","높은 산지예요."],"asset":{"type":"passage","lines":["첫째 날 — 북동쪽의 높은 산지에 갔다.","험한 봉우리가 줄지어 있고 바람이 세게 불었다.","지형도에서 이곳은 진한 갈색으로 칠해져 있었다."],"title":"새봄이네 수첩 ① 높은 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#3','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',1,'mc','auto','새봄이네 수첩 ②에서 물줄기가 서쪽의 낮은 곳으로 흘러간 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ②에서 물줄기가 서쪽의 낮은 곳으로 흘러간 까닭은 무엇인가요?","options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"물은 낮은 곳에서 높은 곳으로 흐르기 때문에","mis":"SO5-1-u1-X05"},{"t":"물은 언제나 동쪽으로 흐르기 때문에","mis":"SO5-1-u1-X05"},{"t":"바람이 물을 밀었기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["물은 아래로 흘러요.","서쪽이 더 낮아요.","그래서 서쪽으로 흘렀어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#4','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',1,'mc','auto','새봄이네 수첩 ③처럼 바닷물이 빠지면 드러나는 넓은 진흙 땅을 무엇이라고 하나요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X06']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ③처럼 바닷물이 빠지면 드러나는 넓은 진흙 땅을 무엇이라고 하나요?","options":[{"t":"갯벌","correct":true},{"t":"모래사장","mis":"SO5-1-u1-X08"},{"t":"해안 절벽","mis":"SO5-1-u1-X08"},{"t":"평야","mis":"SO5-1-u1-X06"}],"explanation":["바닷물이 드나드는 진흙 땅이에요.","조개를 캘 수 있어요.","갯벌이에요."],"asset":{"type":"passage","lines":["바닷물이 빠지자 넓은 진흙 땅이 드러났다.","동생과 조개를 캤다.","지도를 보니 해안선이 들쭉날쭉하고 섬이 많았다."],"title":"새봄이네 수첩 ③ 진흙 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#5','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C5',1,'mc','auto','새봄이네 수첩 ⑤에서 바위가 생긴 까닭과 옛이야기를 들려준 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑤에서 바위가 생긴 까닭과 옛이야기를 들려준 사람은 누구인가요?","options":[{"t":"지질 공원 해설사","correct":true},{"t":"해양 경찰","mis":"SO5-1-u1-X18"},{"t":"독도 경비대원","mis":"SO5-1-u1-X18"},{"t":"여행사 직원","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원에서 일해요.","지질·지형·역사를 엮어 설명해요.","지질 공원 해설사예요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#6','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',1,'mc','auto','국토 여행 계획을 세우는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"국토 여행 계획을 세우는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 여행지 조사 → 경로 표시 → 계획 공유","correct":true},{"t":"여행지 조사 → 주제 정하기 → 경로 표시 → 계획 공유","mis":"SO5-1-u1-X11"},{"t":"경로 표시 → 주제 정하기 → 계획 공유 → 여행지 조사","mis":"SO5-1-u1-X11"},{"t":"계획 공유 → 경로 표시 → 여행지 조사 → 주제 정하기","mis":"SO5-1-u1-X11"}],"explanation":["주제가 먼저예요.","조사한 뒤 경로를 이어요.","마지막에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#7','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',1,'mc','auto','새봄이네 수첩 ⑥에서 독도에 가기 전에 들른 섬은 어디인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑥에서 독도에 가기 전에 들른 섬은 어디인가요?","options":[{"t":"울릉도","correct":true},{"t":"제주도","mis":"SO5-1-u1-X14"},{"t":"강화도","mis":"SO5-1-u1-X14"},{"t":"거제도","mis":"SO5-1-u1-X14"}],"explanation":["동해안 항구에서 배를 탔어요.","먼저 울릉도에 갔어요.","그다음 독도로 갔어요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#8','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C8',1,'mc','auto','새봄이네 수첩 ⑦에 나온 독도의 두 큰 섬은 무엇인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑦에 나온 독도의 두 큰 섬은 무엇인가요?","options":[{"t":"동도와 서도","correct":true},{"t":"남도와 북도","mis":"SO5-1-u1-X16"},{"t":"울릉도와 제주도","mis":"SO5-1-u1-X14"},{"t":"큰섬과 작은섬","mis":"SO5-1-u1-X16"}],"explanation":["동쪽 섬과 서쪽 섬이에요.","동도와 서도예요.","주변에 바위섬이 많아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#9','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C2',2,'mc','auto','새봄이네 수첩 ①의 산지가 북동쪽에 있는 것과 가장 관계 깊은 우리나라 땅의 특징은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ①의 산지가 북동쪽에 있는 것과 가장 관계 깊은 우리나라 땅의 특징은 어느 것인가요?","options":[{"t":"높고 험한 산지가 북쪽과 동쪽에 몰려 있다","correct":true},{"t":"높은 산지가 남쪽과 서쪽에 몰려 있다","mis":"SO5-1-u1-X03"},{"t":"우리나라는 어디나 높이가 같다","mis":"SO5-1-u1-X03"},{"t":"높은 산지는 바다 한가운데에 있다","mis":"SO5-1-u1-X03"}],"explanation":["수첩 ①은 북동쪽이에요.","높은 산지가 북·동쪽에 있어요.","그래서 북동쪽이 높아요."],"asset":{"type":"passage","lines":["첫째 날 — 북동쪽의 높은 산지에 갔다.","험한 봉우리가 줄지어 있고 바람이 세게 불었다.","지형도에서 이곳은 진한 갈색으로 칠해져 있었다."],"title":"새봄이네 수첩 ① 높은 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#10','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',2,'mc','auto','새봄이네 수첩 ②의 「아래쪽에는 논이 넓게 펼쳐져 있었다」는 모습이 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X08']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ②의 「아래쪽에는 논이 넓게 펼쳐져 있었다」는 모습이 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하천 주변의 낮고 평평한 땅에 평야가 발달했기 때문에","correct":true},{"t":"높은 산꼭대기에 평야가 생겼기 때문에","mis":"SO5-1-u1-X06"},{"t":"바닷물이 빠져 진흙 땅이 드러났기 때문에","mis":"SO5-1-u1-X08"},{"t":"파도가 바위를 깎았기 때문에","mis":"SO5-1-u1-X08"}],"explanation":["하천 아래쪽은 낮아요.","평평한 땅이 넓어요.","평야에 논이 많아요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#11','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',2,'mc','auto','새봄이네 수첩 ③과 ④를 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ③과 ④를 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"③은 해안선이 들쭉날쭉하고 갯벌이 있고, ④는 해안선이 곧고 모래사장이 넓다","correct":true},{"t":"③은 모래사장이 넓고, ④는 갯벌이 넓다","mis":"SO5-1-u1-X07"},{"t":"③과 ④는 해안선 모습이 같다","mis":"SO5-1-u1-X07"},{"t":"③은 동해안, ④는 서해안의 모습이다","mis":"SO5-1-u1-X07"}],"explanation":["③은 갯벌과 복잡한 해안선이에요.","④는 곧은 해안선과 모래사장이에요.","바다마다 모습이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#12','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C5',2,'mc','auto','새봄이네 수첩 ⑤에서 아빠가 동생을 말린 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑤에서 아빠가 동생을 말린 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오랜 시간이 만든 자연이라 가져가면 되돌릴 수 없기 때문에","correct":true},{"t":"돌 조각이 너무 무거워서","mis":"SO5-1-u1-X10"},{"t":"돌은 사서 가져가야 하기 때문에","mis":"SO5-1-u1-X10"},{"t":"해설사가 돌을 팔기 때문에","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원의 돌은 오랜 시간이 만들었어요.","가져가면 되돌릴 수 없어요.","눈으로만 봐요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#13','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',2,'mc','auto','새봄이네처럼 「산에서 바다까지 여러 지형을 만나는 여행」을 하려고 해요. 경로를 정할 때 알맞은 생각은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"새봄이네처럼 「산에서 바다까지 여러 지형을 만나는 여행」을 하려고 해요. 경로를 정할 때 알맞은 생각은 어느 것인가요?","options":[{"t":"이동 거리가 너무 길어지지 않게, 여행 목적에 맞는 차례로 화살표를 잇는다","correct":true},{"t":"가장 먼 곳끼리 번갈아 다닌다","mis":"SO5-1-u1-X11"},{"t":"조사하지 않은 곳을 많이 넣는다","mis":"SO5-1-u1-X11"},{"t":"여행지 이름만 나열하고 경로는 그리지 않는다","mis":"SO5-1-u1-X11"}],"explanation":["동선이 길지 않게 해요.","목적에 맞는 차례로 해요.","화살표로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#14','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',2,'mc','auto','새봄이네 수첩 ⑥의 「맑은 날 전망대에서 멀리 독도가 보였다」가 뜻하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X16']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑥의 「맑은 날 전망대에서 멀리 독도가 보였다」가 뜻하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"울릉도 사람들은 오래전부터 독도를 알고 우리 영토로 여겨 왔다","correct":true},{"t":"독도와 울릉도는 땅으로 이어져 있다","mis":"SO5-1-u1-X14"},{"t":"독도는 울릉도보다 훨씬 크다","mis":"SO5-1-u1-X16"},{"t":"독도에는 공항이 있다","mis":"SO5-1-u1-X14"}],"explanation":["눈에 보일 만큼 가까워요.","오래전부터 알았어요.","우리 영토로 여겼어요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#15','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C8',2,'mc','auto','새봄이네 수첩 ⑦에서 안개가 끼었다 걷힌 것과 관계 깊은 독도의 날씨 특징은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑦에서 안개가 끼었다 걷힌 것과 관계 깊은 독도의 날씨 특징은 어느 것인가요?","options":[{"t":"대체로 온화하지만 안개가 자주 끼고 흐린 날이 많다","correct":true},{"t":"일 년 내내 눈이 쌓여 있다","mis":"SO5-1-u1-X16"},{"t":"비가 전혀 오지 않는다","mis":"SO5-1-u1-X16"},{"t":"사막처럼 늘 건조하다","mis":"SO5-1-u1-X16"}],"explanation":["독도는 바다 한가운데예요.","안개가 자주 껴요.","흐린 날이 많아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#16','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C9',2,'mc','auto','새봄이네 수첩 ⑧에서 본 옛 지도로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 본 옛 지도로 알 수 있는 것은 어느 것인가요?","options":[{"t":"당시 일본에서도 독도를 조선의 영토로 여겼다","correct":true},{"t":"독도는 옛날에 일본 땅이었다","mis":"SO5-1-u1-X17"},{"t":"옛날에는 동해에 섬이 없었다","mis":"SO5-1-u1-X17"},{"t":"지도를 만든 나라는 조선이다","mis":"SO5-1-u1-X17"}],"explanation":["일본이 만든 지도예요.","독도를 조선 색으로 칠했어요.","일본도 조선 땅으로 여겼어요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#17','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',3,'mc','auto','새봄이네 수첩 ①에서 ②로 이어지는 여행을 지형도에 그린다면 물줄기를 따라간 방향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X04']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ①에서 ②로 이어지는 여행을 지형도에 그린다면 물줄기를 따라간 방향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"북동쪽의 진한 색 땅에서 서쪽의 옅은 색 땅으로","correct":true},{"t":"서쪽의 옅은 색 땅에서 북동쪽의 진한 색 땅으로","mis":"SO5-1-u1-X05"},{"t":"초록색 땅에서 진한 갈색 땅으로","mis":"SO5-1-u1-X04"},{"t":"높이가 같은 땅을 따라 옆으로만","mis":"SO5-1-u1-X05"}],"explanation":["물은 높은 곳에서 출발해요.","진한 색이 높은 곳이에요.","옅은 색 낮은 곳으로 흘러요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#18','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',3,'mc','auto','새봄이네 수첩 ④의 바닷가에 서핑하는 사람과 해수욕장이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X07','SO5-1-u1-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ④의 바닷가에 서핑하는 사람과 해수욕장이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해안선이 단순하고 넓은 모래사장이 펼쳐진 동해안이기 때문에","correct":true},{"t":"물이 빠지면 넓은 갯벌이 드러나기 때문에","mis":"SO5-1-u1-X08"},{"t":"섬이 아주 많아 다도해이기 때문에","mis":"SO5-1-u1-X07"},{"t":"높은 산지 위에 있기 때문에","mis":"SO5-1-u1-X09"}],"explanation":["모래사장이 넓어요.","해수욕장이 발달해요.","파도를 타기도 좋아요."],"asset":{"type":"passage","lines":["해안선이 곧게 뻗은 바닷가에 갔다.","넓은 모래사장에서 해수욕을 했다.","파도를 타며 서핑을 하는 사람도 많았다."],"title":"새봄이네 수첩 ④ 모래 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#19','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',3,'mc','auto','새봄이가 「다양한 해안 지형을 견주어 보는 여행」을 주제로 다시 계획한다면 넣기 가장 알맞은 수첩 꼭지 묶음은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"새봄이가 「다양한 해안 지형을 견주어 보는 여행」을 주제로 다시 계획한다면 넣기 가장 알맞은 수첩 꼭지 묶음은 어느 것인가요?","options":[{"t":"③과 ④","correct":true},{"t":"①과 ②","mis":"SO5-1-u1-X09"},{"t":"⑥과 ⑧","mis":"SO5-1-u1-X09"},{"t":"①과 ⑤","mis":"SO5-1-u1-X09"}],"explanation":["해안 지형을 견주어요.","③은 갯벌, ④는 모래사장이에요.","두 바닷가를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#20','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',3,'mc','auto','새봄이네 수첩 ⑥과 ⑦을 함께 볼 때 다른 나라 사람이 독도에 간다면 어떻게 가야 할까요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑥과 ⑦을 함께 볼 때 다른 나라 사람이 독도에 간다면 어떻게 가야 할까요?","options":[{"t":"우리나라에 들어와 동해안 항구에서 배를 타고 울릉도를 거쳐 간다","correct":true},{"t":"자기 나라에서 비행기로 독도에 바로 간다","mis":"SO5-1-u1-X14"},{"t":"아무 나라에서나 배를 타고 바로 간다","mis":"SO5-1-u1-X14"},{"t":"다른 나라 사람은 독도에 갈 수 없다","mis":"SO5-1-u1-X15"}],"explanation":["독도는 우리 영토예요.","우리와 같은 방법으로 가요.","항구 → 울릉도 → 독도예요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#21','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C9',3,'mc','auto','새봄이네 수첩 ⑧의 옛 지도가 독도가 우리 땅이라는 증거로 특히 힘이 있는 까닭은 어느 것인가요?',ARRAY['SO5-1-u1-X17','SO5-1-u1-X13']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑧의 옛 지도가 독도가 우리 땅이라는 증거로 특히 힘이 있는 까닭은 어느 것인가요?","options":[{"t":"자기 나라 땅이라 할 수도 있었던 일본이 독도를 조선 색으로 칠했기 때문에","correct":true},{"t":"지도가 아주 크고 화려하기 때문에","mis":"SO5-1-u1-X17"},{"t":"우리나라가 만든 지도이기 때문에","mis":"SO5-1-u1-X17"},{"t":"연도가 가장 정확하게 적혀 있기 때문에","mis":"SO5-1-u1-X13"}],"explanation":["만든 나라가 일본이에요.","그런데도 조선 색이에요.","그래서 더 믿을 만해요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#22','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C11',3,'mc','auto','새봄이네 수첩 ⑧에서 새봄이가 독도를 알리는 그림을 만들 때 넣기 가장 알맞은 조건은 어느 것인가요?',ARRAY['SO5-1-u1-X19','SO5-1-u1-X16']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 새봄이가 독도를 알리는 그림을 만들 때 넣기 가장 알맞은 조건은 어느 것인가요?","options":[{"t":"동도와 서도 사이를 나는 괭이갈매기와 바위에 핀 해국","correct":true},{"t":"예쁜 풍경","mis":"SO5-1-u1-X19"},{"t":"산 위 목장에서 풀을 뜯는 소","mis":"SO5-1-u1-X16"},{"t":"넓은 모래사장의 해수욕장","mis":"SO5-1-u1-X16"}],"explanation":["수첩 ⑦에서 본 것을 떠올려요.","독도의 모습을 자세히 적어요.","흐린 조건은 안 돼요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#23','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C1',4,'mc','auto','「우리나라 국토 여행」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X13','SO5-1-u1-X05']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"mc","stem":"「우리나라 국토 여행」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"우리 국토는 북동쪽이 높고 남서쪽이 낮아 산지·하천·평야·해안이 어우러지고, 동쪽 끝 독도는 예로부터 우리 땅으로 함께 지켜 왔다","correct":true},{"t":"우리 국토는 어디나 평평하고 독도는 최근에 알려진 섬이다","mis":"SO5-1-u1-X03"},{"t":"지형은 이름만 외우면 되고 독도는 정부만 지키면 된다","mis":"SO5-1-u1-X13"},{"t":"하천은 동쪽으로 흐르고 독도는 서쪽 끝에 있다","mis":"SO5-1-u1-X05"}],"explanation":["높낮이가 지형을 이어 줘요.","독도는 동쪽 끝이에요.","옛날부터 함께 지켜 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#24','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',4,'essay','teacher','새봄이네 수첩 ①과 ②를 보고 물줄기가 서쪽으로 흘러간 까닭을 우리나라 땅의 높낮이와 함께 쓰고, 물줄기 아래쪽에 논이 넓게 펼쳐진 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ①과 ②를 보고 물줄기가 서쪽으로 흘러간 까닭을 우리나라 땅의 높낮이와 함께 쓰고, 물줄기 아래쪽에 논이 넓게 펼쳐진 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리나라는 높고 험한 산지가 북쪽과 동쪽에 몰려 있어 북동쪽이 높고 남서쪽이 낮다. 물은 높은 곳에서 낮은 곳으로 흐르므로 북동쪽 산에서 시작한 계곡물이 낮은 서쪽으로 흘러갔다. 물줄기 아래쪽은 낮고 평평한 땅이어서 평야가 발달했고 그래서 논이 넓게 펼쳐져 있다.","scoring_points":["북동쪽이 높고 남서쪽이 낮다고 썼는가","물이 낮은 곳으로 흐른다는 까닭을 썼는가","하천 주변 평야와 논을 이어 썼는가"]},"explanation":["높낮이가 방향을 정해요.","물은 낮은 곳으로 흘러요.","하천 주변에 평야가 있어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#25','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',4,'essay','teacher','새봄이네 수첩 ⑥을 보고 독도까지 가는 길을 차례대로 쓰고, 독도의 위치를 쓴 뒤, 독도가 중요한 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑥을 보고 독도까지 가는 길을 차례대로 쓰고, 독도의 위치를 쓴 뒤, 독도가 중요한 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 동해안의 항구에서 배를 타고 울릉도에 간 뒤 다시 배를 타고 독도로 간다. 독도에는 공항이 없기 때문이다. 독도는 우리나라 영토의 동쪽 끝, 동해에 있다. 독도는 우리 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요하다.","scoring_points":["항구 → 울릉도 → 독도의 차례를 썼는가","위치를 썼는가","중요한 까닭 두 가지를 썼는가"]},"explanation":["배로 울릉도를 거쳐요.","동쪽 끝이에요.","경계·교통·군사·연구·자원이에요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#1','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C1',1,'sa','auto','산봉우리가 길게 이어져 솟아 있는 땅을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"sa","stem":"산봉우리가 길게 이어져 솟아 있는 땅을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["산지"],"explanation":["높이 솟은 땅이에요.","우리 국토의 약 70%예요.","산지예요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#2','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C2',1,'mc','auto','우리나라 땅에서 높고 험한 산지가 많은 쪽은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"우리나라 땅에서 높고 험한 산지가 많은 쪽은 어느 것인가요?","options":[{"t":"북쪽과 동쪽","correct":true},{"t":"남쪽과 서쪽","mis":"SO5-1-u1-X03"},{"t":"남쪽만","mis":"SO5-1-u1-X03"},{"t":"서쪽만","mis":"SO5-1-u1-X03"}],"explanation":["높은 산이 몰려 있어요.","북쪽과 동쪽이에요.","그래서 북동쪽이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#3','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C3',1,'sa','auto','크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? (□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"sa","stem":"크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? (□□)","answer":["하천"],"explanation":["물이 흐르는 지형이에요.","강과 시내예요.","하천이에요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#4','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',1,'mc','auto','새봄이네 수첩 ④의 바닷가는 어느 바다일 가능성이 가장 큰가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ④의 바닷가는 어느 바다일 가능성이 가장 큰가요?","options":[{"t":"동해안","correct":true},{"t":"서해안","mis":"SO5-1-u1-X07"},{"t":"남해안","mis":"SO5-1-u1-X07"},{"t":"호숫가","mis":"SO5-1-u1-X08"}],"explanation":["해안선이 곧게 뻗었어요.","모래사장이 넓어요.","동해안의 모습이에요."],"asset":{"type":"passage","lines":["해안선이 곧게 뻗은 바닷가에 갔다.","넓은 모래사장에서 해수욕을 했다.","파도를 타며 서핑을 하는 사람도 많았다."],"title":"새봄이네 수첩 ④ 모래 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#5','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C5',1,'mc','auto','지질적 가치가 뛰어난 경관을 보전하려고 국제기구가 인증하는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"mc","stem":"지질적 가치가 뛰어난 경관을 보전하려고 국제기구가 인증하는 곳은 어느 것인가요?","options":[{"t":"세계 지질 공원","correct":true},{"t":"놀이공원","mis":"SO5-1-u1-X10"},{"t":"대형 할인점","mis":"SO5-1-u1-X10"},{"t":"공항","mis":"SO5-1-u1-X14"}],"explanation":["지질 가치가 뛰어나요.","국제기구가 인증해요.","세계 지질 공원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#6','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C6',1,'mc','auto','여행지의 실제 모습을 확대해 살펴보는 데 쓰는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"여행지의 실제 모습을 확대해 살펴보는 데 쓰는 것은 어느 것인가요?","options":[{"t":"디지털 영상 지도","correct":true},{"t":"일기장","mis":"SO5-1-u1-X11"},{"t":"저금통","mis":"SO5-1-u1-X11"},{"t":"계산기","mis":"SO5-1-u1-X11"}],"explanation":["영상 지도는 실제 모습을 보여 줘요.","확대할 수 있어요.","지형의 특징을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#7','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C7',1,'mc','auto','독도의 행정구역은 어느 것인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"독도의 행정구역은 어느 것인가요?","options":[{"t":"경상북도 울릉군","correct":true},{"t":"강원특별자치도 강릉시","mis":"SO5-1-u1-X14"},{"t":"제주특별자치도","mis":"SO5-1-u1-X14"},{"t":"전라남도 여수시","mis":"SO5-1-u1-X14"}],"explanation":["울릉도와 같은 군이에요.","경상북도에 속해요.","울릉군이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#8','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C10',1,'mc','auto','새봄이네 수첩 ⑧에서 조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람은 누구인가요?","options":[{"t":"안용복","correct":true},{"t":"최종덕","mis":"SO5-1-u1-X18"},{"t":"홍순칠","mis":"SO5-1-u1-X18"},{"t":"이사부","mis":"SO5-1-u1-X17"}],"explanation":["조선 시대 사람이에요.","두 차례 일본에 건너갔어요.","안용복이에요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#9','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C1',2,'mc','auto','새봄이네 수첩 ②에서 함께 만난 두 지형을 바르게 고른 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ②에서 함께 만난 두 지형을 바르게 고른 것은 어느 것인가요?","options":[{"t":"하천과 평야","correct":true},{"t":"해안과 섬","mis":"SO5-1-u1-X02"},{"t":"갯벌과 모래사장","mis":"SO5-1-u1-X08"},{"t":"섬과 해안 절벽","mis":"SO5-1-u1-X08"}],"explanation":["계곡물은 하천이에요.","논이 펼쳐진 땅은 평야예요.","하천과 평야를 만났어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#10','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C3',2,'mc','auto','물이 갈림길에서 900 m · 600 m · 300 m 세 곳 가운데 하나를 고른다면 어디로 갈까요? (지금 있는 곳은 700 m)',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"물이 갈림길에서 900 m · 600 m · 300 m 세 곳 가운데 하나를 고른다면 어디로 갈까요? (지금 있는 곳은 700 m)","options":[{"t":"300 m","correct":true},{"t":"900 m","mis":"SO5-1-u1-X05"},{"t":"세 곳 모두","mis":"SO5-1-u1-X05"},{"t":"갈 곳이 없다","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 가요.","700 m보다 낮은 곳은 600 m와 300 m예요.","가장 낮은 300 m로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#11','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',2,'mc','auto','새봄이네 수첩 ③에서 조개를 캘 수 있었던 까닭과 가장 관계 깊은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X09']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ③에서 조개를 캘 수 있었던 까닭과 가장 관계 깊은 것은 어느 것인가요?","options":[{"t":"넓은 갯벌이 발달한 바다였다","correct":true},{"t":"넓은 모래사장이 있는 바다였다","mis":"SO5-1-u1-X08"},{"t":"파도가 깎은 절벽이 있는 바다였다","mis":"SO5-1-u1-X08"},{"t":"높은 산지 위였다","mis":"SO5-1-u1-X09"}],"explanation":["조개는 갯벌에 살아요.","물이 빠지면 캘 수 있어요.","갯벌이 넓은 바다예요."],"asset":{"type":"passage","lines":["바닷물이 빠지자 넓은 진흙 땅이 드러났다.","동생과 조개를 캤다.","지도를 보니 해안선이 들쭉날쭉하고 섬이 많았다."],"title":"새봄이네 수첩 ③ 진흙 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#12','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C5',2,'mc','auto','지질 공원 해설사가 마을 옛이야기까지 들려준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"지질 공원 해설사가 마을 옛이야기까지 들려준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해설사는 지질·지형·자연·역사를 엮어 알기 쉽게 설명하기 때문에","correct":true},{"t":"해설사는 지형을 몰라서","mis":"SO5-1-u1-X10"},{"t":"옛이야기는 지질 공원과 관계없지만 재미있어서","mis":"SO5-1-u1-X10"},{"t":"해설사는 역사만 설명하기 때문에","mis":"SO5-1-u1-X10"}],"explanation":["해설사는 여러 이야기를 엮어요.","지질·지형·자연·역사예요.","알기 쉽게 설명해요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#13','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C6',2,'mc','auto','지역별 관광 안내 누리집을 찾을 때 검색창에 넣기 알맞은 말은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"지역별 관광 안내 누리집을 찾을 때 검색창에 넣기 알맞은 말은 어느 것인가요?","options":[{"t":"지역명 + 문화 관광","correct":true},{"t":"친구 이름 + 놀이","mis":"SO5-1-u1-X11"},{"t":"오늘 날씨","mis":"SO5-1-u1-X11"},{"t":"학교 이름 + 급식","mis":"SO5-1-u1-X11"}],"explanation":["지역 누리집을 찾아요.","지역명과 문화 관광을 넣어요.","그러면 연결돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#14','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C7',2,'mc','auto','독도가 동해에 있어 교통과 군사 면에서 중요한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도가 동해에 있어 교통과 군사 면에서 중요한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"동해를 지나는 배와 비행기를 살필 수 있기 때문에","correct":true},{"t":"독도에서 농사를 많이 짓기 때문에","mis":"SO5-1-u1-X15"},{"t":"독도에 큰 공항이 있기 때문에","mis":"SO5-1-u1-X14"},{"t":"독도에 사람이 가장 많이 살기 때문에","mis":"SO5-1-u1-X15"}],"explanation":["동해는 세 나라가 둘러싸요.","많은 배와 비행기가 지나가요.","살피고 지키는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#15','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C8',2,'mc','auto','독도 주변 바다가 좋은 어장을 이루는 까닭은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"독도 주변 바다가 좋은 어장을 이루는 까닭은 어느 것인가요?","options":[{"t":"차가운 바닷물과 따뜻한 바닷물이 만나기 때문에","correct":true},{"t":"바닷물이 아주 얕기 때문에","mis":"SO5-1-u1-X16"},{"t":"바다에 섬이 하나도 없기 때문에","mis":"SO5-1-u1-X16"},{"t":"파도가 전혀 치지 않기 때문에","mis":"SO5-1-u1-X16"}],"explanation":["두 바닷물이 만나요.","해양 생물이 살기 좋아요.","좋은 어장이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#16','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C10',2,'mc','auto','새봄이네 수첩 ⑦에서 독도 경비대원이 사람들을 안내한 것처럼, 정부가 독도 경비대를 보낸 까닭은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑦에서 독도 경비대원이 사람들을 안내한 것처럼, 정부가 독도 경비대를 보낸 까닭은 어느 것인가요?","options":[{"t":"주민과 관광객의 편의와 안전을 지키고 해안을 경계하려고","correct":true},{"t":"독도의 바위를 캐려고","mis":"SO5-1-u1-X18"},{"t":"독도에 목장을 만들려고","mis":"SO5-1-u1-X18"},{"t":"독도에 사람이 못 오게 막으려고","mis":"SO5-1-u1-X18"}],"explanation":["경비대는 경찰이에요.","안전을 지키고 경계해요.","독도를 평소처럼 다스려요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#17','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C2',3,'mc','auto','서쪽 바닷가에서 동쪽 바닷가까지 땅을 잘라 본 단면의 모양으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X04']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"서쪽 바닷가에서 동쪽 바닷가까지 땅을 잘라 본 단면의 모양으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서쪽은 낮고 넓게 이어지다가 동쪽 가까이에서 높이 솟는다","correct":true},{"t":"서쪽이 높이 솟고 동쪽은 낮고 넓다","mis":"SO5-1-u1-X03"},{"t":"처음부터 끝까지 높이가 같다","mis":"SO5-1-u1-X03"},{"t":"가운데만 깊게 파였다","mis":"SO5-1-u1-X04"}],"explanation":["서쪽은 낮아요.","동쪽에 높은 산이 몰려 있어요.","동쪽 가까이에서 솟아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#18','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',3,'error','auto','새봄이네 수첩 ③과 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"error","stem":"새봄이네 수첩 ③과 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세린 — 「③은 해안선이 곧아서 지도에 따라 그리기 쉬워.」","correct":true,"mis_target":"SO5-1-u1-X07"},{"t":"도하 — 「④에서는 해수욕을 즐겼어.」","mis":"SO5-1-u1-X08"},{"t":"예서 — 「③에서는 갯벌에서 조개를 캤어.」","mis":"SO5-1-u1-X08"}],"explanation":["③은 해안선이 들쭉날쭉해요.","따라 그리기 어려워요.","곧은 해안선은 ④예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#19','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C6',3,'error','auto','여행 계획을 세우는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"error","stem":"여행 계획을 세우는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지환 — 「여행지부터 아무 데나 고르고 주제는 맨 마지막에 정하면 돼.」","correct":true,"mis_target":"SO5-1-u1-X11"},{"t":"수빈 — 「주제를 먼저 정해야 어디를 조사할지 알 수 있어.」","mis":"SO5-1-u1-X11"},{"t":"주원 — 「조사한 곳은 디지털 영상 지도로 모습을 확인해.」","mis":"SO5-1-u1-X11"}],"explanation":["주제가 먼저예요.","주제가 조사할 곳을 정해 줘요.","지환의 차례가 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#20','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C8',3,'error','auto','새봄이네 수첩 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"error","stem":"새봄이네 수첩 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「독도는 땅이 평평해서 넓은 들판과 목장이 있어.」","correct":true,"mis_target":"SO5-1-u1-X16"},{"t":"지안 — 「바위에 해국 같은 식물이 자라.」","mis":"SO5-1-u1-X16"},{"t":"서진 — 「괭이갈매기 같은 새가 살아.」","mis":"SO5-1-u1-X16"}],"explanation":["독도는 화산이 만든 바위섬이에요.","들판과 목장은 없어요.","새와 바위 식물이 살아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#21','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C9',3,'error','auto','옛 자료를 살펴보는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"error","stem":"옛 자료를 살펴보는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태경 — 「옛 자료는 연도를 다 외워야만 무엇을 말하는지 알 수 있어.」","correct":true,"mis_target":"SO5-1-u1-X13"},{"t":"나연 — 「누가 만들었는지 살펴봐야 해.」","mis":"SO5-1-u1-X17"},{"t":"찬우 — 「여러 나라 자료를 함께 견주어 봐야 해.」","mis":"SO5-1-u1-X17"}],"explanation":["연도보다 내용을 읽어요.","누가 만들었는지 봐요.","함께 견주면 분명해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#22','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C10',3,'error','auto','독도를 지키는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"error","stem":"독도를 지키는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「경비대가 있으니 우리는 독도에 관심 없어도 돼.」","correct":true,"mis_target":"SO5-1-u1-X18"},{"t":"민재 — 「독도에 관한 잘못된 정보를 보면 바로잡도록 알려야 해.」","mis":"SO5-1-u1-X18"},{"t":"혜원 — 「독도를 알리는 활동에 참여할 수 있어.」","mis":"SO5-1-u1-X18"}],"explanation":["독도 지키기는 모두의 일이에요.","바로잡고 알리는 일도 해요.","관심이 첫걸음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#23','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C3',4,'mc','auto','새봄이네 수첩 ①·②·④를 차례로 이어 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X06','SO5-1-u1-X07']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ①·②·④를 차례로 이어 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"북동쪽 높은 산에서 시작한 물줄기는 낮은 서쪽으로 흐르며 주변에 평야를 만들고, 동쪽 바닷가는 산이 바다 가까이까지 이어진다","correct":true},{"t":"물줄기는 동쪽 바닷가에서 시작해 산꼭대기로 올라간다","mis":"SO5-1-u1-X05"},{"t":"평야는 북동쪽의 높은 산 위에 넓게 펼쳐진다","mis":"SO5-1-u1-X06"},{"t":"동쪽 바닷가는 갯벌이 넓어 해안선이 들쭉날쭉하다","mis":"SO5-1-u1-X07"}],"explanation":["①은 높은 산, ②는 물줄기와 평야예요.","④는 곧은 동해안이에요.","높낮이가 모두를 이어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#24','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',4,'essay','teacher','새봄이네 수첩 ③과 ④의 바닷가를 해안선과 바닷가 땅으로 견주어 쓰고, 각각 어느 바다일지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ③과 ④의 바닷가를 해안선과 바닷가 땅으로 견주어 쓰고, 각각 어느 바다일지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ③은 해안선이 들쭉날쭉하고 섬이 많으며 바닷물이 빠지면 넓은 갯벌이 드러난다. ④는 해안선이 곧게 뻗어 있고 넓은 모래사장이 있다. 그래서 ③은 갯벌이 발달하고 해안선이 복잡한 서해안, ④는 해안선이 단순하고 모래사장이 넓은 동해안이라고 생각한다.","scoring_points":["해안선을 견주었는가","갯벌과 모래사장을 견주었는가","바다를 까닭과 함께 골랐는가"]},"explanation":["③ — 복잡·갯벌이에요.","④ — 단순·모래사장이에요.","서해안과 동해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#25','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C8',4,'essay','teacher','새봄이네 수첩 ⑦을 보고 독도의 자연환경을 생김새·날씨·생물로 나누어 쓰고, 독도 전체를 천연기념물로 지정해 보호해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑦을 보고 독도의 자연환경을 생김새·날씨·생물로 나누어 쓰고, 독도 전체를 천연기념물로 지정해 보호해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 독도는 동도와 서도 두 큰 섬과 여러 바위섬으로 이루어졌다. 날씨는 대체로 온화하지만 안개가 자주 끼고 흐린 날이 많다. 괭이갈매기 같은 새와 해국 같은 식물이 산다. 독도는 화산섬이라 연구 가치가 크고 다양한 생물이 함께 어우러진 생태계를 지녔으므로 한 가지만이 아니라 전체를 보호해야 한다.","scoring_points":["생김새를 썼는가","날씨와 생물을 썼는가","전체를 보호해야 하는 까닭을 썼는가"]},"explanation":["동도·서도·바위섬이에요.","안개가 잦아요.","생태계 전체를 지켜요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#1','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C1',1,'mc','auto','새봄이네 수첩 ②에서 아래쪽에 넓게 펼쳐진 논이 있는 땅은 어떤 지형인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ②에서 아래쪽에 넓게 펼쳐진 논이 있는 땅은 어떤 지형인가요?","options":[{"t":"평야","correct":true},{"t":"산지","mis":"SO5-1-u1-X06"},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"}],"explanation":["넓고 평평한 땅이에요.","물줄기 아래쪽에 있어요.","평야예요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#2','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C2',1,'sa','auto','지형도에서 색이 뜻하는 높이를 알려 주는 부분을 무엇이라고 하나요? (□□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"sa","stem":"지형도에서 색이 뜻하는 높이를 알려 주는 부분을 무엇이라고 하나요? (□□)","answer":["범례"],"explanation":["지도 한쪽에 있어요.","색과 높이를 짝지어요.","범례예요."],"mis":"SO5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#3','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C3',1,'mc','auto','하천 주변의 땅은 대부분 어떠한가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X02']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"하천 주변의 땅은 대부분 어떠한가요?","options":[{"t":"200 m 미만의 낮고 평평한 땅이다","correct":true},{"t":"2,000 m가 넘는 높은 땅이다","mis":"SO5-1-u1-X06"},{"t":"험한 봉우리가 이어진 땅이다","mis":"SO5-1-u1-X06"},{"t":"바다로 둘러싸인 땅이다","mis":"SO5-1-u1-X02"}],"explanation":["하천은 낮은 곳으로 흘러요.","주변도 낮아요.","평야가 발달해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#4','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C4',1,'sa','auto','우리나라는 동·서·남 몇 면이 바다와 맞닿아 있나요? (숫자로)','{}'::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"sa","stem":"우리나라는 동·서·남 몇 면이 바다와 맞닿아 있나요? (숫자로)","answer":["3","세","삼"],"explanation":["동쪽·서쪽·남쪽이에요.","세 면이에요.","삼면이 바다예요."],"mis":"SO5-1-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#5','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',1,'ox','auto','아름다운 지형은 많은 사람이 찾는 관광지가 되기도 해요.',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"ox","stem":"아름다운 지형은 많은 사람이 찾는 관광지가 되기도 해요.","answer":"O","reason_options":[{"t":"독특하고 아름다운 경관을 보려고 사람들이 찾아가기 때문에","correct":true},{"t":"지형은 관광과 아무 관계가 없기 때문에","mis":"SO5-1-u1-X09"}],"mis":"SO5-1-u1-X09","explanation":["산지·하천·해안에 관광지가 있어요.","경관이 아름다워요.","사람들이 찾아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#6','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C6',1,'sa','auto','한 지역 안에서만 여행할 때 경로를 알아보기 쉽게 표시하려고 쓰는, 그 지역만 크게 나타낸 지도를 무엇이라고 하나요? (□□□)','{}'::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"sa","stem":"한 지역 안에서만 여행할 때 경로를 알아보기 쉽게 표시하려고 쓰는, 그 지역만 크게 나타낸 지도를 무엇이라고 하나요? (□□□)","answer":["백지도"],"explanation":["하얀 바탕 지도예요.","그 지역만 크게 나와요.","백지도예요."],"mis":"SO5-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#7','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C7',1,'sa','auto','독도는 우리나라 영토의 어느 쪽 끝에 있나요? (□쪽)','{}'::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"sa","stem":"독도는 우리나라 영토의 어느 쪽 끝에 있나요? (□쪽)","answer":["동쪽","동"],"explanation":["동해에 있어요.","해가 일찍 떠요.","동쪽 끝이에요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#8','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',1,'sa','auto','독도가 그려진 가장 오래된 우리나라 옛 지도의 이름은 무엇인가요? 「□□□□」','{}'::text[],false,'{"seq":8,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"sa","stem":"독도가 그려진 가장 오래된 우리나라 옛 지도의 이름은 무엇인가요? 「□□□□」","answer":["팔도총도","「팔도총도」"],"explanation":["『신증동국여지승람』에 실렸어요.","우산도가 그려져 있어요.","「팔도총도」예요."],"mis":"SO5-1-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#9','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C2',2,'ox','auto','지형도에서 초록색으로 칠해진 땅은 진한 갈색으로 칠해진 땅보다 높아요.',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"ox","stem":"지형도에서 초록색으로 칠해진 땅은 진한 갈색으로 칠해진 땅보다 높아요.","answer":"X","reason_options":[{"t":"범례에서 진한 갈색은 높은 땅, 초록색은 낮은 땅이기 때문에","correct":true},{"t":"초록색은 언제나 가장 높은 땅을 뜻하기 때문에","mis":"SO5-1-u1-X04"}],"mis":"SO5-1-u1-X04","explanation":["범례로 확인해요.","진할수록 높아요.","초록색은 낮은 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#10','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C3',2,'ox','auto','하천은 오랜 시간 땅을 깎아 새로운 지형을 만들기도 해요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"ox","stem":"하천은 오랜 시간 땅을 깎아 새로운 지형을 만들기도 해요.","answer":"O","reason_options":[{"t":"흐르는 물이 오랜 시간 골짜기를 깎아 내기 때문에","correct":true},{"t":"하천은 땅에 아무 영향을 주지 않기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["물은 땅을 깎아요.","골짜기와 모양 지형이 생겨요.","한반도 모양 지형도 그래요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#11','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C4',2,'ox','auto','남해안은 섬이 아주 많아 다도해라고도 불러요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"ox","stem":"남해안은 섬이 아주 많아 다도해라고도 불러요.","answer":"O","reason_options":[{"t":"해안선이 복잡하고 크고 작은 섬이 많기 때문에","correct":true},{"t":"남해안에는 섬이 하나도 없기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["남해안은 섬이 많아요.","다도해라고 불러요.","해안선도 복잡해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#12','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',2,'ox','auto','파도가 바위를 깎아 만든 절벽과 동굴은 하천이 만든 경관이에요.',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"ox","stem":"파도가 바위를 깎아 만든 절벽과 동굴은 하천이 만든 경관이에요.","answer":"X","reason_options":[{"t":"바닷가에서 파도가 만든 해안의 경관이기 때문에","correct":true},{"t":"절벽과 동굴은 높은 산에서만 생기기 때문에","mis":"SO5-1-u1-X09"}],"mis":"SO5-1-u1-X09","explanation":["파도는 바다에서 쳐요.","해안의 바위를 깎아요.","해안이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#13','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C6',2,'ox','auto','여행 주제에는 정답이 없어서 내가 보고 싶은 것과 그 까닭을 생각해 정하면 돼요.',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"ox","stem":"여행 주제에는 정답이 없어서 내가 보고 싶은 것과 그 까닭을 생각해 정하면 돼요.","answer":"O","reason_options":[{"t":"내 관심이 곧 주제이고 까닭을 함께 생각하면 되기 때문에","correct":true},{"t":"선생님이 정해 준 주제만 쓸 수 있기 때문에","mis":"SO5-1-u1-X11"}],"mis":"SO5-1-u1-X11","explanation":["주제는 내가 정해요.","보고 싶은 것과 까닭을 생각해요.","정답은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#14','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C7',2,'ox','auto','독도는 우리 영토의 동쪽 경계를 알려 주는 섬이에요.',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"ox","stem":"독도는 우리 영토의 동쪽 경계를 알려 주는 섬이에요.","answer":"O","reason_options":[{"t":"우리나라 영토의 동쪽 끝에 있기 때문에","correct":true},{"t":"독도는 우리 영토의 서쪽 끝에 있기 때문에","mis":"SO5-1-u1-X14"}],"mis":"SO5-1-u1-X14","explanation":["독도는 동쪽 끝이에요.","영토의 경계를 알려요.","그래서 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#15','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C8',2,'ox','auto','독도 바다 밑에는 「불타는 얼음」이라 불리는 가스 하이드레이트가 묻혀 있어요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"ox","stem":"독도 바다 밑에는 「불타는 얼음」이라 불리는 가스 하이드레이트가 묻혀 있어요.","answer":"O","reason_options":[{"t":"고체 형태의 천연가스가 바다 밑바닥에 묻혀 있기 때문에","correct":true},{"t":"가스 하이드레이트는 바다 위에 떠다니는 얼음이기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["고체로 된 천연가스예요.","바다 밑에 있어요.","미래 에너지 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#16','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',2,'ox','auto','「태정관 지령」은 일본이 만든 문서인데도 울릉도와 독도가 일본 땅이 아니라고 밝혔어요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"ox","stem":"「태정관 지령」은 일본이 만든 문서인데도 울릉도와 독도가 일본 땅이 아니라고 밝혔어요.","answer":"O","reason_options":[{"t":"일본 스스로 두 섬이 자기 나라 땅이 아니라고 적은 국가 문서이기 때문에","correct":true},{"t":"「태정관 지령」은 우리나라가 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["일본의 국가 문서예요.","두 섬이 일본 땅이 아니라고 했어요.","그래서 더 분명한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#17','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C3',3,'error','auto','새봄이네 수첩 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"error","stem":"새봄이네 수첩 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「물줄기가 서쪽으로 간 걸 보니 서쪽 땅이 더 높아.」","correct":true,"mis_target":"SO5-1-u1-X05"},{"t":"가은 — 「물줄기 아래쪽의 논은 평야에 있어.」","mis":"SO5-1-u1-X06"},{"t":"태린 — 「계곡물은 높은 산지에서 시작했어.」","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","서쪽으로 갔다면 서쪽이 낮아요.","윤호의 말이 거꾸로예요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#18','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',3,'mc','auto','새봄이네 수첩 ⑤처럼 지질 공원에서 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑤처럼 지질 공원에서 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해설을 들으며 눈으로 보고 마음에 담되 자연물은 그대로 둔다","correct":true},{"t":"기념으로 작은 돌 조각을 가져간다","mis":"SO5-1-u1-X10"},{"t":"바위에 이름을 새겨 다녀간 표시를 한다","mis":"SO5-1-u1-X10"},{"t":"해설은 듣지 않고 사진만 찍는다","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원은 보전하는 곳이에요.","보고 배워요.","자연물은 그대로 둬요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#19','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C6',3,'mc','auto','친구의 계획서에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"친구의 계획서에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「해 질 녘 해안 사진이 정말 아름다워요. 저도 가 보고 싶어요!」","correct":true},{"t":"「이게 무슨 여행이야, 재미없겠다.」","mis":"SO5-1-u1-X12"},{"t":"「글씨가 엉망이네, 다시 써.」","mis":"SO5-1-u1-X12"},{"t":"「ㅋㅋㅋ」","mis":"SO5-1-u1-X12"}],"explanation":["느낀 점을 예의 있게 써요.","좋은 점을 칭찬해요.","놀리는 말은 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#20','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C8',3,'mc','auto','독도에 사는 새와 식물, 주변 바다 생물을 함께 지키려고 우리나라가 한 일은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X10','SO5-1-u1-X16']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도에 사는 새와 식물, 주변 바다 생물을 함께 지키려고 우리나라가 한 일은 어느 것인가요?","options":[{"t":"독도 전체를 천연기념물로 지정했다","correct":true},{"t":"독도에 큰 공항을 지었다","mis":"SO5-1-u1-X14"},{"t":"독도 바위를 캐어 박물관에 옮겼다","mis":"SO5-1-u1-X10"},{"t":"독도의 새를 모두 다른 섬으로 옮겼다","mis":"SO5-1-u1-X16"}],"explanation":["생물은 서로 이어져 있어요.","전체를 지켜야 해요.","천연기념물로 지정했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#21','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',3,'mc','auto','「조선왕국전도」와 「팔도총도」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"「조선왕국전도」와 「팔도총도」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 사람뿐 아니라 멀리 유럽 사람들도 동해에 울릉도와 독도가 있음을 알았다","correct":true},{"t":"두 지도 모두 일본에서 만들었다","mis":"SO5-1-u1-X17"},{"t":"두 지도에는 독도가 그려지지 않았다","mis":"SO5-1-u1-X17"},{"t":"유럽 사람만 독도를 알았다","mis":"SO5-1-u1-X17"}],"explanation":["「팔도총도」는 우리 지도예요.","「조선왕국전도」는 프랑스 지도예요.","두 섬을 모두 그렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#22','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C10',3,'mc','auto','정부가 독도에 선착장·주민 숙소·등대를 만든 것의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"정부가 독도에 선착장·주민 숙소·등대를 만든 것의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람이 오가고 머물며 독도를 우리 땅으로 다스리는 데 필요한 시설을 갖춘 것이다","correct":true},{"t":"독도를 다른 나라에 빌려주려는 것이다","mis":"SO5-1-u1-X18"},{"t":"독도의 바위를 캐내려는 것이다","mis":"SO5-1-u1-X10"},{"t":"독도에 아무도 오지 못하게 하려는 것이다","mis":"SO5-1-u1-X18"}],"explanation":["시설이 있어야 오갈 수 있어요.","주민과 경비대가 머물러요.","우리 땅으로 다스려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#23','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',4,'mc','auto','새봄이네 수첩 ⑥과 ⑧을 함께 볼 때 독도가 우리 땅임을 보여 주는 근거를 가장 잘 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X16','SO5-1-u1-X17']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ⑥과 ⑧을 함께 볼 때 독도가 우리 땅임을 보여 주는 근거를 가장 잘 묶은 것은 어느 것인가요?","options":[{"t":"울릉도에서 눈으로 보일 만큼 가까워 예로부터 알았고, 일본이 만든 옛 지도도 조선 땅으로 나타냈다","correct":true},{"t":"독도에는 공항이 없고 안개가 자주 낀다","mis":"SO5-1-u1-X15"},{"t":"독도는 화산섬이라 바위가 많다","mis":"SO5-1-u1-X16"},{"t":"새봄이가 독도를 알리는 그림을 그리기로 했다","mis":"SO5-1-u1-X17"}],"explanation":["⑥ — 보이는 거리예요.","⑧ — 다른 나라 지도예요.","둘 다 영토의 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#24','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',4,'essay','teacher','새봄이네 수첩 ⑤에서 지질 공원 해설사가 한 일을 쓰고, 동생의 행동이 왜 바르지 않은지 쓴 뒤, 지질 공원을 지키려고 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C5","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑤에서 지질 공원 해설사가 한 일을 쓰고, 동생의 행동이 왜 바르지 않은지 쓴 뒤, 지질 공원을 지키려고 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 해설사는 바위가 생긴 까닭과 마을의 옛이야기를 엮어 알기 쉽게 설명해 주었다. 지질 공원의 돌은 오랜 시간이 만든 단 하나뿐인 자연이라 가져가면 되돌릴 수 없으므로 동생의 행동은 바르지 않다. 나는 해설을 귀 기울여 듣고, 바위를 만지거나 가져가지 않고 눈으로만 보며, 쓰레기를 되가져오겠다.","scoring_points":["해설사가 한 일을 썼는가","동생의 행동이 바르지 않은 까닭을 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["해설사는 엮어서 설명해요.","자연물은 되돌릴 수 없어요.","보고 배우되 그대로 둬요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#25','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',4,'essay','teacher','새봄이네 수첩 ⑧에 나온 옛 지도와 사람 이야기가 각각 무엇을 말해 주는지 쓰고, 이 둘이 독도가 우리 땅이라는 근거가 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑧에 나온 옛 지도와 사람 이야기가 각각 무엇을 말해 주는지 쓰고, 이 둘이 독도가 우리 땅이라는 근거가 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 일본이 만든 옛 지도는 독도를 조선과 같은 색으로 칠해 당시 일본도 독도를 조선의 영토로 여겼음을 보여 준다. 안용복 이야기는 조선 사람이 일본에 건너가 두 섬이 조선 땅이라고 설명했고 일본도 이를 인정했음을 보여 준다. 다른 나라가 만든 자료와 옛사람의 노력 모두 독도를 우리 땅으로 나타내므로 우리 땅이라는 근거가 된다.","scoring_points":["옛 지도가 말하는 것을 썼는가","안용복 이야기가 말하는 것을 썼는가","두 가지가 근거가 되는 까닭을 썼는가"]},"explanation":["지도는 일본이 만들었어요.","안용복은 일본에 건너가 설명했어요.","둘 다 우리 땅을 보여 줘요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#1','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C1',1,'ox','auto','둘레가 바다로 둘러싸인 땅을 섬이라고 해요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"둘레가 바다로 둘러싸인 땅을 섬이라고 해요.","answer":"O","reason_options":[{"t":"사방이 바다와 맞닿아 있는 땅이기 때문에","correct":true},{"t":"섬은 하천 주변의 넓은 땅이기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["섬은 바다에 둘러싸여요.","배를 타고 가요.","독도도 섬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#2','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C2',1,'ox','auto','우리나라 땅은 북동쪽이 높고 남서쪽이 낮아요.',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"ox","stem":"우리나라 땅은 북동쪽이 높고 남서쪽이 낮아요.","answer":"O","reason_options":[{"t":"높은 산이 북쪽과 동쪽에 몰려 있기 때문에","correct":true},{"t":"높은 산이 남쪽과 서쪽에 몰려 있기 때문에","mis":"SO5-1-u1-X03"}],"mis":"SO5-1-u1-X03","explanation":["북쪽·동쪽에 높은 산이 많아요.","남쪽·서쪽은 낮아요.","북동쪽이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#3','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C3',1,'ox','auto','우리나라의 큰 하천은 대부분 북쪽과 동쪽으로 흘러요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"ox","stem":"우리나라의 큰 하천은 대부분 북쪽과 동쪽으로 흘러요.","answer":"X","reason_options":[{"t":"땅이 낮은 남쪽과 서쪽으로 흐르기 때문에","correct":true},{"t":"하천은 늘 높은 쪽으로 흐르기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["물은 낮은 곳으로 흘러요.","남쪽·서쪽이 낮아요.","그쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#4','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',1,'ox','auto','서해안은 해안선이 단순하고 섬이 거의 없어요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"ox","stem":"서해안은 해안선이 단순하고 섬이 거의 없어요.","answer":"X","reason_options":[{"t":"서해안은 해안선이 복잡하고 섬이 많기 때문에","correct":true},{"t":"서해안은 바다와 맞닿지 않았기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["서해안은 들쭉날쭉해요.","섬도 많아요.","단순한 쪽은 동해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#5','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C5',1,'mc','auto','우리나라에서 처음으로 세계 지질 공원 인증을 받은 곳은 어디인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"mc","stem":"우리나라에서 처음으로 세계 지질 공원 인증을 받은 곳은 어디인가요?","options":[{"t":"제주특별자치도","correct":true},{"t":"울릉도","mis":"SO5-1-u1-X10"},{"t":"독도","mis":"SO5-1-u1-X10"},{"t":"서울","mis":"SO5-1-u1-X10"}],"explanation":["화산섬이에요.","2010년에 인증받았어요.","제주특별자치도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#6','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',1,'ox','auto','친구의 여행 계획서에는 놀리는 댓글을 남겨도 괜찮아요.',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"ox","stem":"친구의 여행 계획서에는 놀리는 댓글을 남겨도 괜찮아요.","answer":"X","reason_options":[{"t":"온라인에서도 예절을 지켜 느낀 점과 칭찬을 써야 하기 때문에","correct":true},{"t":"온라인에서는 예절이 필요 없기 때문에","mis":"SO5-1-u1-X12"}],"mis":"SO5-1-u1-X12","explanation":["놀리는 말은 상처를 줘요.","느낀 점을 예의 있게 써요.","좋은 점을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#7','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',1,'ox','auto','새봄이네가 독도에 비행기를 타지 않고 배를 탄 것은 독도에 공항이 없기 때문이에요.',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"ox","stem":"새봄이네가 독도에 비행기를 타지 않고 배를 탄 것은 독도에 공항이 없기 때문이에요.","answer":"O","reason_options":[{"t":"공항이 없어 항구에서 배를 타고 울릉도를 거쳐 가야 하기 때문에","correct":true},{"t":"비행기 표가 비쌌기 때문일 뿐이기 때문에","mis":"SO5-1-u1-X14"}],"mis":"SO5-1-u1-X14","explanation":["독도에는 공항이 없어요.","배를 타고 가요.","울릉도를 거쳐요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#8','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C8',1,'ox','auto','독도는 오래전 바닷속 화산 활동으로 만들어졌어요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"ox","stem":"독도는 오래전 바닷속 화산 활동으로 만들어졌어요.","answer":"O","reason_options":[{"t":"바닷속에서 화산이 터져 생긴 화산섬이기 때문에","correct":true},{"t":"사람들이 흙을 쌓아 만든 섬이기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["독도는 화산섬이에요.","독특한 지형이 많아요.","연구 가치가 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#9','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C1',2,'match','auto','새봄이네 수첩의 꼭지와 그날 만난 지형을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"새봄이네 수첩의 꼭지와 그날 만난 지형을 알맞게 이으세요.","pairs":[{"l":"①","r":"산지"},{"l":"②","r":"하천과 평야"},{"l":"③","r":"갯벌이 넓은 해안"},{"l":"④","r":"모래사장이 넓은 해안"}],"mis":"SO5-1-u1-X02","explanation":["①은 높은 산이에요.","②는 물줄기와 논이에요.","③은 갯벌, ④는 모래사장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#10','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C9',2,'mc','auto','두 물줄기가 합쳐지는 강가 마을과 지평선이 보이는 평야의 공통점은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"두 물줄기가 합쳐지는 강가 마을과 지평선이 보이는 평야의 공통점은 어느 것인가요?","options":[{"t":"둘 다 하천과 관계있는 경관이다","correct":true},{"t":"둘 다 높은 산지에 있다","mis":"SO5-1-u1-X09"},{"t":"둘 다 바다와 맞닿아 있다","mis":"SO5-1-u1-X09"},{"t":"둘 다 화산이 만든 섬이다","mis":"SO5-1-u1-X09"}],"explanation":["강가 마을은 하천이에요.","평야는 하천 주변에 생겨요.","둘 다 하천과 관계있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#11','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',2,'mc','auto','갯벌을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X09','SO5-1-u1-X06']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"갯벌을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?","options":[{"t":"서해안","correct":true},{"t":"동해안","mis":"SO5-1-u1-X07"},{"t":"높은 산지","mis":"SO5-1-u1-X09"},{"t":"하천의 상류","mis":"SO5-1-u1-X06"}],"explanation":["갯벌을 막는 일이에요.","갯벌은 서해안에 넓어요.","간척이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#12','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C5',2,'match','auto','경관과 그 경관을 만든 지형을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"match","stem":"경관과 그 경관을 만든 지형을 알맞게 이으세요.","pairs":[{"l":"바위 봉우리와 폭포가 있는 산","r":"산지"},{"l":"지평선이 보이는 들판","r":"평야"},{"l":"갯벌과 갈대밭이 펼쳐진 습지","r":"해안"}],"mis":"SO5-1-u1-X09","explanation":["봉우리와 폭포는 산지예요.","넓은 들판은 평야예요.","갯벌과 갈대밭은 해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#13','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',2,'sa','auto','여행 계획서를 사진으로 찍어 올려 친구들과 나눌 때 쓰는 도구를 무엇이라고 하나요? (□□ □□□□□□)','{}'::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"sa","stem":"여행 계획서를 사진으로 찍어 올려 친구들과 나눌 때 쓰는 도구를 무엇이라고 하나요? (□□ □□□□□□)","answer":["공유 애플리케이션","공유애플리케이션","공유 앱"],"explanation":["함께 나누는 도구예요.","자리에서 언제든 볼 수 있어요.","공유 애플리케이션이에요."],"mis":"SO5-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#14','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',2,'sa','auto','독도가 있는 바다의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"sa","stem":"독도가 있는 바다의 이름을 두 글자로 쓰세요.","answer":["동해"],"explanation":["우리나라 동쪽 바다예요.","세 나라가 둘러싸요.","동해예요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#15','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C8',2,'match','auto','독도에서 볼 수 있는 것과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"match","stem":"독도에서 볼 수 있는 것과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"괭이갈매기","r":"새"},{"l":"해국","r":"식물"},{"l":"해양 심층수","r":"바다 자원"}],"mis":"SO5-1-u1-X16","explanation":["괭이갈매기는 새예요.","해국은 바위에 피는 식물이에요.","해양 심층수는 바다 자원이에요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#16','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C10',2,'mc','auto','홍순칠과 울릉도 청년들이 독도를 지키려고 만든 모임은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"홍순칠과 울릉도 청년들이 독도를 지키려고 만든 모임은 어느 것인가요?","options":[{"t":"독도 의용 수비대","correct":true},{"t":"독도 경비대","mis":"SO5-1-u1-X18"},{"t":"사이버 외교 사절단","mis":"SO5-1-u1-X18"},{"t":"지질 공원 해설단","mis":"SO5-1-u1-X10"}],"explanation":["울릉도 청년들이 함께했어요.","스스로 독도를 지켰어요.","독도 의용 수비대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#17','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C3',3,'ox','auto','평야가 하천 주변에 발달한 것과 우리나라 땅이 북동쪽은 높고 남서쪽은 낮은 것은 서로 관계가 있어요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"ox","stem":"평야가 하천 주변에 발달한 것과 우리나라 땅이 북동쪽은 높고 남서쪽은 낮은 것은 서로 관계가 있어요.","answer":"O","reason_options":[{"t":"높낮이가 하천의 방향을 정하고 하천이 흐르는 낮은 땅 주변에 평야가 펼쳐지기 때문에","correct":true},{"t":"평야는 땅의 높낮이와 상관없이 아무 데나 생기기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["높낮이 → 하천의 방향이에요.","하천이 흐르는 곳은 낮아요.","그 주변에 평야가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#18','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',3,'ox','auto','해안의 모습에 따라 해산물을 얻는 곳, 해수욕장, 간척지처럼 사람들의 생활 모습이 달라져요.',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"ox","stem":"해안의 모습에 따라 해산물을 얻는 곳, 해수욕장, 간척지처럼 사람들의 생활 모습이 달라져요.","answer":"O","reason_options":[{"t":"갯벌·모래사장 같은 해안 지형을 생활에 맞게 이용하기 때문에","correct":true},{"t":"해안 사람들은 지형과 상관없이 똑같이 살기 때문에","mis":"SO5-1-u1-X08"}],"mis":"SO5-1-u1-X08","explanation":["지형에 맞게 살아요.","갯벌에서는 해산물, 모래사장에서는 해수욕이에요.","간척도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#19','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',3,'ox','auto','새봄이네처럼 여러 지역을 두루 다니는 여행은 우리나라 전체 지도에, 한 지역 안의 여행은 그 지역 백지도에 경로를 그리는 것이 알맞아요.',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"ox","stem":"새봄이네처럼 여러 지역을 두루 다니는 여행은 우리나라 전체 지도에, 한 지역 안의 여행은 그 지역 백지도에 경로를 그리는 것이 알맞아요.","answer":"O","reason_options":[{"t":"경로의 넓이에 맞는 지도를 써야 알아보기 쉽기 때문에","correct":true},{"t":"어떤 여행이든 지도는 쓰지 않는 것이 좋기 때문에","mis":"SO5-1-u1-X11"}],"mis":"SO5-1-u1-X11","explanation":["넓은 여행은 전국 지도예요.","좁은 여행은 그 지역 백지도예요.","알아보기 쉬운 지도를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#20','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',3,'ox','auto','독도 주변 바다는 어업을 하는 우리 국민을 보호하고 배가 급할 때 대피할 수 있는 곳이기도 해요.',ARRAY['SO5-1-u1-X15']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"ox","stem":"독도 주변 바다는 어업을 하는 우리 국민을 보호하고 배가 급할 때 대피할 수 있는 곳이기도 해요.","answer":"O","reason_options":[{"t":"동해 한가운데의 섬이라 바다에서 일하는 사람들을 지켜 줄 수 있기 때문에","correct":true},{"t":"독도 주변에서는 배가 다닐 수 없기 때문에","mis":"SO5-1-u1-X15"}],"mis":"SO5-1-u1-X15","explanation":["독도는 바다 한가운데예요.","어업하는 국민을 지켜요.","급할 때 피할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#21','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C9',3,'ox','auto','대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 것은 독도가 우리 땅임을 나라가 분명히 밝힌 기록이에요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"ox","stem":"대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 것은 독도가 우리 땅임을 나라가 분명히 밝힌 기록이에요.","answer":"O","reason_options":[{"t":"나라가 공식 문서로 독도를 다스리는 곳을 정했기 때문에","correct":true},{"t":"칙령은 다른 나라가 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["칙령은 나라의 명령이에요.","울릉군이 독도를 다스려요.","10월 25일 독도의 날이 됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#22','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C11',3,'ox','auto','인공지능으로 만든 그림이 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만들면 돼요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"ox","stem":"인공지능으로 만든 그림이 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만들면 돼요.","answer":"O","reason_options":[{"t":"조건을 고칠수록 원하는 그림에 가까워지기 때문에","correct":true},{"t":"한 번 만든 그림은 다시 만들 수 없기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["고칠 수 있는 것은 조건이에요.","여러 번 다시 만들어요.","마음에 들 때까지 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#23','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C10',4,'mc','auto','새봄이네 수첩 ⑦과 ⑧을 함께 볼 때 독도를 지키는 사람들을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ⑦과 ⑧을 함께 볼 때 독도를 지키는 사람들을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"옛날의 안용복부터 오늘의 독도 경비대, 그리고 독도를 알리려는 새봄이까지 모두가 지킨다","correct":true},{"t":"독도 경비대 혼자서만 지킨다","mis":"SO5-1-u1-X18"},{"t":"옛날 사람들만 지켰고 지금은 아무도 지키지 않는다","mis":"SO5-1-u1-X18"},{"t":"관광객은 독도를 지키는 일과 관계없다","mis":"SO5-1-u1-X18"}],"explanation":["옛사람과 오늘의 경비대가 있어요.","새봄이도 알리기로 했어요.","모두가 함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#24','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',4,'essay','teacher','새봄이네 수첩 ①~④를 참고해 「여러 지형을 만나는 국토 여행」 계획을 세우세요. 주제와 까닭, 여행지 두 곳과 지형, 경로를 정할 때 생각할 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ①~④를 참고해 「여러 지형을 만나는 국토 여행」 계획을 세우세요. 주제와 까닭, 여행지 두 곳과 지형, 경로를 정할 때 생각할 점을 쓰세요.","answer_guide":{"answer":"예: 나의 주제는 「산에서 바다까지 물을 따라가는 여행」이다. 땅의 높낮이가 지형을 어떻게 만드는지 직접 보고 싶기 때문이다. 먼저 북동쪽의 높은 산지에서 계곡을 보고, 물줄기를 따라 내려가 넓은 평야를 본 뒤 서해안의 갯벌에 가겠다. 경로는 이동 거리가 너무 길어지지 않게 물이 흐르는 차례에 맞추어 화살표로 잇겠다.","scoring_points":["주제와 까닭을 썼는가","여행지와 지형을 맞게 썼는가","경로를 정할 때 생각할 점을 썼는가"]},"explanation":["주제를 먼저 정해요.","여행지의 지형을 써요.","동선과 목적을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#25','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C11',4,'essay','teacher','새봄이처럼 독도를 알리는 그림을 인공지능으로 만든다고 생각하고, 그림 이름과 자세한 조건 세 가지를 쓴 뒤, 친구들에게 소개할 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C11","difficulty":4,"kind":"essay","stem":"새봄이처럼 독도를 알리는 그림을 인공지능으로 만든다고 생각하고, 그림 이름과 자세한 조건 세 가지를 쓴 뒤, 친구들에게 소개할 말을 쓰세요.","answer_guide":{"answer":"예: 그림 이름은 「안개 걷힌 아침의 독도」이다. 조건은 ① 동도와 서도가 나란히 보이는 바다, ② 하늘을 나는 괭이갈매기 무리, ③ 바위에 핀 해국과 사철나무이다. 소개할 말: 「제 그림의 이름은 「안개 걷힌 아침의 독도」입니다. 동도와 서도, 괭이갈매기, 바위에 핀 해국을 조건으로 독도의 아름다운 자연을 표현했습니다.」","scoring_points":["그림 이름을 붙였는가","독도에 맞는 자세한 조건 세 가지를 썼는가","조건과 표현한 것을 넣어 소개했는가"]},"explanation":["이름을 붙여요.","조건은 자세하게 써요.","무엇을 표현했는지 소개해요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
